{
  "name": "NTP Stat",
  "description": "A high-fidelity tennis match statistics and tracking application with advanced point logging, player profiles, and detailed data visualization.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type HittingArm = 'Left' | 'Right';
export type BackhandType = 'One-Handed' | 'Two-Handed';
export type Outcome = 'Ace' | 'Winner' | 'Unforced Error' | 'Forced Error' | 'Double Fault' | 'Service Winner';
export type ShotKind = 'Regular' | 'Return' | 'Passing' | 'Approach' | 'Slice' | 'Volley' | 'Drop Shot' | 'Lob' | 'Overhead';
export type ShotLocation = 'Cross Court' | 'Middle' | 'Down the Line';
export type ErrorType = 'Long' | 'Net' | 'Wide';
export type ServePlacement = 'T' | 'Body' | 'Wide';
export type CourtSurface = 'Hard' | 'Clay' | 'Grass';
export type CourtSpeed = 'Slow' | 'Neutral' | 'Fast';
export type CourtType = 'Indoor' | 'Outdoor';
export type ScoringType = 'Simple' | 'Shot Stats';

export interface Player {
  id: string;
  name: string;
  team: string;
  hittingArm: HittingArm;
  backhand: BackhandType;
  utrRating: number;
  isSaved: boolean;
}

export interface Point {
  winnerId: string;
  loserId: string;
  outcome: Outcome;
  serverPlayerId: string;
  serveNumber: 1 | 2;
  shotSide?: 'Forehand' | 'Backhand';
  shotKind?: ShotKind;
  location?: ShotLocation;
  errorType?: ErrorType;
  servePlacement?: ServePlacement;
  rallyLength: number;
  scoreAtStart: {
    p1Points: string;
    p2Points: string;
    p1Games: number;
    p2Games: number;
    p1Sets: number;
    p2Sets: number;
  };
}

export interface MatchConfig {
  p1Id: string;
  p2Id: string;
  initialServerId: string;
  scoringType: ScoringType;
  adScoring: boolean;
  tieBreak: boolean;
  setsToWin: 1 | 3 | 5 | 'Pro Set' | 'Fast4';
  gamesPerSet: number;
  courtSurface: CourtSurface;
  courtSpeed: CourtSpeed;
  courtType: CourtType;
  description: string;
  city: string;
  state: string;
  temperature: string;
  humidity: string;
}

export interface Match {
  id: string;
  date: string;
  config: MatchConfig;
  points: Point[];
  isCompleted: boolean;
  finalScore: string;
}

export enum Tab {
  Matches = 'Matches',
  Players = 'Players',
  Active = 'Active'
}

import React from 'react';

