import { Point, MatchConfig, Outcome } from '../types';

export const POINT_VALUES = ['0', '15', '30', '40', 'Ad'];

export interface CurrentScore {
  p1Points: string;
  p2Points: string;
  p1Games: number;
  p2Games: number;
  p1Sets: number;
  p2Sets: number;
  servingPlayerId: string;
  isGameOver: boolean;
  isSetOver: boolean;
  isMatchOver: boolean;
}

export function calculateNewScore(
  current: CurrentScore,
  winnerId: string,
  p1Id: string,
  p2Id: string,
  config: MatchConfig
): CurrentScore {
  let { p1Points, p2Points, p1Games, p2Games, p1Sets, p2Sets, servingPlayerId } = current;
  const isP1 = winnerId === p1Id;

  // Point logic
  if (config.adScoring) {
    if (isP1) {
      if (p1Points === '40') {
        if (p2Points === 'Ad') p2Points = '40';
        else if (p2Points === '40') p1Points = 'Ad';
        else return awardGame(current, p1Id, p1Id, p2Id, config);
      } else if (p1Points === 'Ad') {
        return awardGame(current, p1Id, p1Id, p2Id, config);
      } else {
        p1Points = nextPoint(p1Points);
      }
    } else {
      if (p2Points === '40') {
        if (p1Points === 'Ad') p1Points = '40';
        else if (p1Points === '40') p2Points = 'Ad';
        else return awardGame(current, p2Id, p1Id, p2Id, config);
      } else if (p2Points === 'Ad') {
        return awardGame(current, p2Id, p1Id, p2Id, config);
      } else {
        p2Points = nextPoint(p2Points);
      }
    }
  } else {
    // No-Ad logic
    if (isP1) {
      if (p1Points === '40') return awardGame(current, p1Id, p1Id, p2Id, config);
      p1Points = nextPoint(p1Points);
    } else {
      if (p2Points === '40') return awardGame(current, p2Id, p1Id, p2Id, config);
      p2Points = nextPoint(p2Points);
    }
  }

  return { ...current, p1Points, p2Points };
}

function nextPoint(p: string): string {
  if (p === '0') return '15';
  if (p === '15') return '30';
  if (p === '30') return '40';
  return '0';
}

function awardGame(current: CurrentScore, winnerId: string, p1Id: string, p2Id: string, config: MatchConfig): CurrentScore {
  let { p1Games, p2Games, p1Sets, p2Sets, servingPlayerId } = current;
  if (winnerId === p1Id) p1Games++; else p2Games++;

  // Reset points
  const p1Points = '0';
  const p2Points = '0';

  // Toggle server
  servingPlayerId = servingPlayerId === p1Id ? p2Id : p1Id;

  // Set logic
  const gamesNeeded = config.gamesPerSet;
  if (p1Games >= gamesNeeded && p1Games - p2Games >= 2) {
    p1Sets++;
    p1Games = 0;
    p2Games = 0;
  } else if (p2Games >= gamesNeeded && p2Games - p1Games >= 2) {
    p2Sets++;
    p1Games = 0;
    p2Games = 0;
  }

  // Special Pro Set / Fast4 could be added here

  const setsToWin = typeof config.setsToWin === 'number' ? Math.ceil(config.setsToWin / 2) : 1;
  const isMatchOver = p1Sets >= setsToWin || p2Sets >= setsToWin;

  return { ...current, p1Points, p2Points, p1Games, p2Games, p1Sets, p2Sets, servingPlayerId, isMatchOver };
}

export function calculateStats(points: Point[], p1Id: string, p2Id: string) {
  const stats = (playerId: string) => {
    const pPoints = points.filter(p => p.serverPlayerId === playerId);
    const totalPointsPlayed = points.length;
    const pointsWon = points.filter(p => p.winnerId === playerId).length;
    const firstServesIn = pPoints.filter(p => p.serveNumber === 1 && p.outcome !== 'Double Fault').length;
    const aces = points.filter(p => p.winnerId === playerId && p.outcome === 'Ace').length;
    const winners = points.filter(p => p.winnerId === playerId && p.outcome === 'Winner').length;
    const unforcedErrors = points.filter(p => p.loserId === playerId && p.outcome === 'Unforced Error').length;
    const forcedErrors = points.filter(p => p.loserId === playerId && p.outcome === 'Forced Error').length;

    return {
      firstServePct: pPoints.length ? (firstServesIn / pPoints.length) * 100 : 0,
      aces,
      winners,
      unforcedErrors,
      forcedErrors,
      totalPointsWon: pointsWon,
      totalPointsWonPct: totalPointsPlayed ? (pointsWon / totalPointsPlayed) * 100 : 0,
    };
  };

  return {
    p1: stats(p1Id),
    p2: stats(p2Id)
  };
}

import React from 'react';
import { Match, Player } from '../types';
import { Card, Header } from '../components/UI';

interface MatchesViewProps {
  matches: Match[];
  players: Player[];
  onNewMatch: () => void;
  onAddPlayer: () => void;
}

const MatchesView: React.FC<MatchesViewProps> = ({ matches, players, onNewMatch, onAddPlayer }) => {
  const [showMenu, setShowMenu] = React.useState(false);

  return (
    <div>
      <Header 
        title="Matches" 
        leftAction={<i className="fa-solid fa-circle-notch text-xl"></i>}
        rightAction={
          <div className="relative">
            <button onClick={() => setShowMenu(!showMenu)}><i className="fa-solid fa-plus"></i></button>
            {showMenu && (
              <div className="absolute right-0 top-10 w-48 bg-white border border-iosDivider rounded-lg shadow-xl py-1 z-50">
                <button onClick={() => { onNewMatch(); setShowMenu(false); }} className="w-full text-left px-4 py-3 text-sm border-b border-iosDivider hover:bg-iosBg">New Match</button>
                <button onClick={() => { setShowMenu(false); }} className="w-full text-left px-4 py-3 text-sm border-b border-iosDivider hover:bg-iosBg">Enter Match Score</button>
                <button onClick={() => { onAddPlayer(); setShowMenu(false); }} className="w-full text-left px-4 py-3 text-sm hover:bg-iosBg">Add New Player</button>
              </div>
            )}
          </div>
        }
      />

      <div className="p-4 space-y-4">
        {matches.length === 0 ? (
          <div className="text-center py-20 text-iosGray">
            <p>No matches yet.</p>
            <button onClick={onNewMatch} className="mt-4 text-primary font-semibold">Start your first match</button>
          </div>
        ) : (
          matches.map(match => {
            const p1 = players.find(p => p.id === match.config.p1Id);
            const p2 = players.find(p => p.id === match.config.p2Id);
            return (
              <Card key={match.id}>
                <div className="bg-primary text-white px-4 py-2 text-sm font-semibold">
                  {new Date(match.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}
                </div>
                <div className="p-4 space-y-2">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-xs font-bold">
                            {p1?.name[0] || '1'}
                        </div>
                        <span className="font-medium">{p1?.name || 'Player 1'}</span>
                    </div>
                    <span className="font-bold">{match.finalScore.split('-')[0] || 0}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-xs font-bold">
                            {p2?.name[0] || '2'}
                        </div>
                        <span className="font-medium">{p2?.name || 'Player 2'}</span>
                    </div>
                    <span className="font-bold">{match.finalScore.split('-')[1] || 0}</span>
                  </div>
                </div>
              </Card>
            );
          })
        )}
      </div>
    </div>
  );
};

export default MatchesView;

