import React from 'react';
import { Player, MatchConfig, CourtSurface, CourtSpeed, CourtType, ScoringType } from '../types';
import { Header, SegmentedControl, Card } from '../components/UI';

interface SetupViewProps {
  players: Player[];
  onStartMatch: (config: MatchConfig) => void;
  onCancel: () => void;
}

const SetupView: React.FC<SetupViewProps> = ({ players, onStartMatch, onCancel }) => {
  const [matchType, setMatchType] = React.useState<'Singles' | 'Doubles'>('Singles');
  const [p1Id, setP1Id] = React.useState('');
  const [p2Id, setP2Id] = React.useState('');
  const [serverId, setServerId] = React.useState('');
  const [scoringType, setScoringType] = React.useState<ScoringType>('Shot Stats');
  const [adScoring, setAdScoring] = React.useState(true);
  const [tieBreak, setTieBreak] = React.useState(true);
  const [numSets, setNumSets] = React.useState<any>(1);
  const [gamesPerSet, setGamesPerSet] = React.useState(6);
  const [surface, setSurface] = React.useState<CourtSurface>('Hard');
  const [speed, setSpeed] = React.useState<CourtSpeed>('Neutral');
  const [type, setType] = React.useState<CourtType>('Outdoor');

  const [description, setDescription] = React.useState('');
  const [city, setCity] = React.useState('');
  const [state, setState] = React.useState('');
  const [temp, setTemp] = React.useState('');
  const [humidity, setHumidity] = React.useState('');

  const canStart = p1Id && p2Id && serverId;

  const handleStart = () => {
    onStartMatch({
      p1Id,
      p2Id,
      initialServerId: serverId,
      scoringType,
      adScoring,
      tieBreak,
      setsToWin: numSets,
      gamesPerSet,
      courtSurface: surface,
      courtSpeed: speed,
      courtType: type,
      description,
      city,
      state,
      temperature: temp,
      humidity
    });
  };

  return (
    <div className="min-h-screen bg-iosBg pb-20">
      <header className="sticky top-0 bg-iosBg/80 backdrop-blur-md px-4 pt-10 pb-4 flex justify-between items-center z-50">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-medium">
          <i className="fa-solid fa-chevron-left"></i> Matches
        </button>
        <button 
          onClick={handleStart} 
          disabled={!canStart}
          className={`font-semibold ${canStart ? 'text-primary' : 'text-iosGray opacity-50'}`}
        >
          Start Match
        </button>
      </header>

      <div className="px-4 space-y-6">
        <section>
          <label className="text-[10px] uppercase font-bold text-iosGray ml-4 mb-2 block">Match Type</label>
          <Card className="p-4 space-y-4">
            <SegmentedControl
              options={[{ label: 'Singles', value: 'Singles' }, { label: 'Doubles', value: 'Doubles' }]}
              value={matchType}
              onChange={setMatchType}
            />
            <p className="text-xs text-primary text-center">Get MatchTrack Pro to score doubles</p>
          </section>

          <section className="mt-6">
            <label className="text-[10px] uppercase font-bold text-iosGray ml-4 mb-2 block">Players</label>
            <Card>
              <button className="w-full text-left px-4 py-3 text-primary font-medium border-b border-iosDivider/50">Add New Player</button>
              <div className="p-4 space-y-4">
                <select 
                  value={p1Id} 
                  onChange={(e) => setP1Id(e.target.value)}
                  className="w-full bg-iosBg p-3 rounded-lg text-sm border-none focus:ring-1 focus:ring-primary outline-none"
                >
                  <option value="">Player One</option>
                  {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
                <select 
                  value={p2Id} 
                  onChange={(e) => setP2Id(e.target.value)}
                  className="w-full bg-iosBg p-3 rounded-lg text-sm border-none focus:ring-1 focus:ring-primary outline-none"
                >
                  <option value="">Player Two</option>
                  {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>

                <div className="flex bg-iosBg p-1 rounded-lg">
                   <button 
                     onClick={() => p1Id && setServerId(p1Id)}
                     className={`flex-1 py-2 text-xs font-semibold rounded-md ${serverId === p1Id ? 'bg-white shadow-sm' : 'text-iosGray'}`}
                   >
                     {p1Id ? `${players.find(p=>p.id===p1Id)?.name} Serving` : 'Player 1 Serving'}
                   </button>
                   <button 
                     onClick={() => p2Id && setServerId(p2Id)}
                     className={`flex-1 py-2 text-xs font-semibold rounded-md ${serverId === p2Id ? 'bg-white shadow-sm' : 'text-iosGray'}`}
                   >
                     {p2Id ? `${players.find(p=>p.id===p2Id)?.name} Serving` : 'Player 2 Serving'}
                   </button>
                </div>
              </div>
            </Card>
          </section>

          <section className="mt-6">
            <label className="text-[10px] uppercase font-bold text-iosGray ml-4 mb-2 block">Number of Sets</label>
            <Card className="p-4 space-y-4">
              <SegmentedControl
                options={[
                  { label: '1', value: 1 },
                  { label: '3', value: 3 },
                  { label: '5', value: 5 },
                  { label: 'Pro Set', value: 'Pro Set' },
                  { label: 'Fast4', value: 'Fast4' }
                ]}
                value={numSets}
                onChange={setNumSets}
              />
              <p className="text-xs text-primary text-center">Get MatchTrack Pro to select number of sets</p>
            </Card>
          </section>

          <section className="mt-6">
            <label className="text-[10px] uppercase font-bold text-iosGray ml-4 mb-2 block">Number of Games per Set</label>
            <Card className="p-4 pt-6">
              <input 
                type="range" 
                min="2" 
                max="10" 
                value={gamesPerSet} 
                onChange={(e) => setGamesPerSet(parseInt(e.target.value))}
