import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, POINT_VALUES } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  onFinish: (points: Point[]) => void;
  onCancel: () => void;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ config, players, onFinish, onCancel }) => {
  const [points, setPoints] = React.useState<Point[]>([]);
  const [score, setScore] = React.useState<CurrentScore>({
    p1Points: '0',
    p2Points: '0',
    p1Games: 0,
    p2Games: 0,
    p1Sets: 0,
    p2Sets: 0,
    servingPlayerId: config.initialServerId,
    isGameOver: false,
    isSetOver: false,
    isMatchOver: false,
  });
  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Point Modal State
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    setPointModal({ show: true, winnerId, loserId });
  };

  const handleSavePoint = () => {
    if (!outcome) return;

    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);

    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);

    // Reset Modal
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setRallyLength(0);
    setServeNumber(1);

    if (newScore.isMatchOver) {
      onFinish(newPoints);
    }
  };

  return (
    <div className="flex flex-col h-full bg-iosBg">
      {/* Header */}
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20">
        <button onClick={onCancel} className="text-primary flex items-center gap-1">
          <i className="fa-solid fa-chevron-left"></i> Matches
        </button>
        <div className="flex items-center gap-3">
            <i className="fa-solid fa-tower-broadcast text-primary"></i>
            <i className="fa-solid fa-rotate-left text-primary"></i>
            <i className="fa-solid fa-ellipsis text-primary"></i>
        </div>
      </header>

      {/* Mini Score Card */}
      <div className="p-4">
        <Card className="p-0">
          <div className="bg-primary text-white px-4 py-2 text-sm font-semibold">
            25 January 2026
          </div>
          <div className="p-4 space-y-2">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">J</div>
                <span className="text-sm font-medium">{p1.name}</span>
              </div>
              <span className="font-bold">{score.p1Sets}</span>
            </div>
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">S</div>
                <span className="text-sm font-medium">{p2.name}</span>
              </div>
              <span className="font-bold">{score.p2Sets}</span>
            </div>
          </div>
        </Card>
      </div>

      {/* Live Scoreboard */}
      <div className="px-6 pb-6 pt-2 flex justify-between relative">
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
          {score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute -left-2 top-2"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p1.name}</span>
          <span className="text-8xl scoreboard-font text-primary">{score.p1Points}</span>
        </div>
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
          {score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-[calc(50%-100px)] top-2"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p2.name}</span>
          <span className="text-8xl scoreboard-font text-black">{score.p2Points}</span>
        </div>
      </div>

      {/* Serve Toggle */}
      <div className="px-4 mb-4">
        <SegmentedControl
          options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
          value={serveNumber}
          onChange={(v: any) => setServeNumber(v)}
        />
      </div>

      {/* Sub Navigation */}
      <div className="flex justify-between px-6 py-2 items-center border-t border-b border-iosDivider/20 mb-4 bg-white/50 backdrop-blur-sm">
        <i className="fa-solid fa-magnifying-glass text-primary"></i>
        <div className="flex gap-4">
            <button onClick={() => setActiveSubTab('Match Stats')} className={`text-sm font-bold ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray'}`}>Match Stats</button>
            <button onClick={() => setActiveSubTab('Shot Stats')} className={`text-sm font-bold ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray'}`}>Shot Stats</button>
            <button onClick={() => setActiveSubTab('Match Log')} className={`text-sm font-bold ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray'}`}>Match Log</button>
        </div>
        <i className="fa-solid fa-chart-simple text-primary"></i>
      </div>

      {/* Sub Tab Content */}
      <div className="flex-1 overflow-y-auto px-4 pb-24">
        {activeSubTab === 'Match Stats' && (
          <Card className="divide-y divide-iosDivider/30">
            <StatRow label="1st Serve %" val1={stats.p1.firstServePct.toFixed(2) + '%'} val2={stats.p2.firstServePct.toFixed(2) + '%'} />
            <StatRow label="Aces" val1={stats.p1.aces} val2={stats.p2.aces} />
            <StatRow label="Winners" val1={stats.p1.winners} val2={stats.p2.winners} />
            <StatRow label="Unforced Errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
            <StatRow label="Forced Errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
            <StatRow label="Total Points Won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
            <StatRow label="Total Points Won %" val1={stats.p1.totalPointsWonPct.toFixed(2) + '%'} val2={stats.p2.totalPointsWonPct.toFixed(2) + '%'} />
          </Card>
        )}

        {activeSubTab === 'Shot Stats' && (
          <div className="space-y-6">
            <section>
                <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-2">Winners</h4>
                <Card className="divide-y divide-iosDivider/30">
                    <StatRow label="Forehand" val1={points.filter(p=>p.winnerId===p1.id && p.outcome==='Winner' && p.shotSide==='Forehand').length} val2={points.filter(p=>p.winnerId===p2.id && p.outcome==='Winner' && p.shotSide==='Forehand').length} />
                    <StatRow label="Backhand" val1={points.filter(p=>p.winnerId===p1.id && p.outcome==='Winner' && p.shotSide==='Backhand').length} val2={points.filter(p=>p.winnerId===p2.id && p.outcome==='Winner' && p.shotSide==='Backhand').length} />
                </Card>
            </section>
            <section>
                <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-2">Unforced Errors</h4>
                <Card className="divide-y divide-iosDivider/30">
                    <StatRow label="Forehand" val1={points.filter(p=>p.loserId===p1.id && p.outcome==='Unforced Error' && p.shotSide==='Forehand').length} val2={points.filter(p=>p.loserId===p2.id && p.outcome==='Unforced Error' && p.shotSide==='Forehand').length} />
                    <StatRow label="Backhand" val1={points.filter(p=>p.loserId===p1.id && p.outcome==='Unforced Error' && p.shotSide==='Backhand').length} val2={points.filter(p=>p.loserId===p2.id && p.outcome==='Unforced Error' && p.shotSide==='Backhand').length} />
