            </section>
          </div>
        )}

        {activeSubTab === 'Match Log' && (
           <div className="space-y-2">
             {points.slice().reverse().map((p, i) => {
               const winner = players.find(pl => pl.id === p.winnerId);
               const loser = players.find(pl => pl.id === p.loserId);
               const server = players.find(pl => pl.id === p.serverPlayerId);
               return (
                 <div key={i} className="flex gap-4 p-3 bg-white border border-iosDivider/30 rounded-xl items-center">
