                   >
                     {l}
                   </button>
                 ))}
              </div>

              {(outcome === 'Unforced Error' || outcome === 'Forced Error') && (
                <>
                  <h3 className="text-sm text-center font-medium mb-4">How was the shot an error?</h3>
                  <div className="flex gap-2 mb-8">
                    {['Long', 'Net', 'Wide'].map((e: any) => (
                      <button 
