                      </button>
                    ))}
                  </div>
                </>
              )}
            </div>
          )}

          <div className="mt-4 mb-10">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-semibold">Rally Length:</span>
              <div className="flex items-center gap-4 text-primary font-bold">
                 <button onClick={() => setRallyLength(Math.max(0, rallyLength-1))} className="text-2xl">-</button>
                 <span className="text-lg w-4 text-center">{rallyLength}</span>
                 <button onClick={() => setRallyLength(rallyLength+1)} className="text-2xl">+</button>
              </div>
            </div>
            <input type="range" min="0" max="30" value={rallyLength} onChange={e=>setRallyLength(parseInt(e.target.value))} className="w-full accent-primary" />
