import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, POINT_VALUES } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  onFinish: (points: Point[]) => void;
  onCancel: () => void;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ config, players, onFinish, onCancel }) => {
  const [points, setPoints] = React.useState<Point[]>([]);
  const [score, setScore] = React.useState<CurrentScore>({
    p1Points: '0',
    p2Points: '0',
    p1Games: 0,
    p2Games: 0,
    p1Sets: 0,
    p2Sets: 0,
    servingPlayerId: config.initialServerId,
    isGameOver: false,
    isSetOver: false,
    isMatchOver: false,
  });
  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Point Modal State
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    setPointModal({ show: true, winnerId, loserId });
  };

  const handleSavePoint = () => {
    if (!outcome) return;

    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);

    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);

    // Reset Modal
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setRallyLength(0);
    setServeNumber(1);

    if (newScore.isMatchOver) {
      onFinish(newPoints);
    }
  };

  // Logic for which outcomes to show
  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  return (
    <div className="flex flex-col h-full bg-iosBg">
      {/* Header */}
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-3">
            <i className="fa-solid fa-tower-broadcast text-primary"></i>
            <i className="fa-solid fa-rotate-left text-primary"></i>
            <i className="fa-solid fa-ellipsis text-primary"></i>
        </div>
      </header>

      {/* Mini Score Card */}
      <div className="p-4">
        <Card className="p-0">
          <div className="bg-primary text-white px-4 py-2 text-sm font-semibold">
            {new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}
          </div>
          <div className="p-4 space-y-2">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">
                  {p1.name[0]}
                </div>
                <span className="text-sm font-medium">{p1.name}</span>
              </div>
              <span className="font-bold">{score.p1Sets}</span>
            </div>
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">
                  {p2.name[0]}
                </div>
                <span className="text-sm font-medium">{p2.name}</span>
              </div>
              <span className="font-bold">{score.p2Sets}</span>
            </div>
          </div>
        </Card>
      </div>

      {/* Live Scoreboard */}
      <div className="px-6 pb-6 pt-2 flex justify-between relative">
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
          {score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute -left-2 top-2"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p1.name}</span>
          <span className="text-8xl scoreboard-font text-primary">{score.p1Points}</span>
        </div>
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
          {score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-[calc(50%-100px)] top-2"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p2.name}</span>
          <span className="text-8xl scoreboard-font text-black">{score.p2Points}</span>
        </div>
      </div>

      {/* Serve Toggle */}
      <div className="px-4 mb-4">
        <SegmentedControl
          options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
          value={serveNumber}
          onChange={(v: any) => setServeNumber(v)}
        />
      </div>

      {/* Sub Navigation */}
      <div className="flex justify-between px-6 py-2 items-center border-t border-b border-iosDivider/20 mb-4 bg-white/50 backdrop-blur-sm">
        <i className="fa-solid fa-magnifying-glass text-primary"></i>
        <div className="flex gap-4">
            <button onClick={() => setActiveSubTab('Match Stats')} className={`text-sm font-bold ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray'}`}>Match Stats</button>
            <button onClick={() => setActiveSubTab('Shot Stats')} className={`text-sm font-bold ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray'}`}>Shot Stats</button>
            <button onClick={() => setActiveSubTab('Match Log')} className={`text-sm font-bold ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray'}`}>Match Log</button>
        </div>
        <i className="fa-solid fa-chart-simple text-primary"></i>
      </div>

      {/* Sub Tab Content */}
      <div className="flex-1 overflow-y-auto px-4 pb-24">
        {activeSubTab === 'Match Stats' && (
          <Card className="divide-y divide-iosDivider/30">
            <StatRow label="1st Serve %" val1={stats.p1.firstServePct.toFixed(2) + '%'} val2={stats.p2.firstServePct.toFixed(2) + '%'} />
            <StatRow label="Aces" val1={stats.p1.aces} val2={stats.p2.aces} />
            <StatRow label="Winners" val1={stats.p1.winners} val2={stats.p2.winners} />
            <StatRow label="Unforced Errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
            <StatRow label="Forced Errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
            <StatRow label="Total Points Won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
            <StatRow label="Total Points Won %" val1={stats.p1.totalPointsWonPct.toFixed(2) + '%'} val2={stats.p2.totalPointsWonPct.toFixed(2) + '%'} />
          </Card>
        )}

        {activeSubTab === 'Shot Stats' && (
          <div className="space-y-6">
            <section>
                <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-2 tracking-tight">Winners</h4>
                <Card className="divide-y divide-iosDivider/30">
                    <StatRow label="Forehand" val1={points.filter(p=>p.winnerId===p1.id && p.outcome==='Winner' && p.shotSide==='Forehand').length} val2={points.filter(p=>p.winnerId===p2.id && p.outcome==='Winner' && p.shotSide==='Forehand').length} />
                    <StatRow label="Backhand" val1={points.filter(p=>p.winnerId===p1.id && p.outcome==='Winner' && p.shotSide==='Backhand').length} val2={points.filter(p=>p.winnerId===p2.id && p.outcome==='Winner' && p.shotSide==='Backhand').length} />
                </Card>
            </section>
            <section>
                <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-2 tracking-tight">Unforced Errors</h4>
                <Card className="divide-y divide-iosDivider/30">
                    <StatRow label="Forehand" val1={points.filter(p=>p.loserId===p1.id && p.outcome==='Unforced Error' && p.shotSide==='Forehand').length} val2={points.filter(p=>p.loserId===p2.id && p.outcome==='Unforced Error' && p.shotSide==='Forehand').length} />
                    <StatRow label="Backhand" val1={points.filter(p=>p.loserId===p1.id && p.outcome==='Unforced Error' && p.shotSide==='Backhand').length} val2={points.filter(p=>p.loserId===p2.id && p.outcome==='Unforced Error' && p.shotSide==='Backhand').length} />
                </Card>
            </section>
          </div>
        )}

        {activeSubTab === 'Match Log' && (
           <div className="space-y-2">
             {points.slice().reverse().map((p, i) => {
               const winner = players.find(pl => pl.id === p.winnerId);
               const loser = players.find(pl => pl.id === p.loserId);
               return (
                 <div key={i} className="flex gap-4 p-3 bg-white border border-iosDivider/30 rounded-xl items-center">
                    <div className="flex flex-col items-center min-w-[40px]">
                        <span className="text-xs font-bold">{p.scoreAtStart.p1Points}</span>
                        <div className="w-2 h-2 rounded-full bg-yellow-400 my-1"></div>
                        <span className="text-xs font-bold">{p.scoreAtStart.p2Points}</span>
                    </div>
                    <p className="text-xs leading-relaxed flex-1">
                      {winner?.name} won the point ({p.outcome === 'Double Fault' ? `${loser?.name} Double Fault` : p.outcome}).
                    </p>
                 </div>
               );
             })}
           </div>
        )}
      </div>

      {/* Point Modal Overlay */}
      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] p-6 flex flex-col pt-24 overflow-y-auto animate-in fade-in duration-200">
          <h2 className="text-[16px] text-center font-bold mb-8">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

          <div className="grid grid-cols-3 gap-3 mb-4 px-2">
            {showAce && (
              <button 
                onClick={() => setOutcome('Ace')}
                className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Ace' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
              >
                Ace
              </button>
            )}
            <button 
              onClick={() => setOutcome('Winner')}
              className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Winner' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
            >
              Winner
            </button>
            <button 
              onClick={() => setOutcome('Unforced Error')}
              className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Unforced Error' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
            >
              Unforced Error
            </button>
          </div>
          <div className="grid grid-cols-2 gap-3 mb-8 px-10">
            <button 
              onClick={() => setOutcome('Forced Error')}
              className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Forced Error' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
            >
              Forced Error
            </button>
            {showDoubleFault && (
              <button 
                onClick={() => setOutcome('Double Fault')}
                className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Double Fault' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
              >
                Double Fault
              </button>
            )}
            {!showDoubleFault && winnerIsServer && (
              <button 
                onClick={() => setOutcome('Service Winner')}
                className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Service Winner' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
              >
                Service Winner
              </button>
            )}
          </div>

          {(outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error') && (
            <div className="animate-in slide-in-from-bottom-2 duration-300">
              <h3 className="text-[13px] text-center font-bold text-black mb-4">Forehand or backhand shot?</h3>
              <div className="flex gap-3 mb-8">
                 <button onClick={() => setShotSide('Forehand')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${shotSide === 'Forehand' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Forehand</button>
                 <button onClick={() => setShotSide('Backhand')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${shotSide === 'Backhand' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Backhand</button>
              </div>
            </div>
          )}

          <div className="mt-8 px-2">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[14px] font-bold">Rally Length:</span>
              <div className="flex items-center gap-6 text-primary font-bold">
                 <button onClick={() => setRallyLength(Math.max(0, rallyLength-1))} className="text-2xl h-8 w-8 flex items-center justify-center">-</button>
                 <span className="text-[16px] font-bold w-4 text-center">{rallyLength}</span>
                 <button onClick={() => setRallyLength(rallyLength+1)} className="text-2xl h-8 w-8 flex items-center justify-center">+</button>
              </div>
            </div>
            <input type="range" min="0" max="30" value={rallyLength} onChange={e=>setRallyLength(parseInt(e.target.value))} className="w-full accent-primary h-1 bg-iosBg rounded-lg appearance-none cursor-pointer mt-4" />
          </div>

          <div className="flex gap-4 mt-auto pt-10 pb-12">
            <button 
              onClick={() => setPointModal({ show: false, winnerId: '', loserId: '' })} 
              className="flex-1 py-4 bg-[#EF4444] text-white font-bold rounded-xl shadow-lg active:scale-95 transition-all"
            >
              Cancel Point
            </button>
            <button 
              onClick={handleSavePoint} 
              disabled={!outcome}
              className={`flex-1 py-4 font-bold rounded-xl shadow-lg active:scale-95 transition-all ${outcome ? 'bg-primary text-white' : 'bg-[#C6C6C8] text-white/70'}`}
            >
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: string | number; val2: string | number }> = ({ label, val1, val2 }) => (
  <div className="flex justify-between items-center px-4 py-3">
    <span className="text-sm font-medium w-20">{val1}</span>
    <span className="text-xs text-iosGray font-semibold flex-1 text-center tracking-tight">{label}</span>
    <span className="text-sm font-medium w-20 text-right">{val2}</span>
  </div>
);

export default ActiveMatchView;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, POINT_VALUES } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  onFinish: (points: Point[]) => void;
  onCancel: () => void;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ config, players, onFinish, onCancel }) => {
  const [points, setPoints] = React.useState<Point[]>([]);
  const [score, setScore] = React.useState<CurrentScore>({
    p1Points: '0',
    p2Points: '0',
    p1Games: 0,
    p2Games: 0,
    p1Sets: 0,
    p2Sets: 0,
    servingPlayerId: config.initialServerId,
    isGameOver: false,
    isSetOver: false,
    isMatchOver: false,
  });
  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Point Modal State
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    setPointModal({ show: true, winnerId, loserId });
  };

  const handleSavePoint = () => {
    if (!outcome) return;

    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);

    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);

    // Reset Modal
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);

    if (newScore.isMatchOver) {
      onFinish(newPoints);
    }
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  return (
    <div className="flex flex-col h-full bg-iosBg">
      {/* Header */}
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-3">
            <i className="fa-solid fa-tower-broadcast text-primary"></i>
            <i className="fa-solid fa-rotate-left text-primary"></i>
            <i className="fa-solid fa-ellipsis text-primary"></i>
        </div>
      </header>

      {/* Mini Score Card */}
      <div className="p-4">
        <Card className="p-0">
          <div className="bg-primary text-white px-4 py-2 text-sm font-semibold">
            {new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}
          </div>
          <div className="p-4 space-y-2">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">
                  {p1.name[0]}
                </div>
                <span className="text-sm font-medium">{p1.name}</span>
              </div>
              <span className="font-bold">{score.p1Sets}</span>
            </div>
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">
                  {p2.name[0]}
                </div>
                <span className="text-sm font-medium">{p2.name}</span>
              </div>
              <span className="font-bold">{score.p2Sets}</span>
            </div>
          </div>
        </Card>
      </div>

      {/* Live Scoreboard */}
      <div className="px-6 pb-6 pt-2 flex justify-between relative">
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
          {score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute -left-2 top-2"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p1.name}</span>
          <span className="text-8xl scoreboard-font text-primary">{score.p1Points}</span>
        </div>
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
          {score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-[calc(50%-100px)] top-2"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p2.name}</span>
          <span className="text-8xl scoreboard-font text-black">{score.p2Points}</span>
        </div>
      </div>

      {/* Serve Toggle */}
      <div className="px-4 mb-4">
        <SegmentedControl
          options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
          value={serveNumber}
          onChange={(v: any) => setServeNumber(v)}
        />
      </div>

      {/* Sub Navigation */}
      <div className="flex justify-between px-6 py-2 items-center border-t border-b border-iosDivider/20 mb-4 bg-white/50 backdrop-blur-sm">
        <i className="fa-solid fa-magnifying-glass text-primary"></i>
        <div className="flex gap-4">
            <button onClick={() => setActiveSubTab('Match Stats')} className={`text-sm font-bold ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray'}`}>Match Stats</button>
            <button onClick={() => setActiveSubTab('Shot Stats')} className={`text-sm font-bold ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray'}`}>Shot Stats</button>
            <button onClick={() => setActiveSubTab('Match Log')} className={`text-sm font-bold ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray'}`}>Match Log</button>
        </div>
        <i className="fa-solid fa-chart-simple text-primary"></i>
      </div>

      {/* Sub Tab Content */}
      <div className="flex-1 overflow-y-auto px-4 pb-24">
        {activeSubTab === 'Match Stats' && (
          <Card className="divide-y divide-iosDivider/30">
            <StatRow label="1st Serve %" val1={stats.p1.firstServePct.toFixed(2) + '%'} val2={stats.p2.firstServePct.toFixed(2) + '%'} />
            <StatRow label="Aces" val1={stats.p1.aces} val2={stats.p2.aces} />
            <StatRow label="Winners" val1={stats.p1.winners} val2={stats.p2.winners} />
            <StatRow label="Unforced Errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
            <StatRow label="Forced Errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
            <StatRow label="Total Points Won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
            <StatRow label="Total Points Won %" val1={stats.p1.totalPointsWonPct.toFixed(2) + '%'} val2={stats.p2.totalPointsWonPct.toFixed(2) + '%'} />
          </Card>
        )}

        {activeSubTab === 'Shot Stats' && (
          <div className="space-y-6">
            <section>
                <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-2 tracking-tight">Winners</h4>
                <Card className="divide-y divide-iosDivider/30">
                    <StatRow label="Forehand" val1={points.filter(p=>p.winnerId===p1.id && p.outcome==='Winner' && p.shotSide==='Forehand').length} val2={points.filter(p=>p.winnerId===p2.id && p.outcome==='Winner' && p.shotSide==='Forehand').length} />
                    <StatRow label="Backhand" val1={points.filter(p=>p.winnerId===p1.id && p.outcome==='Winner' && p.shotSide==='Backhand').length} val2={points.filter(p=>p.winnerId===p2.id && p.outcome==='Winner' && p.shotSide==='Backhand').length} />
                </Card>
            </section>
            <section>
                <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-2 tracking-tight">Unforced Errors</h4>
                <Card className="divide-y divide-iosDivider/30">
                    <StatRow label="Forehand" val1={points.filter(p=>p.loserId===p1.id && p.outcome==='Unforced Error' && p.shotSide==='Forehand').length} val2={points.filter(p=>p.loserId===p2.id && p.outcome==='Unforced Error' && p.shotSide==='Forehand').length} />
                    <StatRow label="Backhand" val1={points.filter(p=>p.loserId===p1.id && p.outcome==='Unforced Error' && p.shotSide==='Backhand').length} val2={points.filter(p=>p.loserId===p2.id && p.outcome==='Unforced Error' && p.shotSide==='Backhand').length} />
                </Card>
            </section>
          </div>
        )}

        {activeSubTab === 'Match Log' && (
           <div className="space-y-2">
             {points.slice().reverse().map((p, i) => {
               const winner = players.find(pl => pl.id === p.winnerId);
               const loser = players.find(pl => pl.id === p.loserId);
               return (
                 <div key={i} className="flex gap-4 p-3 bg-white border border-iosDivider/30 rounded-xl items-center">
                    <div className="flex flex-col items-center min-w-[40px]">
                        <span className="text-xs font-bold">{p.scoreAtStart.p1Points}</span>
                        <div className="w-2 h-2 rounded-full bg-yellow-400 my-1"></div>
                        <span className="text-xs font-bold">{p.scoreAtStart.p2Points}</span>
                    </div>
                    <p className="text-xs leading-relaxed flex-1">
                      {winner?.name} won the point ({p.outcome === 'Double Fault' ? `${loser?.name} Double Fault` : p.outcome}).
                    </p>
                 </div>
               );
             })}
           </div>
        )}
      </div>

      {/* Point Modal Overlay */}
      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] p-6 flex flex-col pt-24 overflow-y-auto animate-in fade-in duration-200">
          <h2 className="text-[16px] text-center font-bold mb-8">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

          <div className="grid grid-cols-2 gap-3 mb-4 px-2">
            {showAce && (
              <button 
                onClick={() => { setOutcome('Ace'); setShotSide(null); setErrorType(null); }}
                className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Ace' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
              >
                Ace
              </button>
            )}
            <button 
              onClick={() => { setOutcome('Winner'); setServePlacement(null); }}
              className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Winner' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
            >
              Winner
            </button>
            <button 
              onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }}
              className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Unforced Error' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
            >
              Unforced Error
            </button>
            <button 
              onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }}
              className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Forced Error' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
            >
              Forced Error
            </button>
            {showDoubleFault && (
              <button 
                onClick={() => { setOutcome('Double Fault'); setShotSide(null); setErrorType(null); }}
                className={`py-3 rounded-xl font-bold border transition-all ${outcome === 'Double Fault' ? 'bg-primary text-white border-primary shadow-md' : 'bg-white text-primary border-primary/20'}`}
              >
                Double Fault
              </button>
            )}
          </div>

          {/* Level 2: Conditional Selections */}
          {(outcome === 'Ace' || outcome === 'Double Fault') && (
            <div className="animate-in slide-in-from-bottom-2 duration-300 mt-4">
              <h3 className="text-[13px] text-center font-bold text-black mb-4">Where was the {outcome.toLowerCase()} hit?</h3>
              <div className="flex gap-3 mb-8">
                 <button onClick={() => setServePlacement('Wide')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${servePlacement === 'Wide' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Wide</button>
                 <button onClick={() => setServePlacement('Body')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${servePlacement === 'Body' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Body</button>
                 <button onClick={() => setServePlacement('T')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${servePlacement === 'T' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>T</button>
              </div>
            </div>
          )}

          {(outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error') && (
            <div className="animate-in slide-in-from-bottom-2 duration-300 mt-4">
              <h3 className="text-[13px] text-center font-bold text-black mb-4">Forehand or backhand shot?</h3>
              <div className="flex gap-3 mb-6">
                 <button onClick={() => setShotSide('Forehand')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${shotSide === 'Forehand' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Forehand</button>
                 <button onClick={() => setShotSide('Backhand')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${shotSide === 'Backhand' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Backhand</button>
              </div>

              <h3 className="text-[13px] text-center font-bold text-black mb-4">Shot Location?</h3>
              <div className="flex gap-3 mb-6">
                 <button onClick={() => setLocation('Cross Court')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${location === 'Cross Court' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Cross</button>
                 <button onClick={() => setLocation('Down the Line')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${location === 'Down the Line' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Line</button>
                 <button onClick={() => setLocation('Middle')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${location === 'Middle' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Middle</button>
              </div>
            </div>
          )}

          {(outcome === 'Unforced Error' || outcome === 'Forced Error') && (
             <div className="animate-in slide-in-from-bottom-2 duration-300">
               <h3 className="text-[13px] text-center font-bold text-black mb-4">Error Type?</h3>
               <div className="flex gap-3 mb-8">
                 <button onClick={() => setErrorType('Net')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${errorType === 'Net' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Net</button>
                 <button onClick={() => setErrorType('Long')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${errorType === 'Long' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Long</button>
                 <button onClick={() => setErrorType('Wide')} className={`flex-1 py-3 rounded-xl font-bold border transition-all ${errorType === 'Wide' ? 'bg-primary text-white border-primary' : 'bg-white text-primary border-primary/20'}`}>Wide</button>
               </div>
             </div>
          )}

          <div className="mt-8 px-2">
            <div className="flex items-center justify-between mb-2">
              <span className="text-[14px] font-bold">Rally Length:</span>
              <div className="flex items-center gap-6 text-primary font-bold">
                 <button onClick={() => setRallyLength(Math.max(0, rallyLength-1))} className="text-2xl h-8 w-8 flex items-center justify-center">-</button>
                 <span className="text-[16px] font-bold w-4 text-center">{rallyLength}</span>
                 <button onClick={() => setRallyLength(rallyLength+1)} className="text-2xl h-8 w-8 flex items-center justify-center">+</button>
              </div>
            </div>
            <input type="range" min="0" max="30" value={rallyLength} onChange={e=>setRallyLength(parseInt(e.target.value))} className="w-full accent-primary h-1 bg-iosBg rounded-lg appearance-none cursor-pointer mt-4" />
          </div>

          <div className="flex gap-4 mt-auto pt-10 pb-12">
            <button 
              onClick={() => {
                setPointModal({ show: false, winnerId: '', loserId: '' });
                setOutcome(null);
                setServePlacement(null);
                setShotSide(null);
              }} 
              className="flex-1 py-4 bg-[#EF4444] text-white font-bold rounded-xl shadow-lg active:scale-95 transition-all"
            >
              Cancel Point
            </button>
            <button 
              onClick={handleSavePoint} 
              disabled={!outcome || ((outcome === 'Ace' || outcome === 'Double Fault') && !servePlacement)}
              className={`flex-1 py-4 font-bold rounded-xl shadow-lg active:scale-95 transition-all ${outcome ? 'bg-primary text-white' : 'bg-[#C6C6C8] text-white/70'}`}
            >
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: string | number; val2: string | number }> = ({ label, val1, val2 }) => (
  <div className="flex justify-between items-center px-4 py-3">
    <span className="text-sm font-medium w-20">{val1}</span>
    <span className="text-xs text-iosGray font-semibold flex-1 text-center tracking-tight">{label}</span>
    <span className="text-sm font-medium w-20 text-right">{val2}</span>
  </div>
);

export default ActiveMatchView;

export type HittingArm = 'Left' | 'Right';
export type BackhandType = 'One-Handed' | 'Two-Handed';
export type Outcome = 'Ace' | 'Winner' | 'Unforced Error' | 'Forced Error' | 'Double Fault';
export type ShotKind = 'Regular' | 'Return' | 'Inside-In' | 'Inside-Out' | 'Passing' | 'Approach' | 'Slice' | 'Volley' | 'Drop Shot' | 'Lob' | 'Overhead';
export type ShotLocation = 'Cross Court' | 'Middle' | 'Down the Line';
export type ErrorType = 'Long' | 'Net' | 'Wide';
export type ServePlacement = 'T' | 'Body' | 'Wide';
export type CourtSurface = 'Hard' | 'Clay' | 'Grass';
export type CourtSpeed = 'Slow' | 'Neutral' | 'Fast';
export type CourtType = 'Indoor' | 'Outdoor';
export type ScoringType = 'Simple' | 'Shot Stats';

export interface Player {
  id: string;
  name: string;
  team: string;
  hittingArm: HittingArm;
  backhand: BackhandType;
  utrRating: number;
  isSaved: boolean;
}

export interface Point {
  winnerId: string;
  loserId: string;
  outcome: Outcome;
  serverPlayerId: string;
  serveNumber: 1 | 2;
  shotSide?: 'Forehand' | 'Backhand';
  shotKind?: ShotKind;
  location?: ShotLocation;
  errorType?: ErrorType;
  servePlacement?: ServePlacement;
  rallyLength: number;
  scoreAtStart: {
    p1Points: string;
    p2Points: string;
    p1Games: number;
    p2Games: number;
    p1Sets: number;
    p2Sets: number;
  };
}

export interface MatchConfig {
  p1Id: string;
  p2Id: string;
  initialServerId: string;
  scoringType: ScoringType;
  adScoring: boolean;
  tieBreak: boolean;
  setsToWin: 1 | 3 | 5 | 'Pro Set' | 'Fast4';
  gamesPerSet: number;
  courtSurface: CourtSurface;
  courtSpeed: CourtSpeed;
  courtType: CourtType;
  description: string;
  city: string;
  state: string;
  temperature: string;
  humidity: string;
}

export interface Match {
  id: string;
  date: string;
  config: MatchConfig;
  points: Point[];
  isCompleted: boolean;
  finalScore: string;
}

export enum Tab {
  Matches = 'Matches',
  Players = 'Players',
  Active = 'Active'
}

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  onFinish: (points: Point[]) => void;
  onCancel: () => void;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ config, players, onFinish, onCancel }) => {
  const [points, setPoints] = React.useState<Point[]>([]);
  const [score, setScore] = React.useState<CurrentScore>({
    p1Points: '0',
    p2Points: '0',
    p1Games: 0,
    p2Games: 0,
    p1Sets: 0,
    p2Sets: 0,
    servingPlayerId: config.initialServerId,
    isGameOver: false,
    isSetOver: false,
    isMatchOver: false,
  });
  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Point Modal Step State
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    setPointModal({ show: true, winnerId, loserId });
  };

  const handleSavePoint = () => {
    if (!outcome) return;

    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);

    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);

    // Reset Modal
    resetModalState();

    if (newScore.isMatchOver) {
      onFinish(newPoints);
    }
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  const isOutcomeSelected = !!outcome;
  const isSideSelected = !!shotSide;
  const isKindSelected = !!shotKind;
  const isLocationSelected = !!location;
  const isErrorSelected = !!errorType;
  const isPlacementSelected = !!servePlacement;

  // Decision logic for enabling Save Point
  const canSave = React.useMemo(() => {
    if (!outcome) return false;
    if (outcome === 'Ace' || outcome === 'Double Fault') return !!servePlacement;
    if (outcome === 'Winner') return !!shotSide && !!shotKind && !!location;
    if (outcome === 'Unforced Error' || outcome === 'Forced Error') return !!shotSide && !!shotKind && !!location && !!errorType;
    return false;
  }, [outcome, servePlacement, shotSide, shotKind, location, errorType]);

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3 rounded-xl font-bold transition-all duration-200 border-2 ${
        active 
          ? 'bg-primary text-white border-primary shadow-md' 
          : 'bg-white text-primary border-primary hover:bg-primary/5'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[15px] text-center font-bold text-black mt-6 mb-3">{children}</h3>
  );

  return (
    <div className="flex flex-col h-full bg-iosBg">
      {/* Header */}
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4">
            <i className="fa-solid fa-tower-broadcast text-primary"></i>
            <i className="fa-solid fa-rotate-left text-primary"></i>
            <i className="fa-solid fa-ellipsis text-primary"></i>
        </div>
      </header>

      {/* Main UI (Scoreboard, Stats etc) - Same as before */}
      <div className="p-4">
        <Card className="p-0">
          <div className="bg-primary text-white px-4 py-2 text-sm font-semibold flex justify-between">
            <span>{new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            {config.description && <span className="opacity-70">{config.description}</span>}
          </div>
          <div className="p-4 space-y-2">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">
                  {p1.name[0]}
                </div>
                <span className="text-sm font-medium">{p1.name}</span>
              </div>
              <span className="font-bold">{score.p1Sets}</span>
            </div>
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-primary flex items-center justify-center text-white text-[10px] font-bold">
                  {p2.name[0]}
                </div>
                <span className="text-sm font-medium">{p2.name}</span>
              </div>
              <span className="font-bold">{score.p2Sets}</span>
            </div>
          </div>
        </Card>
      </div>

      <div className="px-6 pb-6 pt-2 flex justify-between relative">
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
          {score.servingPlayerId === p1.id && <div className="w-3 h-3 bg-yellow-400 rounded-full absolute -left-0 top-1.5 shadow-sm"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p1.name}</span>
          <span className="text-8xl scoreboard-font text-primary">{score.p1Points}</span>
        </div>
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
          {score.servingPlayerId === p2.id && <div className="w-3 h-3 bg-yellow-400 rounded-full absolute -right-0 top-1.5 shadow-sm"></div>}
          <span className="text-lg font-medium text-iosGray mb-1">{p2.name}</span>
          <span className="text-8xl scoreboard-font text-black">{score.p2Points}</span>
        </div>
      </div>

      <div className="px-4 mb-4">
        <SegmentedControl
          options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
          value={serveNumber}
          onChange={(v: any) => setServeNumber(v)}
        />
      </div>

      <div className="flex justify-between px-6 py-2 items-center border-t border-b border-iosDivider/20 mb-4 bg-white/50 backdrop-blur-sm">
        <i className="fa-solid fa-magnifying-glass text-primary"></i>
        <div className="flex gap-4">
            <button onClick={() => setActiveSubTab('Match Stats')} className={`text-sm font-bold ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray'}`}>Match Stats</button>
            <button onClick={() => setActiveSubTab('Shot Stats')} className={`text-sm font-bold ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray'}`}>Shot Stats</button>
            <button onClick={() => setActiveSubTab('Match Log')} className={`text-sm font-bold ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray'}`}>Match Log</button>
        </div>
        <i className="fa-solid fa-chart-simple text-primary"></i>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-24">
        {activeSubTab === 'Match Stats' && (
          <Card className="divide-y divide-iosDivider/30">
            <StatRow label="1st Serve %" val1={stats.p1.firstServePct.toFixed(1) + '%'} val2={stats.p2.firstServePct.toFixed(1) + '%'} />
            <StatRow label="Aces" val1={stats.p1.aces} val2={stats.p2.aces} />
            <StatRow label="Winners" val1={stats.p1.winners} val2={stats.p2.winners} />
            <StatRow label="Unforced Errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
            <StatRow label="Forced Errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
            <StatRow label="Total Points Won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
          </Card>
        )}
        {/* ... Rest of stats views ... */}
      </div>

      {/* High Fidelity Progressive Point Entry Modal */}
      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col pt-16 overflow-y-auto animate-in fade-in slide-in-from-bottom-5 duration-300">
          <div className="px-6 pb-20">
            <h2 className="text-[17px] text-center font-bold mb-6">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

            {/* Step 1: Outcome */}
            <div className="grid grid-cols-2 gap-3 mb-2">
              {showAce && <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => { setOutcome('Ace'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); }} />}
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => { setOutcome('Winner'); setServePlacement(null); }} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }} />
              {showDoubleFault && <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => { setOutcome('Double Fault'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); }} className="col-span-2" />}
            </div>

            {/* Step 2: Placement (for Ace/DF) or Shot Side (for Winner/UE/FE) */}
            {isOutcomeSelected && (outcome === 'Ace' || outcome === 'Double Fault') && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Where was the {outcome.toLowerCase()} hit?</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Wide" active={servePlacement === 'Wide'} onClick={() => setServePlacement('Wide')} />
                  <BlueBtn label="Body" active={servePlacement === 'Body'} onClick={() => setServePlacement('Body')} />
                  <BlueBtn label="T" active={servePlacement === 'T'} onClick={() => setServePlacement('T')} />
                </div>
              </div>
            )}

            {isOutcomeSelected && (outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error') && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Forehand or backhand shot?</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                  <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                </div>
              </div>
            )}

            {/* Step 3: Shot Kind */}
            {isSideSelected && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>What kind of shot?</SectionLabel>
                <div className="grid grid-cols-3 gap-2">
                  {(['Regular', 'Return', 'Inside-In', 'Inside-Out', 'Passing', 'Approach', 'Slice', 'Volley', 'Drop Shot', 'Lob', 'Overhead'] as ShotKind[]).map(k => (
                    <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k)} className="text-[12px] py-2" />
                  ))}
                </div>
              </div>
            )}

            {/* Step 4: Shot Location */}
            {isKindSelected && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>What was the shot location?</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Cross Court" active={location === 'Cross Court'} onClick={() => setLocation('Cross Court')} className="text-[12px]" />
                  <BlueBtn label="Middle" active={location === 'Middle'} onClick={() => setLocation('Middle')} className="text-[12px]" />
                  <BlueBtn label="Down the Line" active={location === 'Down the Line'} onClick={() => setLocation('Down the Line')} className="text-[12px]" />
                </div>
              </div>
            )}

            {/* Step 5: Error Type */}
            {isLocationSelected && (outcome === 'Unforced Error' || outcome === 'Forced Error') && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>How was the shot an error?</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                  <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                  <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                </div>
              </div>
            )}

            {/* Rally Length - Always at the bottom once it's relevant */}
            {(isOutcomeSelected) && (
              <div className="mt-10 px-2 animate-in slide-in-from-bottom-2 duration-300">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-[15px] font-bold">Rally Length:</span>
                  <div className="flex items-center gap-4 text-primary font-bold">
                    <button onClick={() => setRallyLength(Math.max(0, rallyLength - 1))} className="text-3xl font-normal w-8 h-8 flex items-center justify-center">－</button>
                    <span className="text-xl w-6 text-center">{rallyLength}</span>
                    <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal w-8 h-8 flex items-center justify-center">＋</button>
                  </div>
                </div>
                <div className="relative h-8 flex items-center">
                  <input 
                    type="range" 
                    min="0" max="30" 
                    value={rallyLength} 
                    onChange={e => setRallyLength(parseInt(e.target.value))} 
                    className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
                  />
                </div>
              </div>
            )}
          </div>

          {/* Persistent Footer Actions */}
          <div className="mt-auto bg-white/90 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button 
              onClick={resetModalState}
              className="flex-1 py-4 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-lg active:scale-95 transition-all text-lg"
            >
              Cancel Point
            </button>
            <button 
              onClick={handleSavePoint}
              disabled={!canSave}
              className={`flex-1 py-4 font-bold rounded-2xl shadow-lg active:scale-95 transition-all text-lg ${
                canSave ? 'bg-primary text-white' : 'bg-[#C6C6C8] text-white/70'
              }`}
            >
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: string | number; val2: string | number }> = ({ label, val1, val2 }) => (
  <div className="flex justify-between items-center px-4 py-3">
    <span className="text-sm font-medium w-20">{val1}</span>
    <span className="text-xs text-iosGray font-semibold flex-1 text-center tracking-tight">{label}</span>
    <span className="text-sm font-medium w-20 text-right">{val2}</span>
  </div>
);

export default ActiveMatchView;

import { Point, MatchConfig, Outcome } from '../types';

export const POINT_VALUES = ['0', '15', '30', '40', 'Ad'];

export interface CurrentScore {
  p1Points: string;
  p2Points: string;
  p1Games: number;
  p2Games: number;
  p1Sets: number;
  p2Sets: number;
  servingPlayerId: string;
  isGameOver: boolean;
  isSetOver: boolean;
  isMatchOver: boolean;
}

export function calculateNewScore(
  current: CurrentScore,
  winnerId: string,
  p1Id: string,
  p2Id: string,
  config: MatchConfig
): CurrentScore {
  let { p1Points, p2Points, p1Games, p2Games, p1Sets, p2Sets, servingPlayerId } = current;
  const isP1 = winnerId === p1Id;

  // Point logic
  if (config.adScoring) {
    if (isP1) {
      if (p1Points === '40') {
        if (p2Points === 'Ad') p2Points = '40';
        else if (p2Points === '40') p1Points = 'Ad';
        else return awardGame(current, p1Id, p1Id, p2Id, config);
      } else if (p1Points === 'Ad') {
        return awardGame(current, p1Id, p1Id, p2Id, config);
      } else {
        p1Points = nextPoint(p1Points);
      }
    } else {
      if (p2Points === '40') {
        if (p1Points === 'Ad') p1Points = '40';
        else if (p1Points === '40') p2Points = 'Ad';
        else return awardGame(current, p2Id, p1Id, p2Id, config);
      } else if (p2Points === 'Ad') {
        return awardGame(current, p2Id, p1Id, p2Id, config);
      } else {
        p2Points = nextPoint(p2Points);
      }
    }
  } else {
    // No-Ad logic
    if (isP1) {
      if (p1Points === '40') return awardGame(current, p1Id, p1Id, p2Id, config);
      p1Points = nextPoint(p1Points);
    } else {
      if (p2Points === '40') return awardGame(current, p2Id, p1Id, p2Id, config);
      p2Points = nextPoint(p2Points);
    }
  }

  return { ...current, p1Points, p2Points };
}

function nextPoint(p: string): string {
  if (p === '0') return '15';
  if (p === '15') return '30';
  if (p === '30') return '40';
  return '0';
}

function awardGame(current: CurrentScore, winnerId: string, p1Id: string, p2Id: string, config: MatchConfig): CurrentScore {
  let { p1Games, p2Games, p1Sets, p2Sets, servingPlayerId } = current;
  if (winnerId === p1Id) p1Games++; else p2Games++;

  // Reset points
  const p1Points = '0';
  const p2Points = '0';

  // Toggle server
  servingPlayerId = servingPlayerId === p1Id ? p2Id : p1Id;

  // Set logic
  const gamesNeeded = config.gamesPerSet;
  if (p1Games >= gamesNeeded && p1Games - p2Games >= 2) {
    p1Sets++;
    p1Games = 0;
    p2Games = 0;
  } else if (p2Games >= gamesNeeded && p2Games - p1Games >= 2) {
    p2Sets++;
    p1Games = 0;
    p2Games = 0;
  }

  const setsToWin = typeof config.setsToWin === 'number' ? Math.ceil(config.setsToWin / 2) : 1;
  const isMatchOver = p1Sets >= setsToWin || p2Sets >= setsToWin;

  return { ...current, p1Points, p2Points, p1Games, p2Games, p1Sets, p2Sets, servingPlayerId, isMatchOver };
}

export function calculateStats(points: Point[], p1Id: string, p2Id: string) {
  const getStats = (playerId: string) => {
    const opponentId = playerId === p1Id ? p2Id : p1Id;

    const servicePoints = points.filter(p => p.serverPlayerId === playerId);
    const returnPoints = points.filter(p => p.serverPlayerId === opponentId);

    const firstServesIn = servicePoints.filter(p => p.serveNumber === 1 && p.outcome !== 'Double Fault');
    const firstServesTotal = servicePoints.length; // Approximate, assuming 2nd serves only happen if 1st is out

    // 2nd serves played are points where serveNumber was 2
    const secondServesIn = servicePoints.filter(p => p.serveNumber === 2 && p.outcome !== 'Double Fault');
    const secondServesTotal = servicePoints.filter(p => p.serveNumber === 2).length;

    const aces = points.filter(p => p.winnerId === playerId && p.outcome === 'Ace').length;
    const doubleFaults = points.filter(p => p.loserId === playerId && p.outcome === 'Double Fault').length;
    const winners = points.filter(p => p.winnerId === playerId && p.outcome === 'Winner').length;
    const unforcedErrors = points.filter(p => p.loserId === playerId && p.outcome === 'Unforced Error').length;
    const forcedErrors = points.filter(p => p.loserId === playerId && p.outcome === 'Forced Error').length;

    const firstServePointsWon = servicePoints.filter(p => p.serveNumber === 1 && p.winnerId === playerId).length;
    const secondServePointsWon = servicePoints.filter(p => p.serveNumber === 2 && p.winnerId === playerId).length;

    const firstReturnPointsWon = returnPoints.filter(p => p.serveNumber === 1 && p.winnerId === playerId).length;
    const secondReturnPointsWon = returnPoints.filter(p => p.serveNumber === 2 && p.winnerId === playerId).length;

    // Break Point calculation
    const isBP = (p: Point, serverId: string) => {
      const s = p.scoreAtStart;
      const isP1Serving = serverId === p1Id;
      if (isP1Serving) {
        // Opponent (P2) has BP
        return (s.p2Points === '40' && s.p1Points !== '40' && s.p1Points !== 'Ad') || (s.p2Points === 'Ad');
      } else {
        // Opponent (P1) has BP
        return (s.p1Points === '40' && s.p2Points !== '40' && s.p2Points !== 'Ad') || (s.p1Points === 'Ad');
      }
    };

    const breakPointOpportunities = returnPoints.filter(p => isBP(p, opponentId));
    const breakPointsWon = breakPointOpportunities.filter(p => p.winnerId === playerId).length;

    const opponentBPOpportunities = servicePoints.filter(p => isBP(p, playerId));
    const breakPointsSaved = opponentBPOpportunities.filter(p => p.winnerId === playerId).length;

    const totalPointsPlayed = points.length;
    const pointsWon = points.filter(p => p.winnerId === playerId).length;

    const touches04 = points.filter(p => p.winnerId === playerId && p.rallyLength <= 4).length;
    const touches58 = points.filter(p => p.winnerId === playerId && p.rallyLength > 4 && p.rallyLength <= 8).length;
    const touches9plus = points.filter(p => p.winnerId === playerId && p.rallyLength > 8).length;

    return {
      firstServePct: firstServesTotal ? (firstServesIn.length / firstServesTotal) * 100 : 0,
      secondServePct: secondServesTotal ? (secondServesIn.length / secondServesTotal) * 100 : 0,
      aces,
      doubleFaults,
      winners,
      unforcedErrors,
      forcedErrors,
      firstServePointsWon,
      secondServePointsWon,
      breakPointsSaved,
      firstReturnPointsWon,
      secondReturnPointsWon,
      breakPointsWon,
      totalPointsWon: pointsWon,
      pointsWonPct: totalPointsPlayed ? (pointsWon / totalPointsPlayed) * 100 : 0,
      touches04,
      touches58,
      touches9plus
    };
  };

  return {
    p1: getStats(p1Id),
    p2: getStats(p2Id)
  };
}

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  onFinish: (points: Point[]) => void;
  onCancel: () => void;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ config, players, onFinish, onCancel }) => {
  const [points, setPoints] = React.useState<Point[]>([]);
  const [score, setScore] = React.useState<CurrentScore>({
    p1Points: '0',
    p2Points: '0',
    p1Games: 0,
    p2Games: 0,
    p1Sets: 0,
    p2Sets: 0,
    servingPlayerId: config.initialServerId,
    isGameOver: false,
    isSetOver: false,
    isMatchOver: false,
  });
  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Progressive Point Modal State
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleSavePoint = () => {
    // Basic fallback: if no outcome selected, treat as simple winner or unforced error based on side?
    // Requirement says "they can save whenever they want", so we use whatever is selected.
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: outcome || (pointModal.winnerId === score.servingPlayerId ? 'Winner' : 'Winner'), // Default to winner if nothing picked
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);

    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);

    resetModalState();

    if (newScore.isMatchOver) {
      onFinish(newPoints);
    }
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  // Progressive visibility logic
  const step1Outcome = outcome !== null;
  const needsSide = outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error';
  const needsPlacement = outcome === 'Ace' || outcome === 'Double Fault';
  const step2Side = needsSide && shotSide !== null;
  const step2Placement = needsPlacement && servePlacement !== null;
  const step3Kind = step2Side && shotKind !== null;
  const step4Location = step3Kind && location !== null;

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[14px] text-center font-bold text-black mt-8 mb-4 tracking-tight">{children}</h3>
  );

  return (
    <div className="flex flex-col h-full bg-iosBg">
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary">
            <i className="fa-solid fa-tower-broadcast"></i>
            <i className="fa-solid fa-rotate-left"></i>
            <i className="fa-solid fa-ellipsis"></i>
        </div>
      </header>

      <div className="p-4">
        <Card className="p-0 border-none shadow-md">
          <div className="bg-primary text-white px-4 py-2 text-xs font-bold flex justify-between uppercase tracking-widest">
            <span>{new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            {config.description && <span className="opacity-80">{config.description}</span>}
          </div>
          <div className="p-4 space-y-3 bg-white">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="w-7 h-7 rounded-full bg-primary flex items-center justify-center text-white text-[11px] font-black">
                  {p1.name[0]}
                </div>
                <span className="text-sm font-bold">{p1.name}</span>
              </div>
              <span className="font-black text-lg">{score.p1Sets}</span>
            </div>
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="w-7 h-7 rounded-full bg-primary flex items-center justify-center text-white text-[11px] font-black">
                  {p2.name[0]}
                </div>
                <span className="text-sm font-bold">{p2.name}</span>
              </div>
              <span className="font-black text-lg">{score.p2Sets}</span>
            </div>
          </div>
        </Card>
      </div>

      <div className="px-6 pb-6 pt-2 flex justify-between relative items-center">
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
          {score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute left-4 top-2 animate-pulse shadow-sm"></div>}
          <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p1.name}</span>
          <span className="text-8xl scoreboard-font text-primary tracking-tighter">{score.p1Points}</span>
        </div>
        <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
          {score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-4 top-2 animate-pulse shadow-sm"></div>}
          <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p2.name}</span>
          <span className="text-8xl scoreboard-font text-black tracking-tighter">{score.p2Points}</span>
        </div>
      </div>

      <div className="px-4 mb-6">
        <SegmentedControl
          options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
          value={serveNumber}
          onChange={(v: any) => setServeNumber(v)}
        />
      </div>

      <div className="flex justify-center gap-8 px-6 py-3 items-center border-t border-b border-iosDivider/20 mb-4 bg-white sticky top-[68px] z-30">
        <button onClick={() => setActiveSubTab('Match Stats')} className={`text-[13px] font-black uppercase tracking-widest ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray opacity-50'}`}>Match Stats</button>
        <button onClick={() => setActiveSubTab('Shot Stats')} className={`text-[13px] font-black uppercase tracking-widest ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray opacity-50'}`}>Shot Stats</button>
        <button onClick={() => setActiveSubTab('Match Log')} className={`text-[13px] font-black uppercase tracking-widest ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray opacity-50'}`}>Match Log</button>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-28">
        {activeSubTab === 'Match Stats' && (
          <Card className="divide-y divide-iosDivider/20 border-none shadow-sm">
            <StatRow label="1st Serve %" val1={stats.p1.firstServePct.toFixed(1) + '%'} val2={stats.p2.firstServePct.toFixed(1) + '%'} />
            <StatRow label="2nd Serve %" val1={stats.p1.secondServePct.toFixed(1) + '%'} val2={stats.p2.secondServePct.toFixed(1) + '%'} />
            <StatRow label="Aces" val1={stats.p1.aces} val2={stats.p2.aces} />
            <StatRow label="Double Faults" val1={stats.p1.doubleFaults} val2={stats.p2.doubleFaults} />
            <StatRow label="Winners" val1={stats.p1.winners} val2={stats.p2.winners} />
            <StatRow label="Unforced Errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
            <StatRow label="Forced Errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
            <StatRow label="1st Serve Won" val1={stats.p1.firstServePointsWon} val2={stats.p2.firstServePointsWon} />
            <StatRow label="2nd Serve Won" val1={stats.p1.secondServePointsWon} val2={stats.p2.secondServePointsWon} />
            <StatRow label="BP Saved" val1={stats.p1.breakPointsSaved} val2={stats.p2.breakPointsSaved} />
            <StatRow label="1st Return Won" val1={stats.p1.firstReturnPointsWon} val2={stats.p2.firstReturnPointsWon} />
            <StatRow label="2nd Return Won" val1={stats.p1.secondReturnPointsWon} val2={stats.p2.secondReturnPointsWon} />
            <StatRow label="BP Won" val1={stats.p1.breakPointsWon} val2={stats.p2.breakPointsWon} />
            <StatRow label="Total Won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
            <StatRow label="% Points Won" val1={stats.p1.pointsWonPct.toFixed(1) + '%'} val2={stats.p2.pointsWonPct.toFixed(1) + '%'} />
            <StatRow label="0-4 touches" val1={stats.p1.touches04} val2={stats.p2.touches04} />
            <StatRow label="5-8 touches" val1={stats.p1.touches58} val2={stats.p2.touches58} />
            <StatRow label="9+ touches" val1={stats.p1.touches9plus} val2={stats.p2.touches9plus} />
          </Card>
        )}
      </div>

      {/* Progressive Disclosure Modal */}
      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
          <div className="flex-1 overflow-y-auto px-6 pt-20 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

            {/* Step 1: Outcome */}
            <div className="grid grid-cols-2 gap-3 mb-2">
              {showAce && <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => { setOutcome('Ace'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); }} />}
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => { setOutcome('Winner'); setServePlacement(null); }} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }} />
              {showDoubleFault && <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => { setOutcome('Double Fault'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); }} className="col-span-2" />}
            </div>

            {/* Step 2: Placement or Side */}
            {step1Outcome && (outcome === 'Ace' || outcome === 'Double Fault') && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Where was the {outcome.toLowerCase()} hit?</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Wide" active={servePlacement === 'Wide'} onClick={() => setServePlacement('Wide')} />
                  <BlueBtn label="Body" active={servePlacement === 'Body'} onClick={() => setServePlacement('Body')} />
                  <BlueBtn label="T" active={servePlacement === 'T'} onClick={() => setServePlacement('T')} />
                </div>
              </div>
            )}

            {step1Outcome && needsSide && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Forehand or backhand shot?</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                  <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                </div>
              </div>
            )}

            {/* Step 3: Kind */}
            {step2Side && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>What kind of shot?</SectionLabel>
                <div className="grid grid-cols-3 gap-2">
                  {(['Regular', 'Return', 'Inside-In', 'Inside-Out', 'Passing', 'Approach', 'Slice', 'Volley', 'Drop Shot', 'Lob', 'Overhead'] as ShotKind[]).map(k => (
                    <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k)} className="text-[12px] py-2" />
                  ))}
                </div>
              </div>
            )}

            {/* Step 4: Location */}
            {step3Kind && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>What was the shot location?</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Cross Court" active={location === 'Cross Court'} onClick={() => setLocation('Cross Court')} className="text-[12px]" />
                  <BlueBtn label="Middle" active={location === 'Middle'} onClick={() => setLocation('Middle')} className="text-[12px]" />
                  <BlueBtn label="Down the Line" active={location === 'Down the Line'} onClick={() => setLocation('Down the Line')} className="text-[12px]" />
                </div>
              </div>
            )}

            {/* Step 5: Error Type */}
            {step4Location && (outcome === 'Unforced Error' || outcome === 'Forced Error') && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>How was the shot an error?</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                  <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                  <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                </div>
              </div>
            )}

            {/* Rally Length */}
            {step1Outcome && (
              <div className="mt-12 px-2 animate-in slide-in-from-bottom-2 duration-300">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-[15px] font-bold">Rally Length:</span>
                  <div className="flex items-center gap-4 text-primary font-bold">
                    <button onClick={() => setRallyLength(Math.max(0, rallyLength - 1))} className="text-3xl font-normal">－</button>
                    <span className="text-xl w-6 text-center">{rallyLength}</span>
                    <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal">＋</button>
                  </div>
                </div>
                <input 
                  type="range" min="0" max="30" value={rallyLength} 
                  onChange={e => setRallyLength(parseInt(e.target.value))} 
                  className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
                />
              </div>
            )}
          </div>

          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg">
              Cancel Point
            </button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg ring-offset-2 hover:ring-2 hover:ring-primary/20">
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
