interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  onFinish: (points: Point[]) => void;
  onCancel: () => void;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ config, players, onFinish, onCancel }) => {
  const [points, setPoints] = React.useState<Point[]>([]);
  const [score, setScore] = React.useState<CurrentScore>({
    p1Points: '0',
    p2Points: '0',
    p1Games: 0,
    p2Games: 0,
    p1Sets: 0,
    p2Sets: 0,
    servingPlayerId: config.initialServerId,
    isGameOver: false,
    isSetOver: false,
    isMatchOver: false,
  });
  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);
    resetModalState();
    if (newScore.isMatchOver) onFinish(newPoints);
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  const step1Outcome = outcome !== null;
  const needsSide = outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error';
  const step2Side = needsSide && shotSide !== null;
  const step3Kind = step2Side && shotKind !== null;
  const step4Location = step3Kind && location !== null;

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[14px] text-center font-bold text-black mt-8 mb-4 tracking-tight uppercase">{children}</h3>
  );

  return (
    <div className="flex flex-col h-full bg-iosBg">
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary">
            <i className="fa-solid fa-tower-broadcast"></i>
            <i className="fa-solid fa-rotate-left"></i>
            <i className="fa-solid fa-ellipsis"></i>
        </div>
      </header>

      {/* Persistent Match Card Header */}
      <div className="p-4">
        <Card className="p-0 border-none shadow-md overflow-hidden">
          <div className="bg-primary text-white px-4 py-2.5 text-xs font-bold flex justify-between uppercase tracking-widest items-center">
            <span>{new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            <div className="flex items-center gap-2">
                <i className="fa-solid fa-tower-broadcast text-[10px]"></i>
                <i className="fa-solid fa-rotate-left text-[10px]"></i>
                <i className="fa-solid fa-ellipsis-vertical text-[10px]"></i>
            </div>
