              <StatRow label="1st return points won" val1={stats.p1.firstReturnPointsWon} val2={stats.p2.firstReturnPointsWon} />
              <StatRow label="2nd return points won" val1={stats.p1.secondReturnPointsWon} val2={stats.p2.secondReturnPointsWon} />
