                          {p.winnerId === p1.id && <div className="w-2 h-2 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                        </div>

                        <div className="flex-1 px-4 text-center">
                           <p className="text-[12px] font-medium leading-tight text-black/80">
                             {getPointDescription(p, players)}
                           </p>
                        </div>

                        <div className="w-12 flex items-center justify-end gap-2 text-right">
                          {p.winnerId === p2.id && <div className="w-2 h-2 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                          <span className="text-[13px] font-bold text-black">{p.scoreAtStart.p2Points}</span>
                        </div>
                      </div>
                    </React.Fragment>
                  );
                })}
             </div>
          )}
        </div>
      </div>

      {/* FIXED SUB-TAB SWITCHER AT THE VERY BOTTOM */}
      <div className="absolute bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-iosDivider/30 flex justify-around px-4 pt-4 pb-10 z-50 shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <button onClick={() => setActiveSubTab('Match Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
