            {step1Outcome && outcome === 'Ace' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Wide" active={servePlacement === 'Wide'} onClick={() => setServePlacement('Wide')} />
                  <BlueBtn label="Body" active={servePlacement === 'Body'} onClick={() => setServePlacement('Body')} />
                  <BlueBtn label="T" active={servePlacement === 'T'} onClick={() => setServePlacement('T')} />
                </div>
              </div>
            )}

            {step1Outcome && needsSide && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Side</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                  <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
