import React from 'react';
import { Match, Player } from '../types';
import { Card, Header } from '../components/UI';

interface MatchesViewProps {
  matches: Match[];
  players: Player[];
  onNewMatch: () => void;
  onAddPlayer: () => void;
  onViewMatch: (match: Match) => void;
}

const MatchesView: React.FC<MatchesViewProps> = ({ matches, players, onNewMatch, onAddPlayer, onViewMatch }) => {
  const [showMenu, setShowMenu] = React.useState(false);

  return (
    <div>
      <Header 
        title="Matches" 
        leftAction={<i className="fa-solid fa-circle-notch text-xl"></i>}
        rightAction={
          <div className="relative">
            <button onClick={() => setShowMenu(!showMenu)}><i className="fa-solid fa-plus"></i></button>
            {showMenu && (
              <div className="absolute right-0 top-10 w-48 bg-white border border-iosDivider rounded-lg shadow-xl py-1 z-50 overflow-hidden">
                <button onClick={() => { onNewMatch(); setShowMenu(false); }} className="w-full text-left px-4 py-3 text-sm border-b border-iosDivider hover:bg-iosBg">New Match</button>
                <button onClick={() => { setShowMenu(false); }} className="w-full text-left px-4 py-3 text-sm border-b border-iosDivider hover:bg-iosBg text-iosGray opacity-50 cursor-not-allowed">Enter Match Score</button>
                <button onClick={() => { onAddPlayer(); setShowMenu(false); }} className="w-full text-left px-4 py-3 text-sm hover:bg-iosBg">Add New Player</button>
              </div>
            )}
          </div>
        }
      />

      <div className="p-4 space-y-4">
        {matches.length === 0 ? (
          <div className="text-center py-20 text-iosGray">
            <p>No matches yet.</p>
            <button onClick={onNewMatch} className="mt-4 text-primary font-semibold">Start your first match</button>
          </div>
        ) : (
          matches.map(match => {
            const p1 = players.find(p => p.id === match.config.p1Id);
            const p2 = players.find(p => p.id === match.config.p2Id);

            // finalScore format: "6-0 (2-1)"
            const scoreParts = match.finalScore.split(' ');
            const setsScore = scoreParts[0].split('-');

            return (
              <div key={match.id} onClick={() => onViewMatch(match)} className="cursor-pointer active:opacity-70 transition-opacity">
                <Card className="overflow-hidden border-none shadow-md">
                  <div className="bg-primary text-white px-4 py-2 text-[10px] font-black uppercase tracking-widest flex justify-between items-center">
                    <div className="flex items-center gap-2">
                       <span>{new Date(match.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
                       {!match.isCompleted && (
                         <span className="bg-yellow-400 text-black px-1.5 py-0.5 rounded text-[8px] animate-pulse">In Progress</span>
                       )}
                    </div>
                    <div className="flex items-center gap-2">
                        <i className="fa-solid fa-tower-broadcast"></i>
                        <i className="fa-solid fa-rotate-left"></i>
                        <i className="fa-solid fa-ellipsis-vertical"></i>
                    </div>
                  </div>
                  <div className="p-4 space-y-4 bg-white">
                    <div className="flex justify-between items-center">
                      <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[11px] font-black">
                              {p1?.name[0] || '1'}
                          </div>
                          <span className="font-bold text-sm">{p1?.name || 'Player 1'}</span>
                      </div>
                      <span className="font-black text-xl">{setsScore[0] || 0}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[11px] font-black">
                              {p2?.name[0] || '2'}
                          </div>
                          <span className="font-bold text-sm">{p2?.name || 'Player 2'}</span>
                      </div>
                      <span className="font-black text-xl">{setsScore[1] || 0}</span>
                    </div>
                    <div className="pt-1 text-[9px] text-iosGray font-black uppercase tracking-widest text-center opacity-60">
                      {scoreParts[1] || ''}
                    </div>
                  </div>
                </Card>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

