};

export default App;

import { Point, MatchConfig, Outcome, ShotKind } from '../types';

export const POINT_VALUES = ['0', '15', '30', '40', 'Ad'];

export interface SetScore {
  p1: number;
  p2: number;
}

export interface CurrentScore {
  p1Points: string;
  p2Points: string;
  p1Games: number;
  p2Games: number;
  p1Sets: number;
  p2Sets: number;
  setHistory: SetScore[];
  servingPlayerId: string;
  isGameOver: boolean;
  isSetOver: boolean;
  isMatchOver: boolean;
  isTieBreak: boolean;
}

export function calculateNewScore(
  current: CurrentScore,
  winnerId: string,
  p1Id: string,
  p2Id: string,
  config: MatchConfig
): CurrentScore {
  let { p1Points, p2Points, p1Games, p2Games, p1Sets, p2Sets, servingPlayerId, setHistory, isTieBreak } = current;
  const isP1 = winnerId === p1Id;

  if (isTieBreak) {
    // Tie-break point progression (0, 1, 2, 3...)
    let p1P = parseInt(p1Points) || 0;
    let p2P = parseInt(p2Points) || 0;

    if (isP1) p1P++; else p2P++;

    // Check for tie-break win (at least 7 points and 2 clear)
    if ((p1P >= 7 || p2P >= 7) && Math.abs(p1P - p2P) >= 2) {
      // Tie-break over. Award the set 7-6.
      return awardSet(current, isP1 ? p1Id : p2Id, p1Id, p2Id, config, true);
    }

    // Standard tie-break service rotation: Player who received first point serves next 2, then rotate every 2 points.
    // However, to keep it simple and consistent with user expectations of manual server override if needed,
    // we just rotate server every 2 points in total.
    const totalPoints = p1P + p2P;
    if (totalPoints % 2 === 1) {
       servingPlayerId = (servingPlayerId === p1Id) ? p2Id : p1Id;
    }

    return { ...current, p1Points: p1P.toString(), p2Points: p2P.toString(), servingPlayerId };
  }

  // Standard Game logic
  if (config.adScoring) {
    if (isP1) {
      if (p1Points === '40') {
        if (p2Points === 'Ad') p2Points = '40';
        else if (p2Points === '40') p1Points = 'Ad';
        else return awardGame(current, p1Id, p1Id, p2Id, config);
      } else if (p1Points === 'Ad') {
        return awardGame(current, p1Id, p1Id, p2Id, config);
      } else {
        p1Points = nextPoint(p1Points);
      }
    } else {
      if (p2Points === '40') {
        if (p1Points === 'Ad') p1Points = '40';
        else if (p1Points === '40') p2Points = 'Ad';
        else return awardGame(current, p2Id, p1Id, p2Id, config);
      } else if (p2Points === 'Ad') {
        return awardGame(current, p2Id, p1Id, p2Id, config);
      } else {
        p2Points = nextPoint(p2Points);
      }
    }
  } else {
    if (isP1) {
      if (p1Points === '40') return awardGame(current, p1Id, p1Id, p2Id, config);
      p1Points = nextPoint(p1Points);
    } else {
      if (p2Points === '40') return awardGame(current, p2Id, p1Id, p2Id, config);
      p2Points = nextPoint(p2Points);
    }
  }

  return { ...current, p1Points, p2Points };
}

function nextPoint(p: string): string {
  if (p === '0') return '15';
  if (p === '15') return '30';
  if (p === '30') return '40';
  return '0';
}

function awardGame(current: CurrentScore, winnerId: string, p1Id: string, p2Id: string, config: MatchConfig): CurrentScore {
  let { p1Games, p2Games, p1Sets, p2Sets, servingPlayerId, setHistory } = current;
  if (winnerId === p1Id) p1Games++; else p2Games++;

  const p1Points = '0';
  const p2Points = '0';
  servingPlayerId = servingPlayerId === p1Id ? p2Id : p1Id;

  const gamesNeeded = config.gamesPerSet;

  // Check for Tie-break trigger (6-6)
  if (config.tieBreak && p1Games === gamesNeeded && p2Games === gamesNeeded) {
    return { ...current, p1Points: '0', p2Points: '0', p1Games, p2Games, servingPlayerId, isTieBreak: true };
  }

  // Check for normal set win
  if (p1Games >= gamesNeeded && (Math.abs(p1Games - p2Games) >= 2 || (!config.tieBreak && p1Games > gamesNeeded))) {
    return awardSet(current, p1Id, p1Id, p2Id, config, false);
  } else if (p2Games >= gamesNeeded && (Math.abs(p2Games - p1Games) >= 2 || (!config.tieBreak && p2Games > gamesNeeded))) {
    return awardSet(current, p2Id, p1Id, p2Id, config, false);
  }

  return { ...current, p1Points, p2Points, p1Games, p2Games, servingPlayerId };
}

function awardSet(current: CurrentScore, winnerId: string, p1Id: string, p2Id: string, config: MatchConfig, viaTieBreak: boolean): CurrentScore {
  let { p1Games, p2Games, p1Sets, p2Sets, setHistory, servingPlayerId } = current;

  if (viaTieBreak) {
    if (winnerId === p1Id) { p1Games = config.gamesPerSet + 1; p2Games = config.gamesPerSet; p1Sets++; }
    else { p2Games = config.gamesPerSet + 1; p1Games = config.gamesPerSet; p2Sets++; }
  } else {
    if (winnerId === p1Id) p1Sets++; else p2Sets++;
  }

  setHistory = [...setHistory, { p1: p1Games, p2: p2Games }];

  const setsToWinCount = typeof config.setsToWin === 'number' ? Math.ceil(config.setsToWin / 2) : 1;
  const isMatchOver = p1Sets >= setsToWinCount || p2Sets >= setsToWinCount;

  return { 
    ...current, 
    p1Points: '0', 
    p2Points: '0', 
    p1Games: 0, 
    p2Games: 0, 
    p1Sets, 
    p2Sets, 
    setHistory, 
    servingPlayerId: (servingPlayerId === p1Id) ? p2Id : p1Id, 
    isMatchOver, 
    isSetOver: true,
    isTieBreak: false 
  };
}

export function getScoreDetails(points: Point[], config: MatchConfig): CurrentScore {
  let current: CurrentScore = {
    p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0,
    setHistory: [], servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
  };

  points.forEach(p => {
    current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
  });

  return current;
}

export function getFinalScoreString(points: Point[], config: MatchConfig): string {
  const current = getScoreDetails(points, config);

  if (config.setsToWin === 1) {
      return `${current.p1Games}-${current.p2Games}`;
  }

  const setsString = current.setHistory.map(s => `${s.p1}-${s.p2}`).join(', ');
  return `${current.p1Sets}-${current.p2Sets} (${setsString}${current.setHistory.length > 0 && (current.p1Games > 0 || current.p2Games > 0) ? ', ' : ''}${(!current.isMatchOver && (current.p1Games > 0 || current.p2Games > 0)) ? `${current.p1Games}-${current.p2Games}` : ''})`;
}

export interface DetailedStat {
  won: number;
  total: number;
  pct: number;
}

export interface ShotStatRow {
  label: string;
  p1: number;
  p2: number;
}

export function calculateStats(points: Point[], p1Id: string, p2Id: string) {
  const getStats = (playerId: string) => {
    const opponentId = playerId === p1Id ? p2Id : p1Id;
    const servicePoints = points.filter(p => p.serverPlayerId === playerId);
    const returnPoints = points.filter(p => p.serverPlayerId === opponentId);

    const firstServesInCount = servicePoints.filter(p => p.serveNumber === 1 && p.outcome !== 'Double Fault').length;
    const firstServesTotalCount = servicePoints.length; 
    const secondServesInCount = servicePoints.filter(p => p.serveNumber === 2 && p.outcome !== 'Double Fault').length;
    const secondServesTotalCount = servicePoints.filter(p => p.serveNumber === 2).length;

    const createDetailed = (won: number, total: number): DetailedStat => ({
      won,
      total,
      pct: total > 0 ? (won / total) * 100 : 0
    });

    const firstServePointsWonCount = servicePoints.filter(p => p.serveNumber === 1 && p.winnerId === playerId).length;
    const firstServePointsTotalCount = servicePoints.filter(p => p.serveNumber === 1).length;
    const secondServePointsWonCount = servicePoints.filter(p => p.serveNumber === 2 && p.winnerId === playerId).length;
    const secondServePointsTotalCount = servicePoints.filter(p => p.serveNumber === 2).length;

    const isBP = (p: Point, serverId: string) => {
      const s = p.scoreAtStart;
      const isP1Serving = serverId === p1Id;
      if (isP1Serving) {
        // P2 is returning. Break point if P2 has 40 and P1 is at 0, 15, or 30; or if P2 has Ad.
        return (s.p2Points === '40' && s.p1Points !== '40' && s.p1Points !== 'Ad') || (s.p2Points === 'Ad');
      } else {
        // P1 is returning. Break point if P1 has 40 and P2 is at 0, 15, or 30; or if P1 has Ad.
        return (s.p1Points === '40' && s.p2Points !== '40' && s.p2Points !== 'Ad') || (s.p1Points === 'Ad');
      }
    };

    const opponentBPOpps = servicePoints.filter(p => isBP(p, playerId));
    const breakPointsSavedCount = opponentBPOpps.filter(p => p.winnerId === playerId).length;
    const firstReturnPointsWonCount = returnPoints.filter(p => p.serveNumber === 1 && p.winnerId === playerId).length;
    const firstReturnPointsTotalCount = returnPoints.filter(p => p.serveNumber === 1).length;
    const secondReturnPointsWonCount = returnPoints.filter(p => p.serveNumber === 2 && p.winnerId === playerId).length;
    const secondReturnPointsTotalCount = returnPoints.filter(p => p.serveNumber === 2).length;
    const myBPOpps = returnPoints.filter(p => isBP(p, opponentId));
    const breakPointsWonCount = myBPOpps.filter(p => p.winnerId === playerId).length;

    return {
      firstServePercentage: createDetailed(firstServesInCount, firstServesTotalCount),
      secondServePercentage: createDetailed(secondServesInCount, secondServesTotalCount),
      aces: points.filter(p => p.winnerId === playerId && p.outcome === 'Ace').length,
      doubleFaults: points.filter(p => p.loserId === playerId && p.outcome === 'Double Fault').length,
      winners: points.filter(p => p.winnerId === playerId && p.outcome === 'Winner').length,
      unforcedErrors: points.filter(p => p.loserId === playerId && p.outcome === 'Unforced Error').length,
      forcedErrors: points.filter(p => p.loserId === playerId && p.outcome === 'Forced Error').length,
      firstServePointsWon: createDetailed(firstServePointsWonCount, firstServePointsTotalCount),
      secondServePointsWon: createDetailed(secondServePointsWonCount, secondServePointsTotalCount),
      breakPointsSaved: createDetailed(breakPointsSavedCount, opponentBPOpps.length),
      firstReturnPointsWon: createDetailed(firstReturnPointsWonCount, firstReturnPointsTotalCount),
      secondReturnPointsWon: createDetailed(secondReturnPointsWonCount, secondReturnPointsTotalCount),
      breakPointsWon: createDetailed(breakPointsWonCount, myBPOpps.length),
      totalPointsWon: points.filter(p => p.winnerId === playerId).length,
      pointsWonPct: points.length > 0 ? (points.filter(p => p.winnerId === playerId).length / points.length) * 100 : 0,
      touches04: points.filter(p => p.winnerId === playerId && p.rallyLength <= 4).length,
      touches58: points.filter(p => p.winnerId === playerId && p.rallyLength > 4 && p.rallyLength <= 8).length,
      touches9plus: points.filter(p => p.winnerId === playerId && p.rallyLength > 8).length
    };
  };

  return {
    p1: getStats(p1Id),
    p2: getStats(p2Id)
  };
}

export function calculateShotBreakdown(points: Point[], p1Id: string, p2Id: string, outcomeType: Outcome): ShotStatRow[] {
  const rows: ShotStatRow[] = [];
  const relevantPoints = points.filter(p => p.outcome === outcomeType);

  const shotKeys = [
    { label: 'Forehand', side: 'Forehand', kind: 'Regular' },
    { label: 'Forehand Volley', side: 'Forehand', kind: 'Volley' },
    { label: 'Forehand Slice', side: 'Forehand', kind: 'Slice' },
    { label: 'Forehand Return', side: 'Forehand', kind: 'Return' },
    { label: 'Inside-In', side: 'Forehand', kind: 'Inside-In' },
    { label: 'Inside-Out', side: 'Forehand', kind: 'Inside-Out' },
    { label: 'Backhand', side: 'Backhand', kind: 'Regular' },
    { label: 'Backhand Slice', side: 'Backhand', kind: 'Slice' },
    { label: 'Backhand Return', side: 'Backhand', kind: 'Return' },
    { label: 'Backhand Volley', side: 'Backhand', kind: 'Volley' },
    { label: 'Approach', side: '', kind: 'Approach' },
    { label: 'Drop Shot', side: '', kind: 'Drop Shot' },
  ];

  shotKeys.forEach(k => {
    const p1Count = relevantPoints.filter(p => {
      const isRelevant = (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p1Id : p.loserId === p1Id;
      if (!isRelevant) return false;
      const sideMatch = !k.side || p.shotSide === k.side;
      const kindMatch = !k.kind || p.shotKind === k.kind || (k.kind === 'Regular' && !p.shotKind);
      return sideMatch && kindMatch;
    }).length;

    const p2Count = relevantPoints.filter(p => {
      const isRelevant = (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p2Id : p.loserId === p2Id;
      if (!isRelevant) return false;
      const sideMatch = !k.side || p.shotSide === k.side;
      const kindMatch = !k.kind || p.shotKind === k.kind || (k.kind === 'Regular' && !p.shotKind);
      return sideMatch && kindMatch;
    }).length;

    if (p1Count > 0 || p2Count > 0) {
      rows.push({ label: k.label, p1: p1Count, p2: p2Count });
    }
  });

  const totalP1 = relevantPoints.filter(p => (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p1Id : p.loserId === p1Id).length;
  const totalP2 = relevantPoints.filter(p => (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p2Id : p.loserId === p2Id).length;
  rows.push({ label: 'Total', p1: totalP1, p2: totalP2 });

  return rows;
}

export function getPointDescription(p: Point, players: {id: string, name: string}[]): string {
  const winner = players.find(pl => pl.id === p.winnerId)?.name;
  const loser = players.find(pl => pl.id === p.loserId)?.name;

  if (p.outcome === 'Winner' || p.outcome === 'Ace') {
    if (p.shotSide || p.shotKind) {
        return `${winner} won the point with a ${p.location?.toLowerCase() || ''} ${p.shotSide?.toLowerCase() || ''} ${p.shotKind?.toLowerCase() || ''} winner`.replace(/\s+/g, ' ').trim();
    }
    return `${winner} won the point`;
  } else {
    const detail = `${p.errorType || ''} ${p.location || ''} ${p.shotSide || ''} ${p.outcome === 'Unforced Error' ? 'unforced error' : 'forced error'}`.toLowerCase().replace(/\s+/g, ' ').trim();
    return `${loser} loses the point with a ${detail}`;
  }
}

export function isWinningPointOfGame(p: Point, config: MatchConfig): boolean {
  const s = p.scoreAtStart;
  const winnerId = p.winnerId;
  const isP1 = winnerId === config.p1Id;

  if (config.adScoring) {
    if (isP1) {
      return (s.p1Points === '40' && s.p2Points !== '40' && s.p2Points !== 'Ad') || (s.p1Points === 'Ad');
    } else {
      return (s.p2Points === '40' && s.p1Points !== '40' && s.p1Points !== 'Ad') || (s.p2Points === 'Ad');
    }
  } else {
    if (isP1) {
      return s.p1Points === '40';
    } else {
      return s.p2Points === '40';
    }
  }
}

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);
  const [score, setScore] = React.useState<CurrentScore>(() => {
    // Add missing isTieBreak property to satisfy CurrentScore interface
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Modal temporary states
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    if (isReadOnly || score.isMatchOver) return;
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleUndo = () => {
    if (points.length === 0) return;

    const newPoints = points.slice(0, -1);
    setPoints(newPoints);

    // Recalculate the entire score from scratch based on the remaining points
    // Add missing isTieBreak property to satisfy CurrentScore interface
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    newPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
    setServeNumber(1);

    // If it's a permanent record (not just transient state), notify parent
    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);
    resetModalState();
    if (newScore.isMatchOver && onFinish) onFinish(newPoints);
    else if (onPause) onPause(newPoints); // Keep match synced even during play
  };

  const handleBack = () => {
    if (!isReadOnly && !score.isMatchOver && onPause) {
      onPause(points);
    } else {
      onCancel();
    }
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  const step1Outcome = outcome !== null;
  const isError = outcome === 'Unforced Error' || outcome === 'Forced Error';
  const needsSide = outcome === 'Winner' || isError;
  const step2Side = needsSide && shotSide !== null;
  const step3Kind = step2Side && shotKind !== null;

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[12px] text-center font-bold text-black mt-8 mb-4 tracking-widest uppercase">{children}</h3>
  );

  return (
    <div className="flex flex-col h-screen bg-iosBg relative overflow-hidden">
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <button onClick={handleBack} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary relative">
            <button className="opacity-40 cursor-not-allowed">
              <i className="fa-solid fa-tower-broadcast"></i>
            </button>
            <button 
              onClick={handleUndo} 
              disabled={points.length === 0}
              className={`${(points.length === 0) ? 'opacity-30' : 'active:scale-90 transition-transform'}`}
              title="Undo Point"
            >
              <i className="fa-solid fa-rotate-left"></i>
            </button>
            <div className="relative">
              <button 
                onClick={() => setShowMoreMenu(!showMoreMenu)}
                className="active:scale-90 transition-transform"
              >
