export default ActiveMatchView;

import { Point, MatchConfig, Outcome, ShotKind } from '../types';

export const POINT_VALUES = ['0', '15', '30', '40', 'Ad'];

export interface SetScore {
  p1: number;
  p2: number;
}

export interface CurrentScore {
  p1Points: string;
  p2Points: string;
  p1Games: number;
  p2Games: number;
  p1Sets: number;
  p2Sets: number;
  setHistory: SetScore[];
  servingPlayerId: string;
  isGameOver: boolean;
  isSetOver: boolean;
  isMatchOver: boolean;
  isTieBreak: boolean;
}

export function calculateNewScore(
  current: CurrentScore,
  winnerId: string,
  p1Id: string,
  p2Id: string,
  config: MatchConfig
): CurrentScore {
  let { p1Points, p2Points, p1Games, p2Games, p1Sets, p2Sets, servingPlayerId, setHistory, isTieBreak } = current;
  const isP1 = winnerId === p1Id;

  if (isTieBreak) {
    // Tie-break point progression (0, 1, 2, 3...)
    let p1P = parseInt(p1Points) || 0;
    let p2P = parseInt(p2Points) || 0;

    if (isP1) p1P++; else p2P++;

    // Check for tie-break win (at least 7 points and 2 clear)
    if ((p1P >= 7 || p2P >= 7) && Math.abs(p1P - p2P) >= 2) {
      // Tie-break over. Award the set 7-6.
      return awardSet({ ...current, p1Points: p1P.toString(), p2Points: p2P.toString() }, isP1 ? p1Id : p2Id, p1Id, p2Id, config, true);
    }

    // Standard tie-break service rotation: Player who received first point serves next 2, then rotate every 2 points.
    const totalPoints = p1P + p2P;
    if (totalPoints % 2 === 1) {
       servingPlayerId = (servingPlayerId === p1Id) ? p2Id : p1Id;
    }

    return { ...current, p1Points: p1P.toString(), p2Points: p2P.toString(), servingPlayerId };
  }

  // Standard Game logic
  if (config.adScoring) {
    if (isP1) {
      if (p1Points === '40') {
        if (p2Points === 'Ad') p2Points = '40';
        else if (p2Points === '40') p1Points = 'Ad';
        else return awardGame(current, p1Id, p1Id, p2Id, config);
      } else if (p1Points === 'Ad') {
        return awardGame(current, p1Id, p1Id, p2Id, config);
      } else {
        p1Points = nextPoint(p1Points);
      }
    } else {
      if (p2Points === '40') {
        if (p1Points === 'Ad') p1Points = '40';
        else if (p1Points === '40') p2Points = 'Ad';
        else return awardGame(current, p2Id, p1Id, p2Id, config);
      } else if (p2Points === 'Ad') {
        return awardGame(current, p2Id, p1Id, p2Id, config);
      } else {
        p2Points = nextPoint(p2Points);
      }
    }
  } else {
    if (isP1) {
      if (p1Points === '40') return awardGame(current, p1Id, p1Id, p2Id, config);
      p1Points = nextPoint(p1Points);
    } else {
      if (p2Points === '40') return awardGame(current, p2Id, p1Id, p2Id, config);
      p2Points = nextPoint(p2Points);
    }
  }

  return { ...current, p1Points, p2Points };
}

function nextPoint(p: string): string {
  if (p === '0') return '15';
  if (p === '15') return '30';
  if (p === '30') return '40';
  return '0';
}

function awardGame(current: CurrentScore, winnerId: string, p1Id: string, p2Id: string, config: MatchConfig): CurrentScore {
  let { p1Games, p2Games, servingPlayerId } = current;
  if (winnerId === p1Id) p1Games++; else p2Games++;

  const p1Points = '0';
  const p2Points = '0';
  const nextServingPlayerId = servingPlayerId === p1Id ? p2Id : p1Id;

  const gamesNeeded = config.gamesPerSet;

  // Create an intermediate state with updated games for logic checking
  const updatedWithGame: CurrentScore = {
    ...current,
    p1Points,
    p2Points,
    p1Games,
    p2Games,
    servingPlayerId: nextServingPlayerId
  };

  // Check for Tie-break trigger (6-6)
  if (config.tieBreak && p1Games === gamesNeeded && p2Games === gamesNeeded) {
    return { ...updatedWithGame, isTieBreak: true };
  }

  // Check for normal set win
  if (p1Games >= gamesNeeded && (Math.abs(p1Games - p2Games) >= 2 || (!config.tieBreak && p1Games > gamesNeeded))) {
    return awardSet(updatedWithGame, p1Id, p1Id, p2Id, config, false);
  } else if (p2Games >= gamesNeeded && (Math.abs(p2Games - p1Games) >= 2 || (!config.tieBreak && p2Games > gamesNeeded))) {
    return awardSet(updatedWithGame, p2Id, p1Id, p2Id, config, false);
  }

  return updatedWithGame;
}

function awardSet(current: CurrentScore, winnerId: string, p1Id: string, p2Id: string, config: MatchConfig, viaTieBreak: boolean): CurrentScore {
  let { p1Games, p2Games, p1Sets, p2Sets, setHistory, servingPlayerId } = current;

  // Note: p1Games and p2Games are already updated by the caller (awardGame or calculateNewScore for tiebreak)
  if (winnerId === p1Id) p1Sets++; else p2Sets++;

  const newHistory = [...setHistory, { p1: p1Games, p2: p2Games }];

  const setsToWinCount = typeof config.setsToWin === 'number' ? Math.ceil(config.setsToWin / 2) : 1;
  const isMatchOver = p1Sets >= setsToWinCount || p2Sets >= setsToWinCount;

  return { 
    ...current, 
    p1Points: '0', 
    p2Points: '0', 
    p1Games: 0, 
    p2Games: 0, 
    p1Sets, 
    p2Sets, 
    setHistory: newHistory, 
    servingPlayerId, // already rotated in awardGame
    isMatchOver, 
    isSetOver: true,
    isTieBreak: false 
  };
}

export function getScoreDetails(points: Point[], config: MatchConfig): CurrentScore {
  let current: CurrentScore = {
    p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0,
    setHistory: [], servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
  };

  points.forEach(p => {
    current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
  });

  return current;
}

export function getFinalScoreString(points: Point[], config: MatchConfig): string {
  const current = getScoreDetails(points, config);

  if (config.setsToWin === 1) {
      return `${current.p1Games}-${current.p2Games}`;
  }

  const setsString = current.setHistory.map(s => `${s.p1}-${s.p2}`).join(', ');
  return `${current.p1Sets}-${current.p2Sets} (${setsString}${current.setHistory.length > 0 && (current.p1Games > 0 || current.p2Games > 0) ? ', ' : ''}${(!current.isMatchOver && (current.p1Games > 0 || current.p2Games > 0)) ? `${current.p1Games}-${current.p2Games}` : ''})`;
}

export interface DetailedStat {
  won: number;
  total: number;
  pct: number;
}

export interface ShotStatRow {
  label: string;
  p1: number;
  p2: number;
}

export function calculateStats(points: Point[], p1Id: string, p2Id: string) {
  const getStats = (playerId: string) => {
    const opponentId = playerId === p1Id ? p2Id : p1Id;
    const servicePoints = points.filter(p => p.serverPlayerId === playerId);
    const returnPoints = points.filter(p => p.serverPlayerId === opponentId);

    const firstServesInCount = servicePoints.filter(p => p.serveNumber === 1 && p.outcome !== 'Double Fault').length;
    const firstServesTotalCount = servicePoints.length; 
    const secondServesInCount = servicePoints.filter(p => p.serveNumber === 2 && p.outcome !== 'Double Fault').length;
    const secondServesTotalCount = servicePoints.filter(p => p.serveNumber === 2).length;

    const createDetailed = (won: number, total: number): DetailedStat => ({
      won,
      total,
      pct: total > 0 ? (won / total) * 100 : 0
    });

    const firstServePointsWonCount = servicePoints.filter(p => p.serveNumber === 1 && p.winnerId === playerId).length;
    const firstServePointsTotalCount = servicePoints.filter(p => p.serveNumber === 1).length;
    const secondServePointsWonCount = servicePoints.filter(p => p.serveNumber === 2 && p.winnerId === playerId).length;
    const secondServePointsTotalCount = servicePoints.filter(p => p.serveNumber === 2).length;

    const isBP = (p: Point, serverId: string) => {
      const s = p.scoreAtStart;
      const isP1Serving = serverId === p1Id;
      if (isP1Serving) {
        return (s.p2Points === '40' && s.p1Points !== '40' && s.p1Points !== 'Ad') || (s.p2Points === 'Ad');
      } else {
        return (s.p1Points === '40' && s.p2Points !== '40' && s.p2Points !== 'Ad') || (s.p1Points === 'Ad');
      }
    };

    const opponentBPOpps = servicePoints.filter(p => isBP(p, playerId));
    const breakPointsSavedCount = opponentBPOpps.filter(p => p.winnerId === playerId).length;
    const firstReturnPointsWonCount = returnPoints.filter(p => p.serveNumber === 1 && p.winnerId === playerId).length;
    const firstReturnPointsTotalCount = returnPoints.filter(p => p.serveNumber === 1).length;
    const secondReturnPointsWonCount = returnPoints.filter(p => p.serveNumber === 2 && p.winnerId === playerId).length;
    const secondReturnPointsTotalCount = returnPoints.filter(p => p.serveNumber === 2).length;
    const myBPOpps = returnPoints.filter(p => isBP(p, opponentId));
    const breakPointsWonCount = myBPOpps.filter(p => p.winnerId === playerId).length;

    return {
      firstServePercentage: createDetailed(firstServesInCount, firstServesTotalCount),
      secondServePercentage: createDetailed(secondServesInCount, secondServesTotalCount),
      aces: points.filter(p => p.winnerId === playerId && p.outcome === 'Ace').length,
      doubleFaults: points.filter(p => p.loserId === playerId && p.outcome === 'Double Fault').length,
      winners: points.filter(p => p.winnerId === playerId && p.outcome === 'Winner').length,
      unforcedErrors: points.filter(p => p.loserId === playerId && p.outcome === 'Unforced Error').length,
      forcedErrors: points.filter(p => p.loserId === playerId && p.outcome === 'Forced Error').length,
      firstServePointsWon: createDetailed(firstServePointsWonCount, firstServePointsTotalCount),
      secondServePointsWon: createDetailed(secondServePointsWonCount, secondServePointsTotalCount),
      breakPointsSaved: createDetailed(breakPointsSavedCount, opponentBPOpps.length),
      firstReturnPointsWon: createDetailed(firstReturnPointsWonCount, firstReturnPointsTotalCount),
      secondReturnPointsWon: createDetailed(secondReturnPointsWonCount, secondReturnPointsTotalCount),
      breakPointsWon: createDetailed(breakPointsWonCount, myBPOpps.length),
      totalPointsWon: points.filter(p => p.winnerId === playerId).length,
      pointsWonPct: points.length > 0 ? (points.filter(p => p.winnerId === playerId).length / points.length) * 100 : 0,
      touches04: points.filter(p => p.winnerId === playerId && p.rallyLength <= 4).length,
      touches58: points.filter(p => p.winnerId === playerId && p.rallyLength > 4 && p.rallyLength <= 8).length,
      touches9plus: points.filter(p => p.winnerId === playerId && p.rallyLength > 8).length
    };
  };

  return {
    p1: getStats(p1Id),
    p2: getStats(p2Id)
  };
}

export function calculateShotBreakdown(points: Point[], p1Id: string, p2Id: string, outcomeType: Outcome): ShotStatRow[] {
  const rows: ShotStatRow[] = [];
  const relevantPoints = points.filter(p => p.outcome === outcomeType);

  const shotKeys = [
    { label: 'Forehand', side: 'Forehand', kind: 'Regular' },
    { label: 'Forehand Volley', side: 'Forehand', kind: 'Volley' },
    { label: 'Forehand Slice', side: 'Forehand', kind: 'Slice' },
    { label: 'Forehand Return', side: 'Forehand', kind: 'Return' },
    { label: 'Inside-In', side: 'Forehand', kind: 'Inside-In' },
    { label: 'Inside-Out', side: 'Forehand', kind: 'Inside-Out' },
    { label: 'Backhand', side: 'Backhand', kind: 'Regular' },
    { label: 'Backhand Slice', side: 'Backhand', kind: 'Slice' },
    { label: 'Backhand Return', side: 'Backhand', kind: 'Return' },
    { label: 'Backhand Volley', side: 'Backhand', kind: 'Volley' },
    { label: 'Approach', side: '', kind: 'Approach' },
    { label: 'Drop Shot', side: '', kind: 'Drop Shot' },
  ];

  shotKeys.forEach(k => {
    const p1Count = relevantPoints.filter(p => {
      const isRelevant = (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p1Id : p.loserId === p1Id;
      if (!isRelevant) return false;
      const sideMatch = !k.side || p.shotSide === k.side;
      const kindMatch = !k.kind || p.shotKind === k.kind || (k.kind === 'Regular' && !p.shotKind);
      return sideMatch && kindMatch;
    }).length;

    const p2Count = relevantPoints.filter(p => {
      const isRelevant = (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p2Id : p.loserId === p2Id;
      if (!isRelevant) return false;
      const sideMatch = !k.side || p.shotSide === k.side;
      const kindMatch = !k.kind || p.shotKind === k.kind || (k.kind === 'Regular' && !p.shotKind);
      return sideMatch && kindMatch;
    }).length;

    if (p1Count > 0 || p2Count > 0) {
      rows.push({ label: k.label, p1: p1Count, p2: p2Count });
    }
  });

  const totalP1 = relevantPoints.filter(p => (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p1Id : p.loserId === p1Id).length;
  const totalP2 = relevantPoints.filter(p => (outcomeType === 'Winner' || outcomeType === 'Ace') ? p.winnerId === p2Id : p.loserId === p2Id).length;
  rows.push({ label: 'Total', p1: totalP1, p2: totalP2 });

  return rows;
}

export function getPointDescription(p: Point, players: {id: string, name: string}[]): string {
  const winner = players.find(pl => pl.id === p.winnerId)?.name;
  const loser = players.find(pl => pl.id === p.loserId)?.name;

  if (p.outcome === 'Winner' || p.outcome === 'Ace') {
    if (p.shotSide || p.shotKind) {
        return `${winner} won the point with a ${p.location?.toLowerCase() || ''} ${p.shotSide?.toLowerCase() || ''} ${p.shotKind?.toLowerCase() || ''} winner`.replace(/\s+/g, ' ').trim();
    }
    return `${winner} won the point`;
  } else {
    const detail = `${p.errorType || ''} ${p.location || ''} ${p.shotSide || ''} ${p.outcome === 'Unforced Error' ? 'unforced error' : 'forced error'}`.toLowerCase().replace(/\s+/g, ' ').trim();
    return `${loser} loses the point with a ${detail}`;
  }
}

export function isWinningPointOfGame(p: Point, config: MatchConfig): boolean {
  const s = p.scoreAtStart;
  const winnerId = p.winnerId;
  const isP1 = winnerId === config.p1Id;

  if (config.adScoring) {
    if (isP1) {
      return (s.p1Points === '40' && s.p2Points !== '40' && s.p2Points !== 'Ad') || (s.p1Points === 'Ad');
    } else {
      return (s.p2Points === '40' && s.p1Points !== '40' && s.p1Points !== 'Ad') || (s.p2Points === 'Ad');
    }
  } else {
    if (isP1) {
      return s.p1Points === '40';
    } else {
      return s.p2Points === '40';
    }
  }
}

import React from 'react';
import Layout from './components/Layout';
import { Tab, Player, Match, MatchConfig, Point } from './types';
import { loadPlayers, loadMatches, savePlayers, saveMatches } from './store';
import MatchesView from './views/MatchesView';
import PlayersView from './views/PlayersView';
import SetupView from './views/SetupView';
import ActiveMatchView from './views/ActiveMatchView';
import AddPlayerView from './views/AddPlayerView';
import { getFinalScoreString, getScoreDetails } from './logic/tennisLogic';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = React.useState<Tab>(Tab.Matches);
  const [players, setPlayers] = React.useState<Player[]>([]);
  const [matches, setMatches] = React.useState<Match[]>([]);
  const [isSettingUp, setIsSettingUp] = React.useState(false);
  const [isAddingPlayer, setIsAddingPlayer] = React.useState(false);
  const [activeMatchConfig, setActiveMatchConfig] = React.useState<MatchConfig | null>(null);
  const [activeMatchId, setActiveMatchId] = React.useState<string | null>(null);
  const [viewingMatch, setViewingMatch] = React.useState<Match | null>(null);
  const [editingSettingsMatch, setEditingSettingsMatch] = React.useState<Match | null>(null);

  React.useEffect(() => {
    setPlayers(loadPlayers());
    setMatches(loadMatches());
  }, []);

  const handleStartMatch = (config: MatchConfig) => {
    if (config.existingMatchId) {
      // Handle saving edited settings for an existing match
      const updatedMatches = matches.map(m => {
        if (m.id === config.existingMatchId) {
           const finalScore = getFinalScoreString(m.points, config);
           const details = getScoreDetails(m.points, config);
           return { ...m, config, finalScore, isCompleted: details.isMatchOver };
        }
        return m;
      });
      setMatches(updatedMatches);
      saveMatches(updatedMatches);

      const updatedMatch = updatedMatches.find(m => m.id === config.existingMatchId);

      // If we were editing from viewing, update viewing state
      if (viewingMatch && viewingMatch.id === config.existingMatchId) {
        setViewingMatch(updatedMatch || null);
      }

      // If we were editing an ACTIVE match, update the active config state
      if (activeMatchId === config.existingMatchId) {
        setActiveMatchConfig(config);
      }

      setEditingSettingsMatch(null);
      setIsSettingUp(false);
      return;
    }

    const newId = Date.now().toString();
    const newMatch: Match = {
      id: newId,
      date: new Date().toISOString(),
      config: config,
      points: [],
      isCompleted: false,
      finalScore: "0-0 (0-0)"
    };

    const updated = [newMatch, ...matches];
    setMatches(updated);
    saveMatches(updated);

    setActiveMatchConfig(config);
    setActiveMatchId(newId);
    setIsSettingUp(false);
    setActiveTab(Tab.Active);
  };

  const handleResumeMatch = (match: Match) => {
    setActiveMatchConfig(match.config);
    setActiveMatchId(match.id);
    setActiveTab(Tab.Active);
  };

  const handleFinishMatch = (points: Point[]) => {
    if (!activeMatchId || !activeMatchConfig) return;

    const finalScore = getFinalScoreString(points, activeMatchConfig);

    const updatedMatches = matches.map(m => 
      m.id === activeMatchId 
        ? { ...m, points, isCompleted: true, finalScore } 
        : m
    );

    setMatches(updatedMatches);
    saveMatches(updatedMatches);

    setActiveMatchConfig(null);
    setActiveMatchId(null);
    setActiveTab(Tab.Matches);
  };

  const handlePauseMatch = (points: Point[]) => {
    const id = activeMatchId || viewingMatch?.id;
    const config = activeMatchConfig || viewingMatch?.config;
    if (!id || !config) return;

    const currentScore = getFinalScoreString(points, config);

    const updatedMatches = matches.map(m => 
      m.id === id 
        ? { ...m, points, finalScore: currentScore } 
        : m
    );

    setMatches(updatedMatches);
    saveMatches(updatedMatches);

    // If we're coming from viewing/editing a completed match, update that state too
    if (viewingMatch && viewingMatch.id === id) {
      setViewingMatch(updatedMatches.find(m => m.id === id)!);
    }
  };

  const handleUpdatePoints = (points: Point[]) => {
    const id = activeMatchId || viewingMatch?.id;
    const config = activeMatchConfig || viewingMatch?.config;
    if (!id || !config) return;

    const currentScore = getFinalScoreString(points, config);
    const details = getScoreDetails(points, config);

    const updatedMatches = matches.map(m => 
      m.id === id 
        ? { ...m, points, finalScore: currentScore, isCompleted: details.isMatchOver } 
        : m
    );

    setMatches(updatedMatches);
    saveMatches(updatedMatches);

    if (viewingMatch && viewingMatch.id === id) {
       setViewingMatch(updatedMatches.find(m => m.id === id)!);
    }
  };

  const handleSavePlayer = (playerData: Omit<Player, 'id'>) => {
    const newPlayer: Player = {
      ...playerData,
      id: Date.now().toString(),
    };
    const updated = [...players, newPlayer];
    setPlayers(updated);
    savePlayers(updated);
    setIsAddingPlayer(false);
  };

  if (isAddingPlayer) {
    return <AddPlayerView onSave={handleSavePlayer} onCancel={() => setIsAddingPlayer(false)} />;
  }

  // Edit settings takes precedence over display
  if (isSettingUp || editingSettingsMatch) {
    const editConfig = editingSettingsMatch ? { ...editingSettingsMatch.config, existingMatchId: editingSettingsMatch.id } : undefined;
    return (
      <SetupView 
        players={players} 
        onStartMatch={handleStartMatch} 
        onCancel={() => { setIsSettingUp(false); setEditingSettingsMatch(null); }} 
        onAddNewPlayer={() => setIsAddingPlayer(true)}
        initialConfig={editConfig}
      />
    );
  }

  if (viewingMatch) {
    return (
      <ActiveMatchView 
        config={viewingMatch.config} 
        players={players} 
        initialPoints={viewingMatch.points}
        onCancel={() => setViewingMatch(null)}
        onUndo={handleUpdatePoints}
        onPause={handlePauseMatch}
        onEditSettings={() => setEditingSettingsMatch(viewingMatch)}
        isReadOnly={false}
      />
    );
  }

  if (activeTab === Tab.Active && activeMatchConfig) {
    const currentMatch = matches.find(m => m.id === activeMatchId);
    return (
      <ActiveMatchView 
        config={activeMatchConfig} 
        players={players} 
        initialPoints={currentMatch?.points || []}
        onFinish={handleFinishMatch} 
        onPause={handlePauseMatch}
        onUndo={handleUpdatePoints}
        onEditSettings={() => setEditingSettingsMatch(currentMatch || null)}
        onCancel={() => { setActiveMatchConfig(null); setActiveTab(Tab.Matches); }} 
      />
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {activeTab === Tab.Matches && (
        <MatchesView 
          matches={matches} 
          players={players} 
          onNewMatch={() => setIsSettingUp(true)} 
          onAddPlayer={() => setIsAddingPlayer(true)}
          onViewMatch={(match) => {
            if (match.isCompleted) {
              setViewingMatch(match);
            } else {
              handleResumeMatch(match);
            }
          }}
        />
      )}
      {activeTab === Tab.Players && (
        <PlayersView 
          players={players} 
          onAddPlayer={() => setIsAddingPlayer(true)}
        />
      )}
      {activeTab === Tab.Active && !activeMatchConfig && (
        <div className="h-full flex flex-col items-center justify-center p-8 text-center bg-iosBg">
           <div className="w-24 h-24 bg-white rounded-3xl shadow-lg flex items-center justify-center mb-6">
              <i className="fa-solid fa-tennis-ball text-primary text-5xl"></i>
           </div>
           <h2 className="text-2xl font-bold mb-2">No Active Match</h2>
           <p className="text-iosGray mb-8">Start a new match or resume an incomplete one from the Matches list.</p>
           <button 
             onClick={() => setIsSettingUp(true)}
             className="w-full max-w-xs py-4 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-transform"
           >
             Start New Match
           </button>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);
  const [score, setScore] = React.useState<CurrentScore>(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Modal temporary states
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    if (isReadOnly || score.isMatchOver) return;
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleUndo = () => {
    if (points.length === 0) return;

    const newPoints = points.slice(0, -1);
    setPoints(newPoints);

    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    newPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
    setServeNumber(1);

    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);
    resetModalState();
    if (newScore.isMatchOver && onFinish) onFinish(newPoints);
    else if (onPause) onPause(newPoints);
  };

  const handleBack = () => {
    if (!isReadOnly && !score.isMatchOver && onPause) {
      onPause(points);
    }
    onCancel();
  };

  const handleEditSettings = () => {
    setShowMoreMenu(false);
    if (onEditSettings) {
      onEditSettings(config);
    }
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  const step1Outcome = outcome !== null;
  const isError = outcome === 'Unforced Error' || outcome === 'Forced Error';
  const needsSide = outcome === 'Winner' || isError;
  const step2Side = needsSide && shotSide !== null;
  const step3Kind = step2Side && shotKind !== null;

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[12px] text-center font-bold text-black mt-8 mb-4 tracking-widest uppercase">{children}</h3>
  );

  return (
    <div className="flex flex-col h-screen bg-iosBg relative overflow-hidden">
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <button onClick={handleBack} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary relative">
            <button className="opacity-40 cursor-not-allowed">
              <i className="fa-solid fa-tower-broadcast"></i>
            </button>
            <button 
              onClick={handleUndo} 
              disabled={points.length === 0}
              className={`${(points.length === 0) ? 'opacity-30' : 'active:scale-90 transition-transform'}`}
              title="Undo Point"
            >
              <i className="fa-solid fa-rotate-left"></i>
            </button>
            <div className="relative">
              <button 
                onClick={() => setShowMoreMenu(!showMoreMenu)}
                className="active:scale-90 transition-transform"
              >
                <i className="fa-solid fa-ellipsis"></i>
              </button>
              {showMoreMenu && (
                <div className="absolute right-0 top-10 w-52 bg-white border border-iosDivider rounded-xl shadow-2xl py-1 z-[60] overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                  <button 
                    onClick={handleEditSettings}
                    className="w-full text-left px-4 py-4 text-sm font-semibold hover:bg-iosBg flex items-center gap-3 active:bg-iosBg/50"
                  >
                    <i className="fa-solid fa-gear text-primary opacity-60"></i>
                    Edit Match Settings
                  </button>
                </div>
              )}
            </div>
        </div>
      </header>

      {showMoreMenu && <div className="fixed inset-0 z-50" onClick={() => setShowMoreMenu(false)} />}

      <div className="flex-1 overflow-y-auto pb-44">
        <div className="p-4">
          <Card className="p-0 border-none shadow-md overflow-hidden">
            <div className="bg-primary text-white px-4 py-2.5 text-[10px] font-bold flex justify-between uppercase tracking-widest items-center">
              <span>{new Date(config.existingMatchId ? Number(config.existingMatchId) : Date.now()).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            </div>
            <div className="p-4 space-y-4 bg-white">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[12px] font-black uppercase">{p1.name[0]}</div>
                  <span className="text-sm font-bold">{p1.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((set, idx) => (
                    <span key={idx} className="text-iosGray text-sm font-bold opacity-60">
                      {set.p1}
                    </span>
                  ))}
                  <span className="font-black text-xl">{score.p1Games}</span>
                </div>
              </div>
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[12px] font-black uppercase">{p2.name[0]}</div>
                  <span className="text-sm font-bold">{p2.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((set, idx) => (
                    <span key={idx} className="text-iosGray text-sm font-bold opacity-60">
                      {set.p2}
                    </span>
                  ))}
                  <span className="font-black text-xl">{score.p2Games}</span>
                </div>
              </div>
            </div>
          </Card>
        </div>

        <div className="px-6 pb-6 pt-2 flex justify-between relative items-center">
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
            {!score.isMatchOver && score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute left-4 top-2 animate-pulse shadow-sm"></div>}
            <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p1.name[0]}</span>
            <span className="text-8xl scoreboard-font text-primary tracking-tighter">{score.p1Points}</span>
          </div>
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
            {!score.isMatchOver && score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-4 top-2 animate-pulse shadow-sm"></div>}
            <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p2.name[0]}</span>
            <span className="text-8xl scoreboard-font text-black tracking-tighter">{score.p2Points}</span>
          </div>
        </div>

        {!isReadOnly && !score.isMatchOver && (
          <div className="px-4 mb-6">
            <SegmentedControl
              options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
              value={serveNumber}
              onChange={(v: any) => setServeNumber(v)}
            />
          </div>
        )}

        <div className="px-4">
          {activeSubTab === 'Match Stats' && (
            <Card className="divide-y divide-iosDivider/10 border-none shadow-none bg-transparent">
              <StatRow label="1st serve percentage" val1={stats.p1.firstServePercentage} val2={stats.p2.firstServePercentage} isPercentOnly />
              <StatRow label="2nd serve percentage" val1={stats.p1.secondServePercentage} val2={stats.p2.secondServePercentage} isPercentOnly />
              <StatRow label="aces" val1={stats.p1.aces} val2={stats.p2.aces} />
              <StatRow label="double faults" val1={stats.p1.doubleFaults} val2={stats.p2.doubleFaults} />
              <StatRow label="winners" val1={stats.p1.winners} val2={stats.p2.winners} />
              <StatRow label="unforced errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
              <StatRow label="forced errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
              <StatRow label="1st serve points won" val1={stats.p1.firstServePointsWon} val2={stats.p2.firstServePointsWon} />
              <StatRow label="2nd serve points won" val1={stats.p1.secondServePointsWon} val2={stats.p2.secondServePointsWon} />
              <StatRow label="break points saved" val1={stats.p1.breakPointsSaved} val2={stats.p2.breakPointsSaved} />
              <StatRow label="1st return points won" val1={stats.p1.firstReturnPointsWon} val2={stats.p2.firstReturnPointsWon} />
              <StatRow label="2nd return points won" val1={stats.p1.secondReturnPointsWon} val2={stats.p2.secondReturnPointsWon} />
              <StatRow label="break points won" val1={stats.p1.breakPointsWon} val2={stats.p2.breakPointsWon} />
              <StatRow label="total points won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
              <StatRow label="% of points won" val1={stats.p1.pointsWonPct} val2={stats.p2.pointsWonPct} isPercentOnly />
              <StatRow label="0-4 touches" val1={stats.p1.touches04} val2={stats.p2.touches04} />
              <StatRow label="5-8 touches" val1={stats.p1.touches58} val2={stats.p2.touches58} />
              <StatRow label="9+ touches" val1={stats.p1.touches9plus} val2={stats.p2.touches9plus} />
            </Card>
          )}

          {activeSubTab === 'Shot Stats' && (
            <div className="space-y-6">
              <ShotSection title="Winners" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Winner')} />
              <ShotSection title="Forced Errors" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Forced Error')} />
              <ShotSection title="Unforced Errors" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Unforced Error')} />
            </div>
          )}

          {activeSubTab === 'Match Log' && (
             <div className="bg-white rounded-xl overflow-hidden border border-iosDivider/20 mb-10 shadow-sm">
                {points.slice().reverse().map((p, i) => {
                  const isGameOverPoint = isWinningPointOfGame(p, config);

                  return (
                    <React.Fragment key={i}>
                      {(i === 0 && score.isMatchOver) && (
                        <div className="bg-primary text-white text-[11px] font-black text-center py-2.5 uppercase tracking-widest">
                          Game, Set, Match, {players.find(pl => pl.id === points[points.length-1].winnerId)?.name}
                        </div>
                      )}

                      {isGameOverPoint && (
                        <div className="bg-primary text-white text-[11px] font-black text-center py-2.5 uppercase tracking-widest">
                          Game, {players.find(pl => pl.id === p.winnerId)?.name}
                        </div>
                      )}

                      <div className="flex justify-between items-center px-4 py-5 border-b border-iosDivider/10 bg-white">
                        <div className="w-12 flex items-center justify-start gap-2">
                          <span className="text-[13px] font-bold text-black">{p.scoreAtStart.p1Points}</span>
                          {p.winnerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                        </div>

                        <div className="flex-1 px-4 text-center">
                           <p className="text-[12px] font-medium leading-tight text-black/80">
                             {getPointDescription(p, players)}
                           </p>
                        </div>

                        <div className="w-12 flex items-center justify-end gap-2 text-right">
                          {p.winnerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                          <span className="text-[13px] font-bold text-black">{p.scoreAtStart.p2Points}</span>
                        </div>
                      </div>
                    </React.Fragment>
                  );
                })}
             </div>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-iosDivider/30 flex justify-around px-4 pt-4 pb-10 z-50 shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <button onClick={() => setActiveSubTab('Match Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-chart-simple text-xl ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Match Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Shot Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-magnifying-glass text-xl ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Shot Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Match Log')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-list-ul text-xl ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/70'}`}>Match Log</span>
        </button>
      </div>

      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
          <div className="flex-1 overflow-y-auto px-6 pt-20 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8 uppercase tracking-tight">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {showDoubleFault && <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => { setOutcome('Double Fault'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              {!showDoubleFault && showAce && <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => { setOutcome('Ace'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => { setOutcome('Winner'); setServePlacement(null); }} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }} />
            </div>

            {step1Outcome && outcome === 'Double Fault' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                  <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                  <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                </div>
              </div>
            )}

            {step1Outcome && outcome === 'Ace' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Wide" active={servePlacement === 'Wide'} onClick={() => setServePlacement('Wide')} />
                  <BlueBtn label="Body" active={servePlacement === 'Body'} onClick={() => setServePlacement('Body')} />
                  <BlueBtn label="T" active={servePlacement === 'T'} onClick={() => setServePlacement('T')} />
                </div>
              </div>
            )}

            {step1Outcome && needsSide && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Side</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                  <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                </div>
              </div>
            )}

            {step2Side && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Shot Kind</SectionLabel>
                <div className="grid grid-cols-3 gap-2">
                  {(['Regular', 'Return', 'Inside-In', 'Inside-Out', 'Passing', 'Approach', 'Slice', 'Volley', 'Drop Shot', 'Lob', 'Overhead'] as ShotKind[]).map(k => (
                    <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k)} className="text-[12px] py-2" />
                  ))}
                </div>
              </div>
            )}

            {step3Kind && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <div className="space-y-4">
                  <div>
                    <SectionLabel>Location</SectionLabel>
                    <div className="grid grid-cols-3 gap-3">
                      <BlueBtn label="Cross Court" active={location === 'Cross Court'} onClick={() => setLocation('Cross Court')} className="text-[11px] px-1" />
                      <BlueBtn label="Middle" active={location === 'Middle'} onClick={() => setLocation('Middle')} className="text-[11px] px-1" />
                      <BlueBtn label="Down the Line" active={location === 'Down the Line'} onClick={() => setLocation('Down the Line')} className="text-[11px] px-1" />
                    </div>
                  </div>

                  {isError && (
                    <div>
                      <SectionLabel>Error Type</SectionLabel>
                      <div className="grid grid-cols-3 gap-3">
                        <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                        <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                        <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="mt-12 px-2 animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center justify-between mb-4">
                <span className="text-[15px] font-bold">Rally Length:</span>
                <div className="flex items-center gap-4 text-primary font-bold">
                  <button onClick={() => setRallyLength(Math.max(0, rallyLength - 1))} className="text-3xl font-normal">－</button>
                  <span className="text-xl w-6 text-center">{rallyLength}</span>
                  <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal">＋</button>
                </div>
              </div>
              <input 
                type="range" min="0" max="30" value={rallyLength} 
                onChange={e => setRallyLength(parseInt(e.target.value))} 
                className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
              />
            </div>
          </div>

          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg uppercase tracking-wider">
              Cancel
            </button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg ring-offset-2 hover:ring-2 hover:ring-primary/20 uppercase tracking-wider">
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) {
        return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(2)}%</span>;
      }
      return (
        <div className="flex flex-col items-center min-w-[60px]">
          <span className="text-[13px] font-bold text-black">{detailed.won}/{detailed.total}</span>
          <span className="text-[11px] font-medium text-iosGray">({detailed.pct.toFixed(2)}%)</span>
        </div>
      );
    }
    if (typeof val === 'number' && isPercentOnly) {
      return <span className="text-[13px] font-bold text-black">{val.toFixed(2)}%</span>;
    }
    return <span className="text-[14px] font-bold text-black">{val}</span>;
  };

  return (
    <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 last:border-0 bg-white">
      <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
      <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center px-2 leading-tight uppercase tracking-tight">{label}</span>
      <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
    </div>
  );
};

const ShotSection: React.FC<{ title: string; rows: any[] }> = ({ title, rows }) => (
  <section className="mb-4">
    <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-4 tracking-widest">{title}</h4>
    <Card className="divide-y divide-iosDivider/10 bg-white shadow-none border-t border-b border-iosDivider/30 rounded-none">
      {rows.map((row, i) => (
        <div key={i} className={`flex justify-between items-center px-4 py-3.5 ${row.label === 'Total' ? 'bg-iosBg/40' : ''}`}>
          <span className={`text-[13px] w-12 text-left ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p1}</span>
          <span className={`text-[12px] flex-1 text-center ${row.label === 'Total' ? 'font-black uppercase tracking-widest' : 'text-black font-medium'}`}>{row.label}</span>
          <span className={`text-[13px] w-12 text-right ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p2}</span>
        </div>
      ))}
    </Card>
  </section>
);

export default ActiveMatchView;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);

  // Local score state needs to be synchronized when config or points change
  const [score, setScore] = React.useState<CurrentScore>(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  // Sync score if config prop changes (e.g. from Edit Match Settings)
  React.useEffect(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    points.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
  }, [config]);

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Modal temporary states
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    if (isReadOnly || score.isMatchOver) return;
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleUndo = () => {
    if (points.length === 0) return;

    const newPoints = points.slice(0, -1);
    setPoints(newPoints);

    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    newPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
    setServeNumber(1);

    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);
    resetModalState();
    if (newScore.isMatchOver && onFinish) onFinish(newPoints);
    else if (onPause) onPause(newPoints);
  };

  const handleBack = () => {
    if (!isReadOnly && !score.isMatchOver && onPause) {
      onPause(points);
    }
    onCancel();
  };

  const handleEditSettings = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowMoreMenu(false);
    if (onEditSettings) {
      onEditSettings(config);
    }
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  const step1Outcome = outcome !== null;
  const isError = outcome === 'Unforced Error' || outcome === 'Forced Error';
  const needsSide = outcome === 'Winner' || isError;
  const step2Side = needsSide && shotSide !== null;
  const step3Kind = step2Side && shotKind !== null;

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[12px] text-center font-bold text-black mt-8 mb-4 tracking-widest uppercase">{children}</h3>
  );

  return (
    <div className="flex flex-col h-screen bg-iosBg relative overflow-hidden">
      {/* Header Z-index must be higher than overlay to allow clicking the menu button */}
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-[70]">
        <button onClick={handleBack} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary relative">
            <button className="opacity-40 cursor-not-allowed">
              <i className="fa-solid fa-tower-broadcast"></i>
            </button>
            <button 
              onClick={handleUndo} 
              disabled={points.length === 0}
              className={`${(points.length === 0) ? 'opacity-30' : 'active:scale-90 transition-transform'}`}
              title="Undo Point"
            >
              <i className="fa-solid fa-rotate-left"></i>
            </button>
            <div className="relative">
              <button 
                onClick={(e) => { e.stopPropagation(); setShowMoreMenu(!showMoreMenu); }}
                className="active:scale-90 transition-transform"
              >
                <i className="fa-solid fa-ellipsis"></i>
              </button>
              {showMoreMenu && (
                <div className="absolute right-0 top-10 w-52 bg-white border border-iosDivider rounded-xl shadow-2xl py-1 z-[80] overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                  <button 
                    onClick={handleEditSettings}
                    className="w-full text-left px-4 py-4 text-sm font-semibold hover:bg-iosBg flex items-center gap-3 active:bg-iosBg/50"
                  >
                    <i className="fa-solid fa-gear text-primary opacity-60"></i>
                    Edit Match Settings
                  </button>
                </div>
              )}
            </div>
        </div>
      </header>

      {/* Overlay to close menu when tapping outside */}
      {showMoreMenu && <div className="fixed inset-0 z-[65] bg-transparent" onClick={() => setShowMoreMenu(false)} />}

      <div className="flex-1 overflow-y-auto pb-44">
        <div className="p-4">
          <Card className="p-0 border-none shadow-md overflow-hidden">
            <div className="bg-primary text-white px-4 py-2.5 text-[10px] font-bold flex justify-between uppercase tracking-widest items-center">
              <span>{new Date(config.existingMatchId ? Number(config.existingMatchId) : Date.now()).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            </div>
            <div className="p-4 space-y-4 bg-white">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[12px] font-black uppercase">{p1.name[0]}</div>
                  <span className="text-sm font-bold">{p1.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((set, idx) => (
                    <span key={idx} className="text-iosGray text-sm font-bold opacity-60">
                      {set.p1}
                    </span>
                  ))}
                  <span className="font-black text-xl tabular-nums">{score.p1Games}</span>
                </div>
              </div>
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[12px] font-black uppercase">{p2.name[0]}</div>
                  <span className="text-sm font-bold">{p2.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((set, idx) => (
                    <span key={idx} className="text-iosGray text-sm font-bold opacity-60">
                      {set.p2}
                    </span>
                  ))}
                  <span className="font-black text-xl tabular-nums">{score.p2Games}</span>
                </div>
              </div>
            </div>
          </Card>
        </div>

        <div className="px-6 pb-6 pt-2 flex justify-between relative items-center">
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
            {!score.isMatchOver && score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute left-4 top-2 animate-pulse shadow-sm"></div>}
            <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p1.name[0]}</span>
            <span className="text-8xl scoreboard-font text-primary tracking-tighter tabular-nums">{score.p1Points}</span>
          </div>
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
            {!score.isMatchOver && score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-4 top-2 animate-pulse shadow-sm"></div>}
            <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p2.name[0]}</span>
            <span className="text-8xl scoreboard-font text-black tracking-tighter tabular-nums">{score.p2Points}</span>
          </div>
        </div>

        {!isReadOnly && !score.isMatchOver && (
          <div className="px-4 mb-6">
            <SegmentedControl
              options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
              value={serveNumber}
              onChange={(v: any) => setServeNumber(v)}
            />
          </div>
        )}

        <div className="px-4">
          {activeSubTab === 'Match Stats' && (
            <Card className="divide-y divide-iosDivider/10 border-none shadow-none bg-transparent">
              <StatRow label="1st serve percentage" val1={stats.p1.firstServePercentage} val2={stats.p2.firstServePercentage} isPercentOnly />
              <StatRow label="2nd serve percentage" val1={stats.p1.secondServePercentage} val2={stats.p2.secondServePercentage} isPercentOnly />
              <StatRow label="aces" val1={stats.p1.aces} val2={stats.p2.aces} />
              <StatRow label="double faults" val1={stats.p1.doubleFaults} val2={stats.p2.doubleFaults} />
              <StatRow label="winners" val1={stats.p1.winners} val2={stats.p2.winners} />
              <StatRow label="unforced errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
              <StatRow label="forced errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
              <StatRow label="1st serve points won" val1={stats.p1.firstServePointsWon} val2={stats.p2.firstServePointsWon} />
              <StatRow label="2nd serve points won" val1={stats.p1.secondServePointsWon} val2={stats.p2.secondServePointsWon} />
              <StatRow label="break points saved" val1={stats.p1.breakPointsSaved} val2={stats.p2.breakPointsSaved} />
              <StatRow label="1st return points won" val1={stats.p1.firstReturnPointsWon} val2={stats.p2.firstReturnPointsWon} />
              <StatRow label="2nd return points won" val1={stats.p1.secondReturnPointsWon} val2={stats.p2.secondReturnPointsWon} />
              <StatRow label="break points won" val1={stats.p1.breakPointsWon} val2={stats.p2.breakPointsWon} />
              <StatRow label="total points won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
              <StatRow label="% of points won" val1={stats.p1.pointsWonPct} val2={stats.p2.pointsWonPct} isPercentOnly />
              <StatRow label="0-4 touches" val1={stats.p1.touches04} val2={stats.p2.touches04} />
              <StatRow label="5-8 touches" val1={stats.p1.touches58} val2={stats.p2.touches58} />
              <StatRow label="9+ touches" val1={stats.p1.touches9plus} val2={stats.p2.touches9plus} />
            </Card>
          )}

          {activeSubTab === 'Shot Stats' && (
            <div className="space-y-6">
              <ShotSection title="Winners" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Winner')} />
              <ShotSection title="Forced Errors" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Forced Error')} />
              <ShotSection title="Unforced Errors" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Unforced Error')} />
            </div>
          )}

          {activeSubTab === 'Match Log' && (
             <div className="bg-white rounded-xl overflow-hidden border border-iosDivider/20 mb-10 shadow-sm">
                {points.slice().reverse().map((p, i) => {
                  const isGameOverPoint = isWinningPointOfGame(p, config);

                  return (
                    <React.Fragment key={i}>
                      {(i === 0 && score.isMatchOver) && (
                        <div className="bg-primary text-white text-[11px] font-black text-center py-2.5 uppercase tracking-widest">
                          Game, Set, Match, {players.find(pl => pl.id === points[points.length-1].winnerId)?.name}
                        </div>
                      )}

                      {isGameOverPoint && (
                        <div className="bg-primary text-white text-[11px] font-black text-center py-2.5 uppercase tracking-widest">
                          Game, {players.find(pl => pl.id === p.winnerId)?.name}
                        </div>
                      )}

                      <div className="flex justify-between items-center px-4 py-5 border-b border-iosDivider/10 bg-white">
                        <div className="w-12 flex items-center justify-start gap-2 text-primary font-black">
                          <span className="text-[13px]">{p.scoreAtStart.p1Points}</span>
                          {p.winnerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                        </div>

                        <div className="flex-1 px-4 text-center">
                           <p className="text-[12px] font-medium leading-tight text-black/80">
                             {getPointDescription(p, players)}
                           </p>
                        </div>

                        <div className="w-12 flex items-center justify-end gap-2 text-right font-black">
                          {p.winnerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                          <span className="text-[13px]">{p.scoreAtStart.p2Points}</span>
                        </div>
                      </div>
                    </React.Fragment>
                  );
                })}
             </div>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-iosDivider/30 flex justify-around px-4 pt-4 pb-10 z-50 shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <button onClick={() => setActiveSubTab('Match Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-chart-simple text-xl ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Match Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Shot Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-magnifying-glass text-xl ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Shot Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Match Log')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-list-ul text-xl ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/70'}`}>Match Log</span>
        </button>
      </div>

      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
          <div className="flex-1 overflow-y-auto px-6 pt-20 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8 uppercase tracking-tight">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {showDoubleFault && <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => { setOutcome('Double Fault'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              {!showDoubleFault && showAce && <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => { setOutcome('Ace'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => { setOutcome('Winner'); setServePlacement(null); }} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }} />
            </div>

            {step1Outcome && outcome === 'Double Fault' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                  <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                  <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                </div>
              </div>
            )}

            {step1Outcome && outcome === 'Ace' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Wide" active={servePlacement === 'Wide'} onClick={() => setServePlacement('Wide')} />
                  <BlueBtn label="Body" active={servePlacement === 'Body'} onClick={() => setServePlacement('Body')} />
                  <BlueBtn label="T" active={servePlacement === 'T'} onClick={() => setServePlacement('T')} />
                </div>
              </div>
            )}

            {step1Outcome && needsSide && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Side</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                  <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                </div>
              </div>
            )}

            {step2Side && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Shot Kind</SectionLabel>
                <div className="grid grid-cols-3 gap-2">
                  {(['Regular', 'Return', 'Inside-In', 'Inside-Out', 'Passing', 'Approach', 'Slice', 'Volley', 'Drop Shot', 'Lob', 'Overhead'] as ShotKind[]).map(k => (
                    <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k)} className="text-[12px] py-2" />
                  ))}
                </div>
              </div>
            )}

            {step3Kind && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <div className="space-y-4">
                  <div>
                    <SectionLabel>Location</SectionLabel>
                    <div className="grid grid-cols-3 gap-3">
                      <BlueBtn label="Cross Court" active={location === 'Cross Court'} onClick={() => setLocation('Cross Court')} className="text-[11px] px-1" />
                      <BlueBtn label="Middle" active={location === 'Middle'} onClick={() => setLocation('Middle')} className="text-[11px] px-1" />
                      <BlueBtn label="Down the Line" active={location === 'Down the Line'} onClick={() => setLocation('Down the Line')} className="text-[11px] px-1" />
                    </div>
                  </div>

                  {isError && (
                    <div>
                      <SectionLabel>Error Type</SectionLabel>
                      <div className="grid grid-cols-3 gap-3">
                        <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                        <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                        <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="mt-12 px-2 animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center justify-between mb-4">
                <span className="text-[15px] font-bold">Rally Length:</span>
                <div className="flex items-center gap-4 text-primary font-bold">
                  <button onClick={() => setRallyLength(Math.max(0, rallyLength - 1))} className="text-3xl font-normal">－</button>
                  <span className="text-xl w-6 text-center">{rallyLength}</span>
                  <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal">＋</button>
                </div>
              </div>
              <input 
                type="range" min="0" max="30" value={rallyLength} 
                onChange={e => setRallyLength(parseInt(e.target.value))} 
                className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
              />
            </div>
          </div>

          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg uppercase tracking-wider">
              Cancel
            </button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg ring-offset-2 hover:ring-2 hover:ring-primary/20 uppercase tracking-wider">
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) {
        return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(2)}%</span>;
      }
      return (
        <div className="flex flex-col items-center min-w-[60px]">
          <span className="text-[13px] font-bold text-black tabular-nums">{detailed.won}/{detailed.total}</span>
          <span className="text-[11px] font-medium text-iosGray tabular-nums">({detailed.pct.toFixed(2)}%)</span>
        </div>
      );
    }
    if (typeof val === 'number' && isPercentOnly) {
      return <span className="text-[13px] font-bold text-black tabular-nums">{val.toFixed(2)}%</span>;
    }
    return <span className="text-[14px] font-bold text-black tabular-nums">{val}</span>;
  };

  return (
    <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 last:border-0 bg-white">
      <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
      <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center px-2 leading-tight uppercase tracking-tight">{label}</span>
      <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
    </div>
  );
};

const ShotSection: React.FC<{ title: string; rows: any[] }> = ({ title, rows }) => (
  <section className="mb-4">
    <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-4 tracking-widest">{title}</h4>
    <Card className="divide-y divide-iosDivider/10 bg-white shadow-none border-t border-b border-iosDivider/30 rounded-none">
      {rows.map((row, i) => (
        <div key={i} className={`flex justify-between items-center px-4 py-3.5 ${row.label === 'Total' ? 'bg-iosBg/40' : ''}`}>
          <span className={`text-[13px] w-12 text-left tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p1}</span>
          <span className={`text-[12px] flex-1 text-center ${row.label === 'Total' ? 'font-black uppercase tracking-widest' : 'text-black font-medium'}`}>{row.label}</span>
          <span className={`text-[13px] w-12 text-right tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p2}</span>
        </div>
      ))}
    </Card>
  </section>
);

export default ActiveMatchView;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);

  // Local score state needs to be synchronized when config or points change
  const [score, setScore] = React.useState<CurrentScore>(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  // Sync score if config prop changes (e.g. from Edit Match Settings)
  React.useEffect(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    points.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
  }, [config]);

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Modal temporary states
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    if (isReadOnly || score.isMatchOver) return;
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleUndo = () => {
    if (points.length === 0) return;

    const newPoints = points.slice(0, -1);
    setPoints(newPoints);

    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    newPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
    setServeNumber(1);

    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);
    resetModalState();
    if (newScore.isMatchOver && onFinish) onFinish(newPoints);
    else if (onPause) onPause(newPoints);
  };

  const handleBack = () => {
    if (!isReadOnly && !score.isMatchOver && onPause) {
      onPause(points);
    }
    onCancel();
  };

  const handleEditSettings = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowMoreMenu(false);
    if (onEditSettings) {
      onEditSettings(config);
    }
  };

  const winnerIsServer = pointModal.winnerId === score.servingPlayerId;
  const showDoubleFault = !winnerIsServer && serveNumber === 2;
  const showAce = winnerIsServer;

  const step1Outcome = outcome !== null;
  const isError = outcome === 'Unforced Error' || outcome === 'Forced Error';
  const needsSide = outcome === 'Winner' || isError;
  const step2Side = needsSide && shotSide !== null;
  const step3Kind = step2Side && shotKind !== null;

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <h3 className="text-[12px] text-center font-bold text-black mt-8 mb-4 tracking-widest uppercase">{children}</h3>
  );

  return (
    <div className="flex flex-col h-screen bg-iosBg relative overflow-hidden">
      {/* Header Z-index must be higher than overlay to allow clicking the menu button */}
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-[70]">
        <button onClick={handleBack} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary relative">
            <button 
              onClick={handleUndo} 
              disabled={points.length === 0}
              className={`${(points.length === 0) ? 'opacity-30' : 'active:scale-90 transition-transform'}`}
              title="Undo Point"
            >
              <i className="fa-solid fa-rotate-left"></i>
            </button>
            <div className="relative">
              <button 
                onClick={(e) => { e.stopPropagation(); setShowMoreMenu(!showMoreMenu); }}
                className="active:scale-90 transition-transform"
              >
                <i className="fa-solid fa-ellipsis"></i>
              </button>
              {showMoreMenu && (
                <div className="absolute right-0 top-10 w-52 bg-white border border-iosDivider rounded-xl shadow-2xl py-1 z-[80] overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                  <button 
                    onClick={handleEditSettings}
                    className="w-full text-left px-4 py-4 text-sm font-semibold hover:bg-iosBg flex items-center gap-3 active:bg-iosBg/50"
                  >
                    <i className="fa-solid fa-gear text-primary opacity-60"></i>
                    Edit Match Settings
                  </button>
                </div>
              )}
            </div>
        </div>
      </header>

      {/* Overlay to close menu when tapping outside */}
      {showMoreMenu && <div className="fixed inset-0 z-[65] bg-transparent" onClick={() => setShowMoreMenu(false)} />}

      <div className="flex-1 overflow-y-auto pb-44">
        <div className="p-4">
          <Card className="p-0 border-none shadow-md overflow-hidden">
            <div className="bg-primary text-white px-4 py-2.5 text-[10px] font-bold flex justify-between uppercase tracking-widest items-center">
              <span>{new Date(config.existingMatchId ? Number(config.existingMatchId) : Date.now()).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
            </div>
            <div className="p-4 space-y-4 bg-white">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[12px] font-black uppercase">{p1.name[0]}</div>
                  <span className="text-sm font-bold">{p1.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((set, idx) => (
                    <span key={idx} className="text-iosGray text-sm font-bold opacity-60">
                      {set.p1}
                    </span>
                  ))}
                  <span className="font-black text-xl tabular-nums">{score.p1Games}</span>
                </div>
              </div>
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-white text-[12px] font-black uppercase">{p2.name[0]}</div>
                  <span className="text-sm font-bold">{p2.name}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((set, idx) => (
                    <span key={idx} className="text-iosGray text-sm font-bold opacity-60">
                      {set.p2}
                    </span>
                  ))}
                  <span className="font-black text-xl tabular-nums">{score.p2Games}</span>
                </div>
              </div>
            </div>
          </Card>
        </div>

        <div className="px-6 pb-6 pt-2 flex justify-between relative items-center">
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p1.id, p2.id)}>
            {!score.isMatchOver && score.servingPlayerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute left-4 top-2 animate-pulse shadow-sm"></div>}
            <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p1.name[0]}</span>
            <span className="text-8xl scoreboard-font text-primary tracking-tighter tabular-nums">{score.p1Points}</span>
          </div>
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick(p2.id, p1.id)}>
            {!score.isMatchOver && score.servingPlayerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-4 top-2 animate-pulse shadow-sm"></div>}
            <span className="text-sm font-bold text-iosGray mb-1 uppercase tracking-tighter">{p2.name[0]}</span>
            <span className="text-8xl scoreboard-font text-black tracking-tighter tabular-nums">{score.p2Points}</span>
          </div>
        </div>

        {!isReadOnly && !score.isMatchOver && (
          <div className="px-4 mb-6">
            <SegmentedControl
              options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]}
              value={serveNumber}
              onChange={(v: any) => setServeNumber(v)}
            />
          </div>
        )}

        <div className="px-4">
          {activeSubTab === 'Match Stats' && (
            <Card className="divide-y divide-iosDivider/10 border-none shadow-none bg-transparent">
              <StatRow label="1st serve percentage" val1={stats.p1.firstServePercentage} val2={stats.p2.firstServePercentage} isPercentOnly />
              <StatRow label="2nd serve percentage" val1={stats.p1.secondServePercentage} val2={stats.p2.secondServePercentage} isPercentOnly />
              <StatRow label="aces" val1={stats.p1.aces} val2={stats.p2.aces} />
              <StatRow label="double faults" val1={stats.p1.doubleFaults} val2={stats.p2.doubleFaults} />
              <StatRow label="winners" val1={stats.p1.winners} val2={stats.p2.winners} />
              <StatRow label="unforced errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
              <StatRow label="forced errors" val1={stats.p1.forcedErrors} val2={stats.p2.forcedErrors} />
              <StatRow label="1st serve points won" val1={stats.p1.firstServePointsWon} val2={stats.p2.firstServePointsWon} />
              <StatRow label="2nd serve points won" val1={stats.p1.secondServePointsWon} val2={stats.p2.secondServePointsWon} />
              <StatRow label="break points saved" val1={stats.p1.breakPointsSaved} val2={stats.p2.breakPointsSaved} />
              <StatRow label="1st return points won" val1={stats.p1.firstReturnPointsWon} val2={stats.p2.firstReturnPointsWon} />
              <StatRow label="2nd return points won" val1={stats.p1.secondReturnPointsWon} val2={stats.p2.secondReturnPointsWon} />
              <StatRow label="break points won" val1={stats.p1.breakPointsWon} val2={stats.p2.breakPointsWon} />
              <StatRow label="total points won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
              <StatRow label="% of points won" val1={stats.p1.pointsWonPct} val2={stats.p2.pointsWonPct} isPercentOnly />
              <StatRow label="0-4 touches" val1={stats.p1.touches04} val2={stats.p2.touches04} />
              <StatRow label="5-8 touches" val1={stats.p1.touches58} val2={stats.p2.touches58} />
              <StatRow label="9+ touches" val1={stats.p1.touches9plus} val2={stats.p2.touches9plus} />
            </Card>
          )}

          {activeSubTab === 'Shot Stats' && (
            <div className="space-y-6">
              <ShotSection title="Winners" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Winner')} />
              <ShotSection title="Forced Errors" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Forced Error')} />
              <ShotSection title="Unforced Errors" rows={calculateShotBreakdown(points, p1.id, p2.id, 'Unforced Error')} />
            </div>
          )}

          {activeSubTab === 'Match Log' && (
             <div className="bg-white rounded-xl overflow-hidden border border-iosDivider/20 mb-10 shadow-sm">
                {points.slice().reverse().map((p, i) => {
                  const isGameOverPoint = isWinningPointOfGame(p, config);

                  return (
                    <React.Fragment key={i}>
                      {(i === 0 && score.isMatchOver) && (
                        <div className="bg-primary text-white text-[11px] font-black text-center py-2.5 uppercase tracking-widest">
                          Game, Set, Match, {players.find(pl => pl.id === points[points.length-1].winnerId)?.name}
                        </div>
                      )}

                      {isGameOverPoint && (
                        <div className="bg-primary text-white text-[11px] font-black text-center py-2.5 uppercase tracking-widest">
                          Game, {players.find(pl => pl.id === p.winnerId)?.name}
                        </div>
                      )}

                      <div className="flex justify-between items-center px-4 py-5 border-b border-iosDivider/10 bg-white">
                        <div className="w-12 flex items-center justify-start gap-2 text-primary font-black">
                          <span className="text-[13px]">{p.scoreAtStart.p1Points}</span>
                          {p.winnerId === p1.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                        </div>

                        <div className="flex-1 px-4 text-center">
                           <p className="text-[12px] font-medium leading-tight text-black/80">
                             {getPointDescription(p, players)}
                           </p>
                        </div>

                        <div className="w-12 flex items-center justify-end gap-2 text-right font-black">
                          {p.winnerId === p2.id && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full shrink-0 shadow-sm" />}
                          <span className="text-[13px]">{p.scoreAtStart.p2Points}</span>
                        </div>
                      </div>
                    </React.Fragment>
                  );
                })}
             </div>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-iosDivider/30 flex justify-around px-4 pt-4 pb-10 z-50 shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <button onClick={() => setActiveSubTab('Match Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-chart-simple text-xl ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Match Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Shot Stats')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-magnifying-glass text-xl ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Shot Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Match Log')} className="flex flex-col items-center gap-1.5 transition-colors flex-1">
          <i className={`fa-solid fa-list-ul text-xl ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase tracking-widest ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/70'}`}>Match Log</span>
        </button>
      </div>

      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
          <div className="flex-1 overflow-y-auto px-6 pt-20 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8 uppercase tracking-tight">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {showDoubleFault && <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => { setOutcome('Double Fault'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              {!showDoubleFault && showAce && <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => { setOutcome('Ace'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => { setOutcome('Winner'); setServePlacement(null); }} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }} />
            </div>

            {step1Outcome && outcome === 'Double Fault' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                  <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                  <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                </div>
              </div>
            )}

            {step1Outcome && outcome === 'Ace' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
                <div className="grid grid-cols-3 gap-3">
                  <BlueBtn label="Wide" active={servePlacement === 'Wide'} onClick={() => setServePlacement('Wide')} />
                  <BlueBtn label="Body" active={servePlacement === 'Body'} onClick={() => setServePlacement('Body')} />
                  <BlueBtn label="T" active={servePlacement === 'T'} onClick={() => setServePlacement('T')} />
                </div>
              </div>
            )}

            {step1Outcome && needsSide && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Side</SectionLabel>
                <div className="grid grid-cols-2 gap-3">
                  <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                  <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                </div>
              </div>
            )}

            {step2Side && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Shot Kind</SectionLabel>
                <div className="grid grid-cols-3 gap-2">
                  {(['Regular', 'Return', 'Inside-In', 'Inside-Out', 'Passing', 'Approach', 'Slice', 'Volley', 'Drop Shot', 'Lob', 'Overhead'] as ShotKind[]).map(k => (
                    <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k)} className="text-[12px] py-2" />
                  ))}
                </div>
              </div>
            )}

            {step3Kind && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <div className="space-y-4">
                  <div>
                    <SectionLabel>Location</SectionLabel>
                    <div className="grid grid-cols-3 gap-3">
                      <BlueBtn label="Cross Court" active={location === 'Cross Court'} onClick={() => setLocation('Cross Court')} className="text-[11px] px-1" />
                      <BlueBtn label="Middle" active={location === 'Middle'} onClick={() => setLocation('Middle')} className="text-[11px] px-1" />
                      <BlueBtn label="Down the Line" active={location === 'Down the Line'} onClick={() => setLocation('Down the Line')} className="text-[11px] px-1" />
                    </div>
                  </div>

                  {isError && (
                    <div>
                      <SectionLabel>Error Type</SectionLabel>
                      <div className="grid grid-cols-3 gap-3">
                        <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                        <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                        <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="mt-12 px-2 animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center justify-between mb-4">
                <span className="text-[15px] font-bold">Rally Length:</span>
                <div className="flex items-center gap-4 text-primary font-bold">
                  <button onClick={() => setRallyLength(Math.max(0, rallyLength - 1))} className="text-3xl font-normal">－</button>
                  <span className="text-xl w-6 text-center">{rallyLength}</span>
                  <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal">＋</button>
                </div>
              </div>
              <input 
                type="range" min="0" max="30" value={rallyLength} 
                onChange={e => setRallyLength(parseInt(e.target.value))} 
                className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
              />
            </div>
          </div>

          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg uppercase tracking-wider">
              Cancel
            </button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg ring-offset-2 hover:ring-2 hover:ring-primary/20 uppercase tracking-wider">
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) {
        return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(2)}%</span>;
      }
      return (
        <div className="flex flex-col items-center min-w-[60px]">
          <span className="text-[13px] font-bold text-black tabular-nums">{detailed.won}/{detailed.total}</span>
          <span className="text-[11px] font-medium text-iosGray tabular-nums">({detailed.pct.toFixed(2)}%)</span>
        </div>
      );
    }
    if (typeof val === 'number' && isPercentOnly) {
      return <span className="text-[13px] font-bold text-black tabular-nums">{val.toFixed(2)}%</span>;
    }
    return <span className="text-[14px] font-bold text-black tabular-nums">{val}</span>;
  };

  return (
    <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 last:border-0 bg-white">
      <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
      <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center px-2 leading-tight uppercase tracking-tight">{label}</span>
      <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
    </div>
  );
};

