                onChange={e => setName(e.target.value)} 
                className="flex-1 text-right text-black border-none focus:ring-0 text-[15px] bg-transparent outline-none placeholder:text-iosGray/40" 
              />
            </label>
            <label className="flex items-center px-4 py-4 justify-between bg-white cursor-text">
              <span className="text-[15px] font-medium text-black">Team</span>
