                      <BlueBtn label="Cross Court" active={location === 'Cross Court'} onClick={() => setLocation('Cross Court')} className="text-[11px] px-1" />
                      <BlueBtn label="Middle" active={location === 'Middle'} onClick={() => setLocation('Middle')} className="text-[11px] px-1" />
                      <BlueBtn label="Down the Line" active={location === 'Down the Line'} onClick={() => setLocation('Down the Line')} className="text-[11px] px-1" />
                    </div>
                  </div>

                  {isError && (
                    <div>
                      <SectionLabel>Error Type</SectionLabel>
                      <div className="grid grid-cols-3 gap-3">
                        <BlueBtn label="Long" active={errorType === 'Long'} onClick={() => setErrorType('Long')} />
                        <BlueBtn label="Net" active={errorType === 'Net'} onClick={() => setErrorType('Net')} />
                        <BlueBtn label="Wide" active={errorType === 'Wide'} onClick={() => setErrorType('Wide')} />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="mt-12 px-2 animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex items-center justify-between mb-4">
                <span className="text-[15px] font-bold">Rally Length:</span>
                <div className="flex items-center gap-4 text-primary font-bold">
                  <button onClick={() => setRallyLength(Math.max(0, rallyLength - 1))} className="text-3xl font-normal">－</button>
                  <span className="text-xl w-6 text-center">{rallyLength}</span>
                  <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal">＋</button>
                </div>
              </div>
              <input 
                type="range" min="0" max="30" value={rallyLength} 
                onChange={e => setRallyLength(parseInt(e.target.value))} 
                className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
              />
            </div>
          </div>

          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg uppercase tracking-wider">
              Cancel
            </button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg ring-offset-2 hover:ring-2 hover:ring-primary/20 uppercase tracking-wider">
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) {
        return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(2)}%</span>;
      }
      return (
        <div className="flex flex-col items-center min-w-[60px]">
          <span className="text-[13px] font-bold text-black tabular-nums">{detailed.won}/{detailed.total}</span>
          <span className="text-[11px] font-medium text-iosGray tabular-nums">({detailed.pct.toFixed(2)}%)</span>
        </div>
      );
    }
    if (typeof val === 'number' && isPercentOnly) {
      return <span className="text-[13px] font-bold text-black tabular-nums">{val.toFixed(2)}%</span>;
    }
    return <span className="text-[14px] font-bold text-black tabular-nums">{val}</span>;
  };

  return (
    <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 last:border-0 bg-white">
      <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
      <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center px-2 leading-tight uppercase tracking-tight">{label}</span>
      <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
    </div>
  );
};

const ShotSection: React.FC<{ title: string; rows: any[] }> = ({ title, rows }) => (
  <section className="mb-4">
    <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-4 tracking-widest">{title}</h4>
    <Card className="divide-y divide-iosDivider/10 bg-white shadow-none border-t border-b border-iosDivider/30 rounded-none">
      {rows.map((row, i) => (
        <div key={i} className={`flex justify-between items-center px-4 py-3.5 ${row.label === 'Total' ? 'bg-iosBg/40' : ''}`}>
          <span className={`text-[13px] w-12 text-left tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p1}</span>
          <span className={`text-[12px] flex-1 text-center ${row.label === 'Total' ? 'font-black uppercase tracking-widest' : 'text-black font-medium'}`}>{row.label}</span>
          <span className={`text-[13px] w-12 text-right tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p2}</span>
