        <div className="fixed inset-0 bg-white z-[100] flex flex-col animate-in fade-in slide-in-from-bottom-5 duration-300">
          <div className="flex-1 overflow-y-auto px-6 pt-20 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8 uppercase tracking-tight">How did {players.find(p=>p.id===pointModal.winnerId)?.name} win the point?</h2>

            <div className="grid grid-cols-2 gap-3 mb-2">
              {showDoubleFault && <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => { setOutcome('Double Fault'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              {!showDoubleFault && showAce && <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => { setOutcome('Ace'); setShotSide(null); setShotKind(null); setLocation(null); setErrorType(null); setServePlacement(null); }} />}
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => { setOutcome('Winner'); setServePlacement(null); }} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => { setOutcome('Unforced Error'); setServePlacement(null); }} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => { setOutcome('Forced Error'); setServePlacement(null); }} />
            </div>

            {step1Outcome && outcome === 'Double Fault' && (
              <div className="animate-in slide-in-from-bottom-2 duration-300">
                <SectionLabel>Placement</SectionLabel>
