                  <span className="text-xl w-6 text-center">{rallyLength}</span>
                  <button onClick={() => setRallyLength(rallyLength + 1)} className="text-3xl font-normal">＋</button>
                </div>
              </div>
              <input 
                type="range" min="0" max="30" value={rallyLength} 
                onChange={e => setRallyLength(parseInt(e.target.value))} 
                className="w-full accent-primary h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer" 
              />
            </div>
          </div>

          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-50">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg uppercase tracking-wider">
              Cancel
            </button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all text-lg ring-offset-2 hover:ring-2 hover:ring-primary/20 uppercase tracking-wider">
              Save Point
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) {
        return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(2)}%</span>;
      }
      return (
        <div className="flex flex-col items-center min-w-[60px]">
          <span className="text-[13px] font-bold text-black tabular-nums">{detailed.won}/{detailed.total}</span>
          <span className="text-[11px] font-medium text-iosGray tabular-nums">({detailed.pct.toFixed(2)}%)</span>
        </div>
      );
    }
    if (typeof val === 'number' && isPercentOnly) {
      return <span className="text-[13px] font-bold text-black tabular-nums">{val.toFixed(2)}%</span>;
    }
    return <span className="text-[14px] font-bold text-black tabular-nums">{val}</span>;
  };

  return (
    <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 last:border-0 bg-white">
      <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
      <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center px-2 leading-tight uppercase tracking-tight">{label}</span>
      <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
    </div>
  );
};

const ShotSection: React.FC<{ title: string; rows: any[] }> = ({ title, rows }) => (
  <section className="mb-4">
    <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-4 tracking-widest">{title}</h4>
    <Card className="divide-y divide-iosDivider/10 bg-white shadow-none border-t border-b border-iosDivider/30 rounded-none">
      {rows.map((row, i) => (
        <div key={i} className={`flex justify-between items-center px-4 py-3.5 ${row.label === 'Total' ? 'bg-iosBg/40' : ''}`}>
          <span className={`text-[13px] w-12 text-left tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p1}</span>
          <span className={`text-[12px] flex-1 text-center ${row.label === 'Total' ? 'font-black uppercase tracking-widest' : 'text-black font-medium'}`}>{row.label}</span>
          <span className={`text-[13px] w-12 text-right tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p2}</span>
        </div>
      ))}
    </Card>
  </section>
);

export default ActiveMatchView;

export type HittingArm = 'Left' | 'Right';
export type BackhandType = 'One-Handed' | 'Two-Handed';
export type Outcome = 'Ace' | 'Winner' | 'Unforced Error' | 'Forced Error' | 'Double Fault';
export type ShotKind = 'Regular' | 'Return' | 'Inside-In' | 'Inside-Out' | 'Passing' | 'Approach' | 'Slice' | 'Volley' | 'Drop Shot' | 'Lob' | 'Overhead';
export type ShotLocation = 'Cross Court' | 'Middle' | 'Down the Line';
export type ErrorType = 'Long' | 'Net' | 'Wide';
export type ServePlacement = 'T' | 'Body' | 'Wide';
export type CourtSurface = 'Hard' | 'Clay' | 'Grass';
export type CourtSpeed = 'Slow' | 'Neutral' | 'Fast';
export type CourtType = 'Indoor' | 'Outdoor';
export type ScoringType = 'Simple' | 'Shot Stats';

export interface Player {
  id: string;
  name: string;
  team: string;
  hittingArm: HittingArm;
  backhand: BackhandType;
  utrRating: number;
  isSaved: boolean;
}

export interface Point {
  winnerId: string;
  loserId: string;
  outcome: Outcome;
  serverPlayerId: string;
  serveNumber: 1 | 2;
  shotSide?: 'Forehand' | 'Backhand';
  shotKind?: ShotKind;
  location?: ShotLocation;
  errorType?: ErrorType;
  servePlacement?: ServePlacement;
  rallyLength: number;
  scoreAtStart: {
    p1Points: string;
    p2Points: string;
    p1Games: number;
    p2Games: number;
    p1Sets: number;
    p2Sets: number;
  };
}

export interface MatchConfig {
  p1Id: string;
  p2Id: string;
  initialServerId: string;
  scoringType: ScoringType;
  adScoring: boolean;
  tieBreak: boolean;
  setsToWin: 1 | 3 | 5 | 'Pro Set' | 'Fast4';
  gamesPerSet: number;
  courtSurface: CourtSurface;
  courtSpeed: CourtSpeed;
  courtType: CourtType;
  description: string;
  city: string;
  state: string;
  temperature: string;
  humidity: string;
  round?: string;
  existingMatchId?: string;
}

export interface Match {
  id: string;
  date: string;
  config: MatchConfig;
  points: Point[];
  isCompleted: boolean;
  finalScore: string;
  notes?: string;
}

export enum Tab {
  Matches = 'Matches',
  Players = 'Players',
  Active = 'Active'
}

import React from 'react';
import { Player, MatchConfig, CourtSurface, CourtSpeed, CourtType, ScoringType } from '../types';
import { Header, SegmentedControl, Card } from '../components/UI';

interface SetupViewProps {
  players: Player[];
  onStartMatch: (config: MatchConfig) => void;
  onCancel: () => void;
  onAddNewPlayer: () => void;
  initialConfig?: MatchConfig;
}

const SetupView: React.FC<SetupViewProps> = ({ players, onStartMatch, onCancel, onAddNewPlayer, initialConfig }) => {
  const [matchType, setMatchType] = React.useState<'Singles' | 'Doubles'>('Singles');
  const [p1Id, setP1Id] = React.useState(initialConfig?.p1Id || '');
  const [p2Id, setP2Id] = React.useState(initialConfig?.p2Id || '');
  const [serverId, setServerId] = React.useState(initialConfig?.initialServerId || '');
  const [scoringType, setScoringType] = React.useState<ScoringType>(initialConfig?.scoringType || 'Shot Stats');
  const [adScoring, setAdScoring] = React.useState(initialConfig ? initialConfig.adScoring : true);
  const [tieBreak, setTieBreak] = React.useState(initialConfig ? initialConfig.tieBreak : true);
  const [numSets, setNumSets] = React.useState<any>(initialConfig?.setsToWin || 1);
  const [gamesPerSet, setGamesPerSet] = React.useState(initialConfig?.gamesPerSet || 6);
  const [surface, setSurface] = React.useState<CourtSurface>(initialConfig?.courtSurface || 'Hard');
  const [speed, setSpeed] = React.useState<CourtSpeed>(initialConfig?.courtSpeed || 'Neutral');
  const [type, setType] = React.useState<CourtType>(initialConfig?.courtType || 'Outdoor');

  const [description, setDescription] = React.useState(initialConfig?.description || '');
  const [city, setCity] = React.useState(initialConfig?.city || '');
  const [state, setState] = React.useState(initialConfig?.state || '');
  const [temp, setTemp] = React.useState(initialConfig?.temperature || '');
  const [humidity, setHumidity] = React.useState(initialConfig?.humidity || '');
  const [round, setRound] = React.useState(initialConfig?.round || '');

  const canStart = p1Id && p2Id && serverId;

  const handleStart = () => {
    if (!canStart) return;
    onStartMatch({
      p1Id,
      p2Id,
      initialServerId: serverId,
      scoringType,
      adScoring,
      tieBreak,
      setsToWin: numSets,
      gamesPerSet,
      courtSurface: surface,
      courtSpeed: speed,
      courtType: type,
      description,
      city,
      state,
      temperature: temp,
      humidity,
      round,
      existingMatchId: initialConfig?.existingMatchId
    });
  };

  const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
    <label className="text-[10px] uppercase font-bold text-iosGray ml-4 mb-2 block tracking-tight">
      {children}
    </label>
  );

  return (
    <div className="min-h-screen bg-iosBg pb-20">
      <header className="sticky top-0 bg-iosBg/80 backdrop-blur-md px-4 pt-10 pb-4 flex justify-between items-center z-50">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold text-lg">
          <i className="fa-solid fa-chevron-left text-sm"></i> {initialConfig ? 'Edit Match' : 'Matches'}
        </button>
        <button 
          onClick={handleStart} 
          disabled={!canStart}
          className={`font-semibold text-lg ${canStart ? 'text-primary' : 'text-iosGray opacity-40'}`}
        >
          {initialConfig ? 'Save Changes' : 'Start Match'}
        </button>
      </header>

      <div className="px-4 space-y-6">
        <section>
          <SectionLabel>Match Type</SectionLabel>
          <Card className="p-4">
            <SegmentedControl
              options={[{ label: 'Singles', value: 'Singles' }, { label: 'Doubles', value: 'Doubles' }]}
              value={matchType}
              onChange={(v: any) => setMatchType(v)}
            />
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Players</SectionLabel>
          <Card>
            <button 
              onClick={onAddNewPlayer}
              className="w-full text-left px-4 py-4 text-primary font-bold text-[16px] border-b border-iosDivider/50"
            >
              Add New Player
            </button>
            <div className="p-4 space-y-3">
              <div className="relative">
                <select 
                  value={p1Id} 
                  onChange={(e) => setP1Id(e.target.value)}
                  className="w-full bg-[#E9E9EB] p-3.5 rounded-lg text-[16px] border-none focus:ring-1 focus:ring-primary appearance-none outline-none"
                >
                  <option value="">Player One</option>
                  {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </div>
              <div className="relative">
                <select 
                  value={p2Id} 
                  onChange={(e) => setP2Id(e.target.value)}
                  className="w-full bg-[#E9E9EB] p-3.5 rounded-lg text-[16px] border-none focus:ring-1 focus:ring-primary appearance-none outline-none"
                >
                  <option value="">Player Two</option>
                  {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </div>

              <div className="flex bg-[#E9E9EB] p-1 rounded-lg">
                 <button 
                   onClick={() => p1Id && setServerId(p1Id)}
                   className={`flex-1 py-2 text-xs font-semibold rounded-md transition-all ${serverId === p1Id ? 'bg-white shadow-sm' : 'text-black/60'}`}
                 >
                   {p1Id ? `${players.find(p=>p.id===p1Id)?.name} Serving` : 'Player 1 Serving'}
                 </button>
                 <button 
                   onClick={() => p2Id && setServerId(p2Id)}
                   className={`flex-1 py-2 text-xs font-semibold rounded-md transition-all ${serverId === p2Id ? 'bg-white shadow-sm' : 'text-black/60'}`}
                 >
                   {p2Id ? `${players.find(p=>p.id===p2Id)?.name} Serving` : 'Player 2 Serving'}
                 </button>
              </div>
            </div>
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Number of Sets</SectionLabel>
          <Card className="p-4">
            <SegmentedControl
              options={[
                { label: '1', value: 1 },
                { label: '3', value: 3 },
                { label: '5', value: 5 },
                { label: 'Pro Set', value: 'Pro Set' },
                { label: 'Fast4', value: 'Fast4' }
              ]}
              value={numSets}
              onChange={(v: any) => setNumSets(v)}
            />
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Number of Games per Set</SectionLabel>
          <Card className="p-4 pt-6">
            <input 
              type="range" 
              min="2" 
              max="10" 
              value={gamesPerSet} 
              onChange={(e) => setGamesPerSet(parseInt(e.target.value))}
              className="w-full accent-primary h-1 bg-iosBg rounded-lg appearance-none cursor-pointer mb-6"
            />
            <div className="flex justify-between px-1 text-xs font-bold text-iosGray">
              {[2,3,4,5,6,7,8,9,10].map(n => (
                <span key={n} className={gamesPerSet === n ? 'text-primary' : ''}>{n}</span>
              ))}
            </div>
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Scoring Type</SectionLabel>
          <Card className="p-4">
            <SegmentedControl
              options={[{ label: 'Simple', value: 'Simple' }, { label: 'Shot Stats', value: 'Shot Stats' }]}
              value={scoringType}
              onChange={(v: any) => setScoringType(v)}
            />
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Match Options</SectionLabel>
          <Card className="p-4 space-y-4">
            <SegmentedControl
              options={[{ label: 'Ad Scoring', value: 'ad' }, { label: 'No-Ad Scoring', value: 'no-ad' }]}
              value={adScoring ? 'ad' : 'no-ad'}
              onChange={(v) => setAdScoring(v === 'ad')}
            />
            <SegmentedControl
              options={[{ label: 'Tie Break', value: 'tb' }, { label: 'No Tie Break', value: 'no-tb' }]}
              value={tieBreak ? 'tb' : 'no-tb'}
              onChange={(v) => setTieBreak(v === 'tb')}
            />
          </Card>
        </section>

        <section className="mt-6">
           <SectionLabel>Match Details</SectionLabel>
           <Card className="divide-y divide-iosDivider/30">
              <label className="flex items-center px-4 py-3 justify-between">
                <span className="text-[16px] font-medium">Description</span>
                <input 
                  type="text" 
                  placeholder="Match Description"
                  className="text-right text-iosGray border-none focus:ring-0 text-[16px] bg-transparent outline-none appearance-none"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </label>
              <label className="flex items-center px-4 py-3 justify-between">
                <span className="text-[16px] font-medium">Round #</span>
                <input 
                  type="text" 
                  placeholder="e.g. Final, R16"
                  className="text-right text-iosGray border-none focus:ring-0 text-[16px] bg-transparent outline-none appearance-none"
                  value={round}
                  onChange={(e) => setRound(e.target.value)}
                />
              </label>
           </Card>
        </section>

        <section className="mt-6 pb-12">
          <SectionLabel>Location and Weather</SectionLabel>
          <Card className="divide-y divide-iosDivider/30">
            <button className="w-full p-4 text-center text-primary text-[16px] font-bold">Get Current Location and Weather</button>
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">City</span>
              <input type="text" placeholder="City" value={city} onChange={e=>setCity(e.target.value)} className="text-right text-iosGray border-none focus:ring-0 text-[16px] bg-transparent appearance-none" />
            </div>
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">State</span>
              <input type="text" placeholder="State" value={state} onChange={e=>setState(e.target.value)} className="text-right text-iosGray border-none focus:ring-0 text-[16px] bg-transparent appearance-none" />
            </div>
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">Court Surface</span>
              <SegmentedControl className="max-w-[180px]" options={[{label:'Hard', value:'Hard'}, {label:'Clay', value:'Clay'}, {label:'Grass', value:'Grass'}]} value={surface} onChange={(v: any) => setSurface(v)} />
            </div>
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">Court Speed</span>
              <SegmentedControl className="max-w-[180px]" options={[{label:'Slow', value:'Slow'}, {label:'Neutral', value:'Neutral'}, {label:'Fast', value:'Fast'}]} value={speed} onChange={(v: any) => setSpeed(v)} />
            </div>
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">Court Type</span>
              <SegmentedControl className="max-w-[180px]" options={[{label:'Outdoor', value:'Outdoor'}, {label:'Indoor', value:'Indoor'}]} value={type} onChange={(v: any) => setType(v)} />
            </div>
          </Card>
        </section>
      </div>
    </div>
  );
};

export default SetupView;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame, getFinalScoreString } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  initialNotes?: string;
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUpdateNotes?: (notes: string) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  initialNotes = "",
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUpdateNotes,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);
  const [notes, setNotes] = React.useState(initialNotes);
  const [isNotesOpen, setIsNotesOpen] = React.useState(false);
  const [showExportPrompt, setShowExportPrompt] = React.useState(false);

  // Local score state needs to be synchronized when config or points change
  const [score, setScore] = React.useState<CurrentScore>(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  // Sync score if config prop changes (e.g. from Edit Match Settings)
  React.useEffect(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    points.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
  }, [config, points]);

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const p1 = players.find(p => p.id === config.p1Id)!;
  const p2 = players.find(p => p.id === config.p2Id)!;

  // Modal temporary states
  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, p1.id, p2.id);

  const handlePointClick = (winnerId: string, loserId: string) => {
    if (isReadOnly || score.isMatchOver) return;
    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleUndo = () => {
    if (points.length === 0) return;

    const newPoints = points.slice(0, -1);
    setPoints(newPoints);

    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false
    };
    newPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
    setServeNumber(1);

    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };

    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    const newScore = calculateNewScore(score, pointModal.winnerId, p1.id, p2.id, config);
    setScore(newScore);
    resetModalState();
    if (newScore.isMatchOver && onFinish) onFinish(newPoints);
    else if (onPause) onPause(newPoints);
  };

  const handleBack = () => {
    if (!isReadOnly && !score.isMatchOver && onPause) {
      onPause(points);
    }
    onCancel();
  };

  const handleEditSettings = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowMoreMenu(false);
    if (onEditSettings) {
      onEditSettings(config);
    }
  };

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newNotes = e.target.value;
    setNotes(newNotes);
    if (onUpdateNotes) onUpdateNotes(newNotes);
  };

  const exportMatch = (playerId: string) => {
    const subjectPlayer = players.find(p => p.id === playerId)!;
    const opponentPlayer = players.find(p => p.id === (playerId === p1.id ? p2.id : p1.id))!;
    const subjectStats = playerId === p1.id ? stats.p1 : stats.p2;
    const finalScoreStr = getFinalScoreString(points, config);

    // Breakdown helpers
    const getBreakdown = (type: Outcome) => calculateShotBreakdown(points, p1.id, p2.id, type);
    const filterSubject = (list: any[]) => list.map(r => ({ label: r.label, val: playerId === p1.id ? r.p1 : r.p2 }));

    const winnersSub = filterSubject(getBreakdown('Winner'));
    const forcedSub = filterSubject(getBreakdown('Forced Error'));
    const unforcedSub = filterSubject(getBreakdown('Unforced Error'));

    const renderVal = (list: any[], label: string) => list.find(item => item.label === label)?.val || 0;
    const renderDetailed = (s: DetailedStat) => `${s.won}/${s.total} (${s.pct.toFixed(1)}%)`;

    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const html = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <title>POST-MATCH ANALYSIS - ${subjectPlayer.name}</title>
        <style>
          @page { size: A4; margin: 20mm; }
          body { font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif; padding: 20px; color: #000; line-height: 1.4; font-size: 13px; }
          h1 { font-size: 32px; font-weight: 900; margin-bottom: 30px; border-bottom: 4px solid #000; padding-bottom: 5px; letter-spacing: -0.5px; text-transform: uppercase; }
          .meta-info { margin-bottom: 40px; }
          .meta-info div { display: flex; margin-bottom: 4px; }
          .meta-info label { font-weight: 900; width: 120px; text-transform: uppercase; }
          .section-header { font-weight: 900; font-size: 16px; margin: 30px 0 20px; text-transform: uppercase; border-bottom: 1px solid #000; padding-bottom: 3px; }
          .stats-container { display: grid; grid-template-columns: 1fr 1fr; gap: 50px; }
          .stat-group { margin-bottom: 25px; }
          .stat-group h3 { font-size: 15px; font-weight: 900; margin-bottom: 12px; border-left: 5px solid #0F5CCE; padding-left: 10px; }
          .stat-row { display: flex; justify-content: space-between; margin-bottom: 5px; }
          .stat-row .label { display: flex; align-items: center; }
          .stat-row .label::before { content: "•"; margin-right: 8px; font-weight: bold; }
          .stat-row .value { font-weight: bold; }
          .total-row { font-style: italic; border-top: 1px dashed #ccc; padding-top: 4px; margin-top: 4px; }
          .notes-section { margin-top: 40px; border-top: 2px solid #000; padding-top: 20px; }
          .notes-section h3 { font-weight: 900; text-transform: uppercase; margin-bottom: 10px; }
          .footer { position: fixed; bottom: 20px; left: 40px; right: 40px; display: flex; justify-content: space-between; font-size: 11px; color: #666; border-top: 1px solid #eee; padding-top: 10px; }
          @media print { .no-print { display: none; } .footer { position: absolute; bottom: 0; } }
        </style>
      </head>
      <body>
        <h1>POST-MATCH ANALYSIS</h1>

        <div class="meta-info">
          <div><label>NAME:</label> <span>${subjectPlayer.name}</span></div>
          <div><label>OPPONENT:</label> <span>${opponentPlayer.name}</span></div>
          <div><label>ROUND #:</label> <span>${config.round || 'N/A'}</span></div>
          <div><label>SCORE:</label> <span>${finalScoreStr}</span></div>
        </div>

        <div class="section-header">MATCH STATISTICS:</div>

        <div class="stats-container">
          <div class="left-col">
            <div class="stat-group">
              <h3>Serve Statistics</h3>
              <div class="stat-row"><span class="label">1st Serve %:</span><span class="value">${subjectStats.firstServePercentage.pct.toFixed(1)}%</span></div>
              <div class="stat-row"><span class="label">2nd Serve %:</span><span class="value">${subjectStats.secondServePercentage.pct.toFixed(1)}%</span></div>
              <div class="stat-row"><span class="label">Aces:</span><span class="value">${subjectStats.aces}</span></div>
              <div class="stat-row"><span class="label">Double Faults:</span><span class="value">${subjectStats.doubleFaults}</span></div>
              <div class="stat-row"><span class="label">1st Serve Points Won:</span><span class="value">${renderDetailed(subjectStats.firstServePointsWon)}</span></div>
