                <div className="relative">
                  <select 
                    value={p1PartnerId} 
                    onChange={(e) => setP1PartnerId(e.target.value)}
                    className="w-full bg-[#E9E9EB] p-3.5 rounded-lg text-[16px] border-none appearance-none outline-none"
                  >
                    <option value="">Team 1, Player 2</option>
                    {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
                </div>
              )}
            </div>
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>{isSingles ? 'Opponent' : 'Team 2 Players'}</SectionLabel>
          <Card>
            <div className="p-4 space-y-3">
              <div className="relative">
                <select 
                  value={p2Id} 
                  onChange={(e) => setP2Id(e.target.value)}
                  className="w-full bg-[#E9E9EB] p-3.5 rounded-lg text-[16px] border-none appearance-none outline-none"
                >
                  <option value="">{isSingles ? 'Player Two' : 'Team 2, Player 1'}</option>
                  {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </div>
              {!isSingles && (
                <div className="relative">
                  <select 
                    value={p2PartnerId} 
                    onChange={(e) => setP2PartnerId(e.target.value)}
                    className="w-full bg-[#E9E9EB] p-3.5 rounded-lg text-[16px] border-none appearance-none outline-none"
                  >
                    <option value="">Team 2, Player 2</option>
                    {players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
                </div>
              )}
            </div>
          </Card>
        </section>

        {allSelectedPlayers.length > 0 && (
          <section className="mt-6">
            <SectionLabel>Initial Server</SectionLabel>
            <Card className="p-4">
              <div className="grid grid-cols-2 gap-2">
                {allSelectedPlayers.map(p => (
                  <button 
                    key={p.id}
                    onClick={() => setServerId(p.id)}
                    className={`py-3 text-xs font-bold rounded-lg transition-all ${serverId === p.id ? 'bg-primary text-white' : 'bg-iosBg text-black/60'}`}
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </Card>
          </section>
        )}

        <section className="mt-6">
          <SectionLabel>Number of Sets</SectionLabel>
          <Card className="p-4">
            <SegmentedControl
              options={[
                { label: '1', value: 1 },
                { label: '3', value: 3 },
                { label: '5', value: 5 },
                { label: 'Pro Set', value: 'Pro Set' },
                { label: 'Fast4', value: 'Fast4' }
              ]}
              value={numSets}
              onChange={(v: any) => setNumSets(v)}
            />
          </Card>
        </section>

        {showDecidingSetOption && (
          <section className="mt-6">
            <SectionLabel>Deciding Set Format</SectionLabel>
            <Card className="p-4">
              <SegmentedControl
                options={[
                  { label: 'Full Set', value: 'Full Set' },
                  { label: 'Super Tiebreak (10pt)', value: 'Super Tiebreak' }
                ]}
                value={decidingSetFormat}
                onChange={(v: any) => setDecidingSetFormat(v)}
              />
            </Card>
          </section>
        )}

        <section className="mt-6">
          <SectionLabel>Number of Games per Set</SectionLabel>
          <Card className="p-4 pt-6">
            <input 
              type="range" 
              min="2" 
              max="10" 
              value={gamesPerSet} 
              onChange={(e) => setGamesPerSet(parseInt(e.target.value))}
              className="w-full accent-primary h-1 bg-iosBg rounded-lg appearance-none cursor-pointer mb-6"
            />
            <div className="flex justify-between px-1 text-xs font-bold text-iosGray">
              {[2,3,4,5,6,7,8,9,10].map(n => (
                <span key={n} className={gamesPerSet === n ? 'text-primary' : ''}>{n}</span>
              ))}
            </div>
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Scoring Type</SectionLabel>
          <Card className="p-4">
            <SegmentedControl
              options={[{ label: 'Simple', value: 'Simple' }, { label: 'Shot Stats', value: 'Shot Stats' }]}
              value={scoringType}
              onChange={(v: any) => setScoringType(v)}
            />
          </Card>
        </section>

        <section className="mt-6">
          <SectionLabel>Match Options</SectionLabel>
          <Card className="p-4 space-y-4">
            <SegmentedControl
              options={[{ label: 'Ad Scoring', value: 'ad' }, { label: 'No-Ad Scoring', value: 'no-ad' }]}
              value={adScoring ? 'ad' : 'no-ad'}
              onChange={(v) => setAdScoring(v === 'ad')}
            />
            <SegmentedControl
              options={[{ label: 'Tie Break', value: 'tb' }, { label: 'No Tie Break', value: 'no-tb' }]}
              value={tieBreak ? 'tb' : 'no-tb'}
              onChange={(v) => setTieBreak(v === 'tb')}
            />
          </Card>
        </section>

        <section className="mt-6 pb-12">
          <SectionLabel>Match Details</SectionLabel>
          <Card className="divide-y divide-iosDivider/30">
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">Description</span>
              <input type="text" placeholder="e.g. Club Championship" value={description} onChange={e=>setDescription(e.target.value)} className="text-right text-iosGray border-none focus:ring-0 text-[16px] bg-transparent outline-none appearance-none" />
            </div>
            <div className="flex items-center px-4 py-3 justify-between">
              <span className="text-[16px] font-medium">Round</span>
              <input type="text" placeholder="e.g. Final" value={round} onChange={e=>setRound(e.target.value)} className="text-right text-iosGray border-none focus:ring-0 text-[16px] bg-transparent outline-none appearance-none" />
            </div>
          </Card>
        </section>
      </div>
    </div>
  );
};

export default SetupView;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame, getFinalScoreString } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  initialNotes?: string;
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUpdateNotes?: (notes: string) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  initialNotes = "",
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUpdateNotes,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);
  const [notes, setNotes] = React.useState(initialNotes);
  const [isNotesOpen, setIsNotesOpen] = React.useState(false);
  const [showExportPrompt, setShowExportPrompt] = React.useState(false);
  const [exportStep, setExportStep] = React.useState<'player' | 'format'>('player');
  const [selectedPlayerId, setSelectedPlayerId] = React.useState<string | null>(null);
  const [exportRound, setExportRound] = React.useState(config.round || '');

  const [score, setScore] = React.useState<CurrentScore>(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false, isSuperTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  React.useEffect(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false, isSuperTieBreak: false
    };
    points.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
  }, [config, points]);

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [doublesPicker, setDoublesPicker] = React.useState<{ show: boolean; team: 'T1' | 'T2'; side: 'Winner' | 'Loser' }>({ show: false, team: 'T1', side: 'Winner' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const team1 = [players.find(p => p.id === config.p1Id)!, players.find(p => p.id === config.p1PartnerId)].filter(Boolean) as Player[];
  const team2 = [players.find(p => p.id === config.p2Id)!, players.find(p => p.id === config.p2PartnerId)].filter(Boolean) as Player[];

  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, config);

  const handlePointClick = (winningTeam: 'T1' | 'T2') => {
    if (isReadOnly || score.isMatchOver) return;

    if (config.matchType === 'Doubles') {
      setDoublesPicker({ show: true, team: winningTeam, side: 'Winner' });
    } else {
      const winnerId = winningTeam === 'T1' ? team1[0].id : team2[0].id;
      const loserId = winningTeam === 'T1' ? team2[0].id : team1[0].id;
      setPointModal({ show: true, winnerId, loserId });
    }
  };

  const handleDoublesPlayerSelect = (playerId: string) => {
    if (doublesPicker.side === 'Winner') {
      const opposingTeam = doublesPicker.team === 'T1' ? 'T2' : 'T1';
      setDoublesPicker({ ...doublesPicker, side: 'Loser' });
      setPointModal({ ...pointModal, winnerId: playerId });
    } else {
      setPointModal({ ...pointModal, loserId: playerId, show: true });
      setDoublesPicker({ show: false, team: 'T1', side: 'Winner' });
    }
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
    setDoublesPicker({ show: false, team: 'T1', side: 'Winner' });
  };

  const handleUndo = () => {
    if (points.length === 0) return;
    const newPoints = points.slice(0, -1);
    setPoints(newPoints);
    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };
    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    resetModalState();
    if (onFinish && calculateNewScore(score, pointModal.winnerId, config.p1Id, config.p2Id, config).isMatchOver) onFinish(newPoints);
    else if (onPause) onPause(newPoints);
  };

  const generateReportHTML = (playerId: string) => {
    const subjectPlayer = players.find(p => p.id === playerId)!;
    const isSubjectT1 = playerId === config.p1Id || playerId === config.p1PartnerId;
    const subjectStats = isSubjectT1 ? stats.p1 : stats.p2;
    const finalScoreStr = getFinalScoreString(points, config);

    const logoSVG = `
      <svg width="340" height="60" viewBox="0 0 500 80" xmlns="http://www.w3.org/2000/svg">
        <text x="0" y="55" font-family="Arial Black, sans-serif" font-size="44" fill="#0F5CCE" font-style="italic" font-weight="900" letter-spacing="2">NEXT TENNIS PRO</text>
      </svg>
    `;

    return `
      <html>
      <head><meta charset="utf-8"></head>
      <body style="font-family: Arial; padding: 20px;">
        <div style="text-align: center;">${logoSVG}</div>
        <h1>Analysis for ${subjectPlayer.name}</h1>
        <p>Final Score: ${finalScoreStr}</p>
        <hr/>
        <h3>Key Statistics</h3>
        <p>1st Serve: ${subjectStats.firstServePercentage.pct.toFixed(1)}%</p>
        <p>Aces: ${subjectStats.aces}</p>
        <p>Winners: ${subjectStats.winners}</p>
        <p>Unforced Errors: ${subjectStats.unforcedErrors}</p>
        <p>Total Points Won: ${subjectStats.totalPointsWon}</p>
      </body>
      </html>
    `;
  };

  const exportMatch = (format: 'pdf' | 'doc') => {
    if (!selectedPlayerId) return;
    const html = generateReportHTML(selectedPlayerId);
    if (format === 'pdf') {
      const printWindow = window.open('', '_blank');
      if (printWindow) {
        printWindow.document.write(html);
        printWindow.document.close();
        setTimeout(() => printWindow.print(), 500);
      }
    }
    setShowExportPrompt(false);
  };

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg' 
          : 'bg-white text-primary border-primary'
      } ${className}`}
    >
      {label}
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-iosBg relative overflow-hidden">
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-[70]">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary relative">
          <button onClick={handleUndo} disabled={points.length === 0} className={points.length === 0 ? 'opacity-30' : ''}>
            <i className="fa-solid fa-rotate-left"></i>
          </button>
          <button onClick={() => setShowMoreMenu(!showMoreMenu)}>
            <i className="fa-solid fa-ellipsis"></i>
          </button>
        </div>
      </header>

      {showMoreMenu && (
        <div className="fixed inset-0 z-[65]" onClick={() => setShowMoreMenu(false)}>
           <div className="absolute right-4 top-20 w-52 bg-white border border-iosDivider rounded-xl shadow-2xl py-1 z-[80]">
                <button onClick={() => { setShowMoreMenu(false); onEditSettings?.(config); }} className="w-full text-left px-4 py-4 text-sm font-semibold border-b border-iosDivider/10">Edit Match Settings</button>
                <button onClick={() => { setShowExportPrompt(true); setShowMoreMenu(false); }} className="w-full text-left px-4 py-4 text-sm font-semibold">Export Match</button>
            </div>
        </div>
      )}

      <div className="flex-1 overflow-y-auto pb-44">
        <div className="p-4">
          <Card className="p-0 border-none shadow-md overflow-hidden bg-white">
            <div className="bg-primary text-white px-4 py-2.5 text-[10px] font-bold uppercase tracking-widest">
              {config.matchType} Match
            </div>
            <div className="p-4 space-y-4">
              <div className="flex justify-between items-center">
                <div className="flex flex-col">
                  <span className="text-sm font-bold">{team1.map(p => p.name).join(' / ')}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((s, idx) => <span key={idx} className="text-iosGray text-sm font-bold">{s.p1}</span>)}
                  <span className="font-black text-xl tabular-nums">{score.p1Games}</span>
                </div>
              </div>
              <div className="flex justify-between items-center">
                <div className="flex flex-col">
                  <span className="text-sm font-bold">{team2.map(p => p.name).join(' / ')}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((s, idx) => <span key={idx} className="text-iosGray text-sm font-bold">{s.p2}</span>)}
                  <span className="font-black text-xl tabular-nums">{score.p2Games}</span>
                </div>
              </div>
            </div>
          </Card>
        </div>

        <div className="px-6 pb-6 pt-2 flex justify-between relative items-center">
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick('T1')}>
            {!score.isMatchOver && [config.p1Id, config.p1PartnerId].includes(score.servingPlayerId) && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute left-4 top-2 animate-pulse"></div>}
            <span className="text-8xl scoreboard-font text-primary tracking-tighter tabular-nums">{score.p1Points}</span>
          </div>
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick('T2')}>
            {!score.isMatchOver && [config.p2Id, config.p2PartnerId].includes(score.servingPlayerId) && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-4 top-2 animate-pulse"></div>}
            <span className="text-8xl scoreboard-font text-black tracking-tighter tabular-nums">{score.p2Points}</span>
          </div>
        </div>

        {!isReadOnly && !score.isMatchOver && (
          <div className="px-4 mb-6">
            <SegmentedControl options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]} value={serveNumber} onChange={(v: any) => setServeNumber(v)} />
          </div>
        )}

        <div className="px-4">
          {activeSubTab === 'Match Stats' && (
            <Card className="divide-y divide-iosDivider/10 bg-transparent border-none">
              <StatRow label="1st serve %" val1={stats.p1.firstServePercentage} val2={stats.p2.firstServePercentage} isPercentOnly />
              <StatRow label="aces" val1={stats.p1.aces} val2={stats.p2.aces} />
              <StatRow label="winners" val1={stats.p1.winners} val2={stats.p2.winners} />
              <StatRow label="unforced errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
              <StatRow label="total points won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
            </Card>
          )}
          {activeSubTab === 'Shot Stats' && (
            <div className="space-y-6">
              <ShotSection title="Winners" rows={calculateShotBreakdown(points, config, 'Winner')} />
              <ShotSection title="Forced Errors" rows={calculateShotBreakdown(points, config, 'Forced Error')} />
              <ShotSection title="Unforced Errors" rows={calculateShotBreakdown(points, config, 'Unforced Error')} />
            </div>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-iosDivider/30 flex justify-around px-4 pt-4 pb-10 z-50">
        <button onClick={() => setActiveSubTab('Match Stats')} className="flex flex-col items-center gap-1 flex-1">
          <i className={`fa-solid fa-chart-simple text-xl ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className="text-[9px] font-black uppercase">Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Shot Stats')} className="flex flex-col items-center gap-1 flex-1">
          <i className={`fa-solid fa-magnifying-glass text-xl ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className="text-[9px] font-black uppercase">Shots</span>
        </button>
        <button onClick={() => setActiveSubTab('Match Log')} className="flex flex-col items-center gap-1 flex-1">
          <i className={`fa-solid fa-list-ul text-xl ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className="text-[9px] font-black uppercase">Log</span>
        </button>
      </div>

      {doublesPicker.show && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6" onClick={() => resetModalState()}>
          <div className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-black uppercase text-center mb-6">
              Select {doublesPicker.side}
            </h3>
            <div className="space-y-4">
              {(doublesPicker.side === 'Winner' 
                ? (doublesPicker.team === 'T1' ? team1 : team2) 
                : (doublesPicker.team === 'T1' ? team2 : team1)
              ).map(p => (
                <button 
                  key={p.id}
                  onClick={() => handleDoublesPlayerSelect(p.id)}
                  className="w-full py-4 bg-primary text-white font-bold rounded-2xl shadow-lg uppercase"
                >
                  {p.name}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col pt-20">
          <div className="flex-1 overflow-y-auto px-6 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8 uppercase">Point Outcome</h2>
            <div className="grid grid-cols-2 gap-3 mb-6">
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => setOutcome('Winner')} />
              <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => setOutcome('Ace')} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => setOutcome('Unforced Error')} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => setOutcome('Forced Error')} />
              <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => setOutcome('Double Fault')} />
            </div>

            {(outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error') && (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2">
                <div>
                  <h3 className="text-[12px] text-center font-bold uppercase mb-4">Side</h3>
                  <div className="grid grid-cols-2 gap-3">
                    <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                    <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                  </div>
                </div>
                <div>
                  <h3 className="text-[12px] text-center font-bold uppercase mb-4">Shot Type</h3>
                  <div className="grid grid-cols-3 gap-2">
                    {['Regular', 'Volley', 'Slice', 'Passing', 'Drop Shot', 'Lob'].map(k => (
                      <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k as any)} className="text-[12px] py-2" />
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0">
            <button onClick={resetModalState} className="flex-1 py-4 bg-[#FF3B30] text-white font-bold rounded-2xl uppercase">Cancel</button>
            <button onClick={handleSavePoint} className="flex-1 py-4 bg-primary text-white font-bold rounded-2xl uppercase">Save</button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(1)}%</span>;
      return <div className="flex flex-col items-center"><span className="text-[13px] font-bold text-black">{detailed.won}/{detailed.total}</span></div>;
    }
    return <span className="text-[14px] font-bold text-black">{val}</span>;
  };
  return <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 bg-white">
    <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
    <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center uppercase">{label}</span>
    <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
  </div>;
};

const ShotSection: React.FC<{ title: string; rows: any[] }> = ({ title, rows }) => (
  <section className="mb-4">
    <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-4 tracking-widest">{title}</h4>
    <Card className="divide-y divide-iosDivider/10 bg-white shadow-none border-t border-b border-iosDivider/30 rounded-none">
      {rows.map((row, i) => (
        <div key={i} className="flex justify-between items-center px-4 py-3.5">
          <span className="text-[13px] w-12 text-left tabular-nums font-medium">{row.p1}</span>
          <span className="text-[12px] flex-1 text-center font-medium">{row.label}</span>
          <span className="text-[13px] w-12 text-right tabular-nums font-medium">{row.p2}</span>
        </div>
      ))}
    </Card>
  </section>
);

export default ActiveMatchView;

import React from 'react';
import { MatchConfig, Player, Point, Outcome, ShotKind, ShotLocation, ErrorType, ServePlacement } from '../types';
import { Card, SegmentedControl } from '../components/UI';
import { CurrentScore, calculateNewScore, calculateStats, DetailedStat, calculateShotBreakdown, getPointDescription, isWinningPointOfGame, getFinalScoreString } from '../logic/tennisLogic';

interface ActiveMatchViewProps {
  config: MatchConfig;
  players: Player[];
  initialPoints?: Point[];
  initialNotes?: string;
  onFinish?: (points: Point[]) => void;
  onPause?: (points: Point[]) => void;
  onCancel: () => void;
  onEditSettings?: (config: MatchConfig) => void;
  onUpdateNotes?: (notes: string) => void;
  onUndo?: (points: Point[]) => void;
  isReadOnly?: boolean;
}

const ActiveMatchView: React.FC<ActiveMatchViewProps> = ({ 
  config, 
  players, 
  initialPoints = [], 
  initialNotes = "",
  onFinish, 
  onPause,
  onCancel, 
  onEditSettings,
  onUpdateNotes,
  onUndo,
  isReadOnly = false 
}) => {
  const [points, setPoints] = React.useState<Point[]>(initialPoints);
  const [notes, setNotes] = React.useState(initialNotes);
  const [isNotesOpen, setIsNotesOpen] = React.useState(false);
  const [showExportPrompt, setShowExportPrompt] = React.useState(false);
  const [exportStep, setExportStep] = React.useState<'player' | 'format'>('player');
  const [selectedPlayerId, setSelectedPlayerId] = React.useState<string | null>(null);
  const [exportRound, setExportRound] = React.useState(config.round || '');

  const [score, setScore] = React.useState<CurrentScore>(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false, isSuperTieBreak: false
    };
    initialPoints.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    return current;
  });

  React.useEffect(() => {
    let current: CurrentScore = {
      p1Points: '0', p2Points: '0', p1Games: 0, p2Games: 0, p1Sets: 0, p2Sets: 0, setHistory: [],
      servingPlayerId: config.initialServerId, isGameOver: false, isSetOver: false, isMatchOver: false, isTieBreak: false, isSuperTieBreak: false
    };
    points.forEach(p => {
      current = calculateNewScore(current, p.winnerId, config.p1Id, config.p2Id, config);
    });
    setScore(current);
  }, [config, points]);

  const [serveNumber, setServeNumber] = React.useState<1 | 2>(1);
  const [activeSubTab, setActiveSubTab] = React.useState<'Match Stats' | 'Shot Stats' | 'Match Log'>('Match Stats');
  const [pointModal, setPointModal] = React.useState<{ show: boolean; winnerId: string; loserId: string }>({ show: false, winnerId: '', loserId: '' });
  const [showMoreMenu, setShowMoreMenu] = React.useState(false);

  const team1 = [players.find(p => p.id === config.p1Id)!, players.find(p => p.id === config.p1PartnerId)].filter(Boolean) as Player[];
  const team2 = [players.find(p => p.id === config.p2Id)!, players.find(p => p.id === config.p2PartnerId)].filter(Boolean) as Player[];

  const [outcome, setOutcome] = React.useState<Outcome | null>(null);
  const [shotSide, setShotSide] = React.useState<'Forehand' | 'Backhand' | null>(null);
  const [shotKind, setShotKind] = React.useState<ShotKind | null>(null);
  const [location, setLocation] = React.useState<ShotLocation | null>(null);
  const [errorType, setErrorType] = React.useState<ErrorType | null>(null);
  const [servePlacement, setServePlacement] = React.useState<ServePlacement | null>(null);
  const [rallyLength, setRallyLength] = React.useState(0);

  const stats = calculateStats(points, config);

  const handlePointClick = (winningTeam: 'T1' | 'T2') => {
    if (isReadOnly || score.isMatchOver) return;

    // As per user request: for doubles, just track which team won.
    // We attribute the point to the primary player of the team for tracking, 
    // but the calculateStats logic treats the team as a single unit.
    const winnerId = winningTeam === 'T1' ? config.p1Id : config.p2Id;
    const loserId = winningTeam === 'T1' ? config.p2Id : config.p1Id;

    setPointModal({ show: true, winnerId, loserId });
  };

  const resetModalState = () => {
    setPointModal({ show: false, winnerId: '', loserId: '' });
    setOutcome(null);
    setShotSide(null);
    setShotKind(null);
    setLocation(null);
    setErrorType(null);
    setServePlacement(null);
    setRallyLength(0);
    setServeNumber(1);
  };

  const handleUndo = () => {
    if (points.length === 0) return;
    const newPoints = points.slice(0, -1);
    setPoints(newPoints);
    if (onUndo) onUndo(newPoints);
  };

  const handleSavePoint = () => {
    const finalOutcome = outcome || 'Winner';
    const newPoint: Point = {
      winnerId: pointModal.winnerId,
      loserId: pointModal.loserId,
      outcome: finalOutcome,
      serverPlayerId: score.servingPlayerId,
      serveNumber,
      shotSide: shotSide || undefined,
      shotKind: shotKind || undefined,
      location: location || undefined,
      errorType: errorType || undefined,
      servePlacement: servePlacement || undefined,
      rallyLength,
      scoreAtStart: {
        p1Points: score.p1Points,
        p2Points: score.p2Points,
        p1Games: score.p1Games,
        p2Games: score.p2Games,
        p1Sets: score.p1Sets,
        p2Sets: score.p2Sets,
      }
    };
    const newPoints = [...points, newPoint];
    setPoints(newPoints);
    resetModalState();
    if (onFinish && calculateNewScore(score, pointModal.winnerId, config.p1Id, config.p2Id, config).isMatchOver) onFinish(newPoints);
    else if (onPause) onPause(newPoints);
  };

  const generateReportHTML = (playerId: string) => {
    const subjectPlayer = players.find(p => p.id === playerId)!;
    const isSubjectT1 = playerId === config.p1Id || playerId === config.p1PartnerId;
    const subjectStats = isSubjectT1 ? stats.p1 : stats.p2;
    const finalScoreStr = getFinalScoreString(points, config);

    const logoSVG = `
      <svg width="340" height="60" viewBox="0 0 500 80" xmlns="http://www.w3.org/2000/svg">
        <text x="0" y="55" font-family="Arial Black, sans-serif" font-size="44" fill="#0F5CCE" font-style="italic" font-weight="900" letter-spacing="2">NEXT TENNIS PRO</text>
      </svg>
    `;

    return `
      <html>
      <head><meta charset="utf-8"></head>
      <body style="font-family: Arial; padding: 20px;">
        <div style="text-align: center;">${logoSVG}</div>
        <h1>Analysis for ${subjectPlayer.name}</h1>
        <p>Final Score: ${finalScoreStr}</p>
        <hr/>
        <h3>Key Statistics</h3>
        <p>1st Serve: ${subjectStats.firstServePercentage.pct.toFixed(1)}%</p>
        <p>Aces: ${subjectStats.aces}</p>
        <p>Winners: ${subjectStats.winners}</p>
        <p>Unforced Errors: ${subjectStats.unforcedErrors}</p>
        <p>Total Points Won: ${subjectStats.totalPointsWon}</p>
      </body>
      </html>
    `;
  };

  const exportMatch = (format: 'pdf' | 'doc') => {
    const pId = config.p1Id; // Default to P1 for export if no selection
    const html = generateReportHTML(pId);
    if (format === 'pdf') {
      const printWindow = window.open('', '_blank');
      if (printWindow) {
        printWindow.document.write(html);
        printWindow.document.close();
        setTimeout(() => printWindow.print(), 500);
      }
    }
    setShowExportPrompt(false);
  };

  const BlueBtn: React.FC<{ label: string; active: boolean; onClick: () => void; className?: string }> = ({ label, active, onClick, className = "" }) => (
    <button 
      onClick={onClick}
      className={`py-3.5 px-4 rounded-xl font-bold transition-all duration-200 border-2 text-[15px] ${
        active 
          ? 'bg-primary text-white border-primary shadow-lg ring-2 ring-primary/20' 
          : 'bg-white text-primary border-primary hover:bg-primary/5 active:scale-[0.98]'
      } ${className}`}
    >
      {label}
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-iosBg relative overflow-hidden">
      <header className="px-4 pt-10 pb-4 flex justify-between items-center border-b border-iosDivider/20 bg-white/80 backdrop-blur-md sticky top-0 z-[70]">
        <button onClick={onCancel} className="text-primary flex items-center gap-1 font-semibold">
          <i className="fa-solid fa-chevron-left text-sm"></i> Matches
        </button>
        <div className="flex items-center gap-4 text-primary relative">
          <button onClick={handleUndo} disabled={points.length === 0} className={points.length === 0 ? 'opacity-30' : 'active:scale-90 transition-transform'}>
            <i className="fa-solid fa-rotate-left"></i>
          </button>
          <button onClick={() => setShowMoreMenu(!showMoreMenu)} className="active:scale-90 transition-transform">
            <i className="fa-solid fa-ellipsis"></i>
          </button>
        </div>
      </header>

      {showMoreMenu && (
        <div className="fixed inset-0 z-[65]" onClick={() => setShowMoreMenu(false)}>
           <div className="absolute right-4 top-20 w-52 bg-white border border-iosDivider rounded-xl shadow-2xl py-1 z-[80] overflow-hidden animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                <button onClick={() => { setShowMoreMenu(false); onEditSettings?.(config); }} className="w-full text-left px-4 py-4 text-sm font-semibold border-b border-iosDivider/10 hover:bg-iosBg">Edit Match Settings</button>
                <button onClick={() => { setShowExportPrompt(true); setShowMoreMenu(false); }} className="w-full text-left px-4 py-4 text-sm font-semibold hover:bg-iosBg">Export Match</button>
            </div>
        </div>
      )}

      <div className="flex-1 overflow-y-auto pb-44">
        <div className="p-4">
          <Card className="p-0 border-none shadow-md overflow-hidden bg-white">
            <div className="bg-primary text-white px-4 py-2.5 text-[10px] font-bold uppercase tracking-widest flex justify-between items-center">
              <span>{config.matchType} Match</span>
              <span className="opacity-60">{new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}</span>
            </div>
            <div className="p-4 space-y-4">
              <div className="flex justify-between items-center">
                <div className="flex flex-col">
                  <span className="text-sm font-bold text-black/90">{team1.map(p => p.name).join(' / ')}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((s, idx) => <span key={idx} className="text-iosGray text-sm font-bold opacity-60">{s.p1}</span>)}
                  <span className="font-black text-xl tabular-nums">{score.p1Games}</span>
                </div>
              </div>
              <div className="flex justify-between items-center">
                <div className="flex flex-col">
                  <span className="text-sm font-bold text-black/90">{team2.map(p => p.name).join(' / ')}</span>
                </div>
                <div className="flex items-center gap-2">
                  {score.setHistory.map((s, idx) => <span key={idx} className="text-iosGray text-sm font-bold opacity-60">{s.p2}</span>)}
                  <span className="font-black text-xl tabular-nums">{score.p2Games}</span>
                </div>
              </div>
            </div>
          </Card>
        </div>

        <div className="px-6 pb-6 pt-2 flex justify-between relative items-center">
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick('T1')}>
            {!score.isMatchOver && [config.p1Id, config.p1PartnerId].filter(Boolean).includes(score.servingPlayerId) && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute left-4 top-2 animate-pulse"></div>}
            <span className="text-8xl scoreboard-font text-primary tracking-tighter tabular-nums transition-transform active:scale-95">{score.p1Points}</span>
          </div>
          <div className="flex flex-col items-center flex-1 cursor-pointer" onClick={() => handlePointClick('T2')}>
            {!score.isMatchOver && [config.p2Id, config.p2PartnerId].filter(Boolean).includes(score.servingPlayerId) && <div className="w-2.5 h-2.5 bg-yellow-400 rounded-full absolute right-4 top-2 animate-pulse"></div>}
            <span className="text-8xl scoreboard-font text-black tracking-tighter tabular-nums transition-transform active:scale-95">{score.p2Points}</span>
          </div>
        </div>

        {!isReadOnly && !score.isMatchOver && (
          <div className="px-4 mb-6">
            <SegmentedControl options={[{ label: 'First Serve', value: 1 }, { label: 'Second Serve', value: 2 }]} value={serveNumber} onChange={(v: any) => setServeNumber(v)} />
          </div>
        )}

        <div className="px-4">
          {activeSubTab === 'Match Stats' && (
            <Card className="divide-y divide-iosDivider/10 bg-transparent border-none shadow-none rounded-none">
              <StatRow label="1st serve %" val1={stats.p1.firstServePercentage} val2={stats.p2.firstServePercentage} isPercentOnly />
              <StatRow label="aces" val1={stats.p1.aces} val2={stats.p2.aces} />
              <StatRow label="winners" val1={stats.p1.winners} val2={stats.p2.winners} />
              <StatRow label="unforced errors" val1={stats.p1.unforcedErrors} val2={stats.p2.unforcedErrors} />
              <StatRow label="total points won" val1={stats.p1.totalPointsWon} val2={stats.p2.totalPointsWon} />
            </Card>
          )}
          {activeSubTab === 'Shot Stats' && (
            <div className="space-y-6">
              <ShotSection title="Winners" rows={calculateShotBreakdown(points, config, 'Winner')} />
              <ShotSection title="Forced Errors" rows={calculateShotBreakdown(points, config, 'Forced Error')} />
              <ShotSection title="Unforced Errors" rows={calculateShotBreakdown(points, config, 'Unforced Error')} />
            </div>
          )}
          {activeSubTab === 'Match Log' && (
            <div className="bg-white rounded-xl overflow-hidden border border-iosDivider/20 mb-10">
              {points.slice().reverse().map((p, i) => (
                <div key={i} className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10">
                  <div className="w-12 text-primary font-black text-[13px]">{p.scoreAtStart.p1Points}</div>
                  <div className="flex-1 px-4 text-center text-[12px] font-medium text-black/80">{getPointDescription(p, players)}</div>
                  <div className="w-12 text-right font-black text-[13px]">{p.scoreAtStart.p2Points}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-iosDivider/30 flex justify-around px-4 pt-4 pb-10 z-50 shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <button onClick={() => setActiveSubTab('Match Stats')} className="flex flex-col items-center gap-1.5 flex-1 transition-all active:scale-90">
          <i className={`fa-solid fa-chart-simple text-xl ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase ${activeSubTab === 'Match Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Stats</span>
        </button>
        <button onClick={() => setActiveSubTab('Shot Stats')} className="flex flex-col items-center gap-1.5 flex-1 transition-all active:scale-90">
          <i className={`fa-solid fa-magnifying-glass text-xl ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase ${activeSubTab === 'Shot Stats' ? 'text-primary' : 'text-iosGray/70'}`}>Shots</span>
        </button>
        <button onClick={() => setActiveSubTab('Match Log')} className="flex flex-col items-center gap-1.5 flex-1 transition-all active:scale-90">
          <i className={`fa-solid fa-list-ul text-xl ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/40'}`}></i>
          <span className={`text-[9px] font-black uppercase ${activeSubTab === 'Match Log' ? 'text-primary' : 'text-iosGray/70'}`}>Log</span>
        </button>
      </div>

      {pointModal.show && (
        <div className="fixed inset-0 bg-white z-[100] flex flex-col pt-20 animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="flex-1 overflow-y-auto px-6 pb-40">
            <h2 className="text-[18px] text-center font-bold mb-8 uppercase tracking-tight">Point Outcome</h2>
            <div className="grid grid-cols-2 gap-3 mb-6">
              <BlueBtn label="Winner" active={outcome === 'Winner'} onClick={() => setOutcome('Winner')} />
              <BlueBtn label="Ace" active={outcome === 'Ace'} onClick={() => setOutcome('Ace')} />
              <BlueBtn label="Unforced Error" active={outcome === 'Unforced Error'} onClick={() => setOutcome('Unforced Error')} />
              <BlueBtn label="Forced Error" active={outcome === 'Forced Error'} onClick={() => setOutcome('Forced Error')} />
              <BlueBtn label="Double Fault" active={outcome === 'Double Fault'} onClick={() => setOutcome('Double Fault')} />
            </div>

            {(outcome === 'Winner' || outcome === 'Unforced Error' || outcome === 'Forced Error') && (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
                <div>
                  <h3 className="text-[12px] text-center font-bold uppercase mb-4 text-iosGray">Side</h3>
                  <div className="grid grid-cols-2 gap-3">
                    <BlueBtn label="Forehand" active={shotSide === 'Forehand'} onClick={() => setShotSide('Forehand')} />
                    <BlueBtn label="Backhand" active={shotSide === 'Backhand'} onClick={() => setShotSide('Backhand')} />
                  </div>
                </div>
                <div>
                  <h3 className="text-[12px] text-center font-bold uppercase mb-4 text-iosGray">Shot Type</h3>
                  <div className="grid grid-cols-3 gap-2">
                    {['Regular', 'Volley', 'Slice', 'Passing', 'Drop Shot', 'Lob'].map(k => (
                      <BlueBtn key={k} label={k} active={shotKind === k} onClick={() => setShotKind(k as any)} className="text-[12px] py-2" />
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
          <div className="bg-white/95 backdrop-blur-md p-6 border-t border-iosDivider flex gap-4 sticky bottom-0 z-[110]">
            <button onClick={resetModalState} className="flex-1 py-4.5 bg-[#FF3B30] text-white font-bold rounded-2xl uppercase tracking-wider shadow-lg active:scale-95 transition-all">Cancel</button>
            <button onClick={handleSavePoint} className="flex-1 py-4.5 bg-primary text-white font-bold rounded-2xl uppercase tracking-wider shadow-lg active:scale-95 transition-all">Save Point</button>
          </div>
        </div>
      )}

      {showExportPrompt && (
        <div className="fixed inset-0 z-[120] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in" onClick={() => setShowExportPrompt(false)}>
          <div className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-in zoom-in-95" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-black uppercase text-primary mb-4 text-center">Export Match</h3>
            <p className="text-iosGray text-sm text-center mb-8 px-4">Generate a detailed report of this match.</p>
            <div className="space-y-4">
               <button onClick={() => exportMatch('pdf')} className="w-full py-4 bg-primary text-white font-bold rounded-2xl shadow-lg active:scale-95 transition-all uppercase tracking-wider">Save as PDF</button>
               <button onClick={() => setShowExportPrompt(false)} className="w-full py-3 text-iosGray font-bold uppercase tracking-widest text-xs">Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatRow: React.FC<{ label: string; val1: any; val2: any; isPercentOnly?: boolean }> = ({ label, val1, val2, isPercentOnly }) => {
  const renderValue = (val: any) => {
    if (typeof val === 'object' && val !== null && 'won' in val) {
      const detailed = val as DetailedStat;
      if (isPercentOnly) return <span className="text-[13px] font-bold text-black">{detailed.pct.toFixed(1)}%</span>;
      return <div className="flex flex-col items-center"><span className="text-[13px] font-bold text-black">{detailed.won}/{detailed.total}</span><span className="text-[10px] text-iosGray">({detailed.pct.toFixed(1)}%)</span></div>;
    }
    return <span className="text-[14px] font-bold text-black">{val}</span>;
  };
  return <div className="flex justify-between items-center px-4 py-4 border-b border-iosDivider/10 bg-white">
    <div className="flex-1 flex justify-start">{renderValue(val1)}</div>
    <span className="text-[12px] text-iosGray font-semibold flex-[1.5] text-center uppercase tracking-tight px-2 leading-tight">{label}</span>
    <div className="flex-1 flex justify-end">{renderValue(val2)}</div>
  </div>;
};

const ShotSection: React.FC<{ title: string; rows: any[] }> = ({ title, rows }) => (
  <section className="mb-4">
    <h4 className="text-[10px] uppercase font-bold text-iosGray mb-2 ml-4 tracking-widest">{title}</h4>
    <Card className="divide-y divide-iosDivider/10 bg-white shadow-none border-t border-b border-iosDivider/30 rounded-none">
      {rows.map((row, i) => (
        <div key={i} className={`flex justify-between items-center px-4 py-3.5 ${row.label === 'Total' ? 'bg-iosBg/30' : ''}`}>
          <span className={`text-[13px] w-12 text-left tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p1}</span>
          <span className={`text-[12px] flex-1 text-center ${row.label === 'Total' ? 'font-black uppercase tracking-widest' : 'text-black font-medium'}`}>{row.label}</span>
          <span className={`text-[13px] w-12 text-right tabular-nums ${row.label === 'Total' ? 'font-black' : 'font-medium'}`}>{row.p2}</span>
        </div>
      ))}
    </Card>
  </section>
);

export default ActiveMatchView;
